 * @file task6.cpp
 * @brief Implements the complex, multi-step conversion of a general propositional formula to Conjunctive Normal Form (CNF).
 *
 * The conversion sequence is:
 * 1. Implication Elimination (impl_free): A > B becomes ~A + B.
 * 2. Negation Normal Form (NNF): Pushing negations inward (using De Morgan's laws and double negation).
 * 3. Distribution (distr and cnf): Applying the distributive law of OR over AND.
 *
 * @page task6_page Task 6: Convert to CNF (Implication Elimination, NNF, Distribution)
 * @ingroup task6_page
 * @details This is the formal logic transformation module, converting any formula into an equivalent CNF form.
 * @subpage task8_page
 */

#include <bits/stdc++.h>
using namespace std;

// Forward declaration for mutual recursion
struct node;
node* cnf(node* root);

// --- Task 2 Structures ---
/**
 * @brief Structure representing a node in the general propositional logic parse tree (char-based).
 * @ingroup task2_page
 */
struct node
{
    char data;
    node* left;
    node* right;

    node(char val)
    {
        data = val;
        left = NULL;
        right = NULL;
    }
};

// --- Task 8 Functions: Memory Cleanup ---

/**
 * @brief Recursively deallocates all nodes in a general propositional logic parse tree.
 * @ingroup task8_page
 * @param root A pointer to the root of the tree to delete.
 */
void deleteTree(node* root)
{
    if (root == NULL) return;
    deleteTree(root->left);
    deleteTree(root->right);
    delete root;
}

// --- Task 6 Helper Functions ---

/**
 * @brief Creates a deep copy of the given parse tree.
 * @ingroup task6_page
 * @param root A pointer to the root of the tree to copy.
 * @return A pointer to the root of the newly created copy.
 * * @complexity
 * Time: O(T), where T is the number of nodes in the tree.
 * Space: O(T), for the newly created tree nodes.
 */
node* copyTree(node* root)
{
    if (root == NULL) return NULL;
    node* n = new node(root->data);
    n->left = copyTree(root->left);
    n->right = copyTree(root->right);
    return n;
}

/**
 * @brief Eliminates all implication operators ('>') from the parse tree.
 * @ingroup task6_page
 * @details Converts A > B to ~A + B.
 * @param root A pointer to the root of the (sub)tree.
 * @return A pointer to the root of the modified (sub)tree.
 * * @complexity
 * Time: O(T), where T is the number of nodes in the tree.
 * Space: O(H), where H is the height of the tree, for the recursion stack.
 */
node* impl_free(node* root)
{
    if (root == NULL)
        return NULL;

    // Recurse first (post-order traversal)
    root->left = impl_free(root->left);
    root->right = impl_free(root->right);

    if (root->data == '>')
    {
        node* a = root->left;
        node* b = root->right;
        delete root;

        node* notA = new node('~');
        notA->right = a;
        node* orNode = new node('+');
        orNode->left = notA;
        orNode->right = b;
        return orNode; // The new '+' node is the replacement root
    }
    return root;
}

