using namespace std;

void Create(int** a, const int k, const int n, const int Low, const int High);
void Print(int** a, const int k, const int n);
bool SearchMinOfMaxOddCols(int** a, const int k, const int n, int& minOfMax);

int main()
{
    srand((unsigned)time(NULL));

    int Low = 5;
    int High = 90;
    int k, n;

    cout << "k (rows) = "; cin >> k;
    cout << "n (cols) = "; cin >> n;

    int** a = new int* [k];
    for (int i = 0; i < k; i++)
        a[i] = new int[n];

    Create(a, k, n, Low, High);
    cout << "\nInitial matrix:\n";
    Print(a, k, n);

    int minOfMax;
    if (SearchMinOfMaxOddCols(a, k, n, minOfMax))
        cout << "Minimum among maximums of odd columns = " << minOfMax << endl;
    else
        cout << "No odd columns found." << endl;

    for (int i = 0; i < k; i++)
        delete[] a[i];
    delete[] a;

    return 0;
}

void Create(int** a, const int k, const int n, const int Low, const int High)
{
    for (int i = 0; i < k; i++)
        for (int j = 0; j < n; j++)
            a[i][j] = Low + rand() % (High - Low + 1);
}

void Print(int** a, const int k, const int n)
{
    cout << endl;
    for (int i = 0; i < k; i++)
    {
        for (int j = 0; j < n; j++)
            cout << setw(5) << a[i][j];
        cout << endl;
    }
    cout << endl;
}

bool SearchMinOfMaxOddCols(int** a, const int k, const int n, int& minOfMax)
{
    bool found = false;

    for (int j = 0; j < n; j += 2)
    {
        int maxInCol = a[0][j];
        for (int i = 1; i < k; i++)
        {
            if (a[i][j] > maxInCol)
                maxInCol = a[i][j];
        }

        if (!found)
        {
            minOfMax = maxInCol;
            found = true;
        }
        else if (maxInCol < minOfMax)
            minOfMax = maxInCol;
    }

    return found;
}

