template <int M, int N>
void test_equals(
        float*(*f0)(float*, float*),
        float*(*f1)(float*, float*),
        float*(*f2)(float*, float*),
        float*(*f3)(float*, float*),
        vec8*(*f4)(float*, float*),
        vec16*(*f5)(float*, float*)
) {
    float *A = randmat(M, N);
    float *B = randmat(M, N);
    float *C0 = f0(A, B);
    float *C1 = f1(A, B);
    float *C2 = f2(A, B);
    float *C3 = f3(A, B);
    vec8 *C4 = f4(A, B);
    vec16 *C5 = f5(A, B);

    for (int i = 0; i < M; ++i) {
        for (int j = 0; j < N; ++j) {
            assert(C0[i * N + j] == C1[i * N + j]);
            assert(C1[i * N + j] == C2[i * N + j]);
            assert(C2[i * N + j] == C3[i * N + j]);
            assert(C3[i * N + j] == C4[i * N / 8 + j / 8][j % 8]);
            assert(C4[i * N / 8 + j / 8][j % 8] == C5[i * N / 16 + j / 16][j % 16]);
        }
    }
}

