      case 2: {
        // Deletes a villager
        if (it != villagerData.end()) {
          villagerData.erase(name);
          cout << endl;
        } else {
          cout << name << " not found.\n";
          cout << endl;
        }
        break;
      }
      case 3: {
        // Increases friendship level of a villager
        if (it != villagerData.end()) {
          get<0>(it->second) = min(max_friendship, get<0>(it->second) + 1);
          cout << name << "'s friendship increased.\n";
          cout << endl;
        } else {
          cout << name << " not found.\n";
          cout << endl;
