        break;
      }

      case 4: {
        // Decreases friendship level of a villager
        if (it != villagerData.end()) {
          get<0>(it->second) = max(min_friendship, get<0>(it->second) - 1);
          cout << name << "'s friendship decreased.\n";
          cout << endl;
        } else {
