    std::cout << "  \"turn_rate_dps\": " << turn.turn_rate_

// SudokuSolver.cpp
// C++17 Sudoku solver using backtracking with bitmasks and MRV heuristic.
// Compile: g++ -std=c++17 SudokuSolver.cpp -O2 -o sudoku
// Usage:
//  - Input: 9 lines, each with 9 characters (digits '1'..'9' or '.' or '0' for empty).
//  - Example:
//    53..7....
//    6..195...
//    .98....6.
//    8...6...3
//    4..8.3..1
//    7...2...6
//    .6....28.
//    ...419..5
//    ....8..79
//
// Output: solved board printed as 9 lines.

#include <bits/stdc++.h>
using namespace std;

struct SudokuSolver {
    // grid: 0 = empty, 1..9 filled
    int grid[9][9];
    // bitmask: bit d (1<<d) means digit d is present (we use d:0..8 -> digits 1..9)
    int rowMask[9], colMask[9], boxMask[9];

    SudokuSolver() {
        memset(grid, 0, sizeof(grid));
        fill(begin(rowMask), end(rowMask), 0);
        fill(begin(colMask), end(colMask), 0);
        fill(begin(boxMask), end(boxMask), 0);
    }

    static inline int boxIndex(int r, int c) {
        return (r/3)*3 + (c/3);
    }

    // set digit d (1..9) at position r,c
    void place(int r, int c, int d) {
        grid[r][c] = d;
        int bit = 1 << (d-1);
        rowMask[r] |= bit;
        colMask[c] |= bit;
        boxMask[boxIndex(r,c)] |= bit;
    }

    // remove digit from r,c (used during backtracking)
    void remove(int r, int c, int d) {
        grid[r][c] = 0;
        int bit = ~(1 << (d-1));
        rowMask[r] &= bit;
        colMask[c] &= bit;
        boxMask[boxIndex(r,c)] &= bit;
    }

    // return bitmask of available candidates (bits 0..8 => digits 1..9)
    int candidatesMask(int r, int c) const {
        int used = rowMask[r] | colMask[c] | boxMask[boxIndex(r,c)];
        return (~used) & 0x1FF; // only 9 bits
    }

    // Convert single-bit mask to digit (1..9). Assumes mask is power of two.
    static inline int maskToDigit(int mask) {
        return __builtin_ctz(mask) + 1;
    }

    // Try to solve. Returns true if solved.
    bool solve() {
        // find an empty cell with minimum candidates (MRV)
        int br=-1, bc=-1, bestCount = 10, bestMask = 0;
        for (int r=0; r<9; ++r) {
            for (int c=0; c<9; ++c) {
                if (grid[r][c] == 0) {
                    int mask = candidatesMask(r,c);
                    if (mask == 0) return false; // dead end
                    int cnt = __builtin_popcount(mask);
                    if (cnt < bestCount) {
                        bestCount = cnt;
                        br = r; bc = c;
                        bestMask = mask;
                        if (cnt == 1) break; // can't do better than 1
                    }
                }
            }
            if (bestCount == 1) break;
        }

        // If no empty found, solved
        if (br == -1) return true;

        // try each candidate (iterate bits)
        // try digits in increasing order (1..9)
        for (int m = bestMask; m; m &= (m-1)) {
            int bit = m & -m;
            int digit = maskToDigit(bit);
            place(br, bc, digit);
            if (solve()) return true;
            remove(br, bc, digit);
        }
        return false;
    }

    // read board from stdin (9 lines). Accepts digits or '.' or '0'
    bool readInput() {
        string line;
        for (int r=0; r<9; ++r) {
            if (!getline(cin, line)) return false;
            // skip empty lines
            if (line.empty()) { --r; continue; }
            int filled = 0;
            for (char ch : line) {
                if (ch == ' ' || ch == '\t') continue;
                if (filled >= 9) break;
                if (ch == '.' || ch == '0') {
                    grid[r][filled] = 0;
                } else if (ch >= '1' && ch <= '9') {
                    int d = ch - '0';
                    grid[r][filled] = d;
                } else {
                    // invalid char -> treat as empty
                    grid[r][filled] = 0;
                }
                ++filled;
            }
            if (filled < 9) {
                // If the line had fewer chars, fill rest with 0s
                for (int c = filled; c < 9; ++c) grid[r][c] = 0;
            }
        }
        // initialize masks and verify no conflicts
        for (int r=0; r<9; ++r) {
            for (int c=0; c<9; ++c) {
                int d = grid[r][c];
                if (d != 0) {
                    int bit = 1 << (d-1);
                    if (rowMask[r] & bit) return false; // duplicate in row
                    if (colMask[c] & bit) return false; // duplicate in col
                    int b = boxIndex(r,c);
                    if (boxMask[b] & bit) return false; // duplicate in box
                    rowMask[r] |= bit;
                    colMask[c] |= bit;
                    boxMask[b] |= bit;
                }
            }
        }
        return true;
    }

#include "semantics_av/http/response.hpp"

namespace semantics_av {
