bool FFTSpectrumVisualizer::initialize() {
    glGenVertexArrays(1, &vao);
    glGenBuffers(1, &vbo);

    glBindVertexArray(vao);
    glBindBuffer(GL_ARRAY_BUFFER, vbo);
    // Initial allocation (will be resized based on actual FFT size)
    glBufferData(GL_ARRAY_BUFFER, 4096 * 2 * sizeof(float), nullptr, GL_DYNAMIC_DRAW);
    glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 2 * sizeof(float), (void*)0);
    glEnableVertexAttribArray(0);

    // Create axis line (x-axis at bottom of spectrum plot)
    // Note: The shader applies transformation: pos.y = pos.y * 0.4 for plot_type 4
    // So to get y=-0.32 after transformation, we need y=-0.8 before
    glGenVertexArrays(1, &axis_vao);
    glGenBuffers(1, &axis_vbo);

    glBindVertexArray(axis_vao);
    glBindBuffer(GL_ARRAY_BUFFER, axis_vbo);

    float axis_vertices[] = {
        -1.0f, -1.8f,  // Left end of x-axis (shifted down)
         1.0f, -1.8f   // Right end of x-axis (shifted down)
    };

    glBufferData(GL_ARRAY_BUFFER, sizeof(axis_vertices), axis_vertices, GL_STATIC_DRAW);
    glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 2 * sizeof(float), (void*)0);
    glEnableVertexAttribArray(0);

    // Create tick marks (11 ticks: -fs/2, ..., 0, ..., +fs/2)
    glGenVertexArrays(1, &ticks_vao);
    glGenBuffers(1, &ticks_vbo);

    glBindVertexArray(ticks_vao);
    glBindBuffer(GL_ARRAY_BUFFER, ticks_vbo);

    const int num_ticks = 11;
    std::vector<float> tick_vertices;
    tick_vertices.reserve(num_ticks * 4); // 2 vertices per tick, 2 coords per vertex

    for (int i = 0; i < num_ticks; i++) {
        float x = -1.0f + (2.0f * i) / (num_ticks - 1);
        tick_vertices.push_back(x);
        tick_vertices.push_back(-1.8f);   // Bottom of tick (at axis line, shifted down)
        tick_vertices.push_back(x);
        tick_vertices.push_back(-1.675f); // Top of tick (small upward tick, shifted down)
    }

    glBufferData(GL_ARRAY_BUFFER, tick_vertices.size() * sizeof(float), tick_vertices.data(), GL_STATIC_DRAW);
    glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 2 * sizeof(float), (void*)0);
    glEnableVertexAttribArray(0);

    // Initialize text renderer with larger font
    text_renderer = std::make_unique<TextRenderer>();
    if (!text_renderer->initialize("/usr/share/fonts/liberation-mono-fonts/LiberationMono-Regular.ttf", 48)) {
        std::cerr << "Warning: Failed to initialize text renderer for FFT spectrum" << std::endl;
        text_renderer.reset();
    }

    return true;
}

