    if (samples.empty()) return;

    // Reinitialize FFT plan if size changed
    if (samples.size() != fft_size) {
        if (fft_plan) {
            fftwf_destroy_plan(fft_plan);
            fftwf_free(fft_input);
            fftwf_free(fft_output);
        }

        fft_size = samples.size();
        fft_input = fftwf_alloc_real(fft_size * 2);  // Interleaved complex
        fft_output = fftwf_alloc_complex(fft_size);

        fft_plan = fftwf_plan_dft_1d(fft_size,
                                     reinterpret_cast<fftwf_complex*>(fft_input),
                                     fft_output,
                                     FFTW_FORWARD,
                                     FFTW_ESTIMATE);

        spectrum_magnitude.resize(fft_size);

