        glBindBuffer(GL_ARRAY_BUFFER, vbo);
        glBufferData(GL_ARRAY_BUFFER, fft_size * 2 * sizeof(float), nullptr, GL_DYNAMIC_DRAW);
    }

    computeFFT(samples);
}

