/**
 * @brief mecanum chassis velocity decomposition
 * @param input : ↑=+vx(mm/s)  →=+vy(mm/s)  ccw=+vw(deg/s)
 *        output: every wheel speed(rpm)
 * @trans 输入：		前后左右的量
 *				 输出：		每个轮子对应的速度
 * @note  1=FR 2=FL 3=BL 4=BR
 * @work	 分析演算公式计算的效率
 */
static void mecanum_calc(float vx, float vy, float vw, int16_t speed[]) // 底盘解算，得到底盘获得相应速度需要的四个电机值
{
	static float rotate_ratio = ((WHEELBASE + WHEELTRACK) / 2.0f) * ANGLE_TO_RAD;
	static float wheel_rpm_ratio = (60.0f * CHASSIS_DECELE_RATIO) / PERIMETER;

	VAL_LIMIT(vx, -MAX_CHASSIS_VX_SPEED, MAX_CHASSIS_VX_SPEED); // mm/s
	VAL_LIMIT(vy, -MAX_CHASSIS_VY_SPEED, MAX_CHASSIS_VY_SPEED); // mm/s
	/*小陀螺以外的模式，vw限制正常*/
	if (chassis_mode != CHASSIS_DODGE_MODE && chassis.dodge_ctrl == OFF_DODGE)
		VAL_LIMIT(vw, -MAX_CHASSIS_VR_SPEED, MAX_CHASSIS_VR_SPEED); // deg/s
	/*小陀螺时，vw不受限制*/
	//	else
	//		VAL_LIMIT(vw, -MAX_CHASSIS_VR_SPEED, MAX_CHASSIS_VR_SPEED);  //deg/s

	int16_t wheel_rpm[4];
	float max = 0;

	wheel_rpm[0] = (-vx + vy - vw * rotate_ratio) * wheel_rpm_ratio;
	wheel_rpm[1] = (vx + vy - vw * rotate_ratio) * wheel_rpm_ratio;
	wheel_rpm[2] = (vx - vy - vw * rotate_ratio) * wheel_rpm_ratio;
	wheel_rpm[3] = (-vx - vy - vw * rotate_ratio) * wheel_rpm_ratio;

	// find max item
	for (uint8_t i = 0; i < 4; i++)
	{
		if (abs(wheel_rpm[i]) > max)
			max = abs(wheel_rpm[i]);
	}
	// equal proportion
	if (max > MAX_WHEEL_RPM)
	{
		float rate = MAX_WHEEL_RPM / max;
		for (uint8_t i = 0; i < 4; i++)

			wheel_rpm[i] *= rate;
	}
	memcpy(speed, wheel_rpm, 4 * sizeof(int16_t));
}

//正解算获取vx vy vw
static void calculate_chassis_velocities(int16_t wheel_rpm[4],float *vx, float *vy, float *vw) 
{
	static float rotate_ratio = ((WHEELBASE + WHEELTRACK) / 2.0f) * ANGLE_TO_RAD;
	static float wheel_rpm_ratio = (60.0f * CHASSIS_DECELE_RATIO) / PERIMETER;
    // 计算 vx 和 vy
    *vx = ( -wheel_rpm[0] + wheel_rpm[1] + wheel_rpm[2] - wheel_rpm[3] ) / (4 * wheel_rpm_ratio);
    *vy = ( wheel_rpm[0] + wheel_rpm[1] - wheel_rpm[2] - wheel_rpm[3] ) / (4 * wheel_rpm_ratio);

    // 计算 vw
    *vw = ( -wheel_rpm[0] - wheel_rpm[1] - wheel_rpm[2] - wheel_rpm[3] ) / (4*rotate_ratio * wheel_rpm_ratio);
}

//逆解算获取速度分量
static void calculate_wheel_velocities(float wheel_rpm_v[4], float wheel_rpm_w[4], float vx, float vy, float w)
{
	static float rotate_ratio = ((WHEELBASE + WHEELTRACK) / 2.0f) * ANGLE_TO_RAD;
	static float wheel_rpm_ratio = (60.0f * CHASSIS_DECELE_RATIO) / PERIMETER;

	wheel_rpm_v[0] = (-vx + vy) * wheel_rpm_ratio;
	wheel_rpm_v[1] = (vx + vy) * wheel_rpm_ratio;
	wheel_rpm_v[2] = (vx - vy) * wheel_rpm_ratio;
	wheel_rpm_v[3] = (-vx - vy) * wheel_rpm_ratio;

	wheel_rpm_w[0] = (- (w * rotate_ratio)) * wheel_rpm_ratio;
	wheel_rpm_w[1] = (- (w * rotate_ratio)) * wheel_rpm_ratio;
	wheel_rpm_w[2] = (- (w * rotate_ratio)) * wheel_rpm_ratio;
	wheel_rpm_w[3] = (- (w * rotate_ratio)) * wheel_rpm_ratio;
}

//获取移动、旋转功率分量
//铜损耗、铁损耗、静态功率损耗需要均摊，保证两者功率相和为整个底盘的功率
static void calculate_power_component(float* power_v, float* power_w, int16_t wheel_current[4], float wheel_rpm_v[4], float wheel_rpm_w[4])
{
	static float k1 = 0.000002329f;//机械功率系数
	static float k2 = 0.0000001804f;//铜损耗系数
	static float k3 = 0.0000002496f;//铁损耗系数
	static float a = 0.8152f;//电调静态功率
	*power_v = 0;
	*power_w = 0;
	u8 i = 0;
	for(i = 0;i < 4;i++)
	{
		*power_v += k1*wheel_current[i]*wheel_rpm_v[i]
							+ 0.5f*k2*wheel_current[i]*wheel_current[i]
							+ 0.5f*k3*(wheel_rpm_v[i] + wheel_rpm_w[i])*(wheel_rpm_v[i] + wheel_rpm_w[i])
							+ 0.5f*a;
	}
	for(i = 0;i < 4;i++)
	{
		*power_w += k1*wheel_current[i]*wheel_rpm_w[i]
							+ 0.5f*k2*wheel_current[i]*wheel_current[i]
							+ 0.5f*k3*(wheel_rpm_v[i] + wheel_rpm_w[i])*(wheel_rpm_v[i] + wheel_rpm_w[i])
							+ 0.5f*a;
	}
	if(power_v < 0)
		power_v = 0;
	if(power_w < 0)
		power_w = 0;
}

static void Get_v_w_power(float* power_v, float* power_w, int16_t wheel_current[4], int16_t wheel_rpm[4])
{
	float vx,vy,vw;//平移、旋转速度
	float wheel_rpm_v[4];//每个轮毂的平移速度分量
	float wheel_rpm_w[4];//每个轮毂的旋转速度分量
	calculate_chassis_velocities(wheel_rpm,&vx,&vy,&vw);//获取底盘的平移、旋转速度
	calculate_wheel_velocities(wheel_rpm_v, wheel_rpm_w, vx, vy, vw);//获取每个轮毂的平移、旋转速度分量
	calculate_power_component(power_v,power_w,wheel_current,wheel_rpm_v,wheel_rpm_w);//获取底盘平移、旋转的功率分量
}

