Matrix  Matrix::operator*(const Matrix& other) const{
            if (cols != other.rows){
                throw std::invalid_argument("Matrices dimensions do not match for multiplication");
            }
            Matrix result(rows, other.cols);
            for(int i=0; i<rows; ++i){
                for(int j=0; j<other.cols; ++j){
                    double sum = 0.0;
                    for(int k=0; k<cols; ++k){
                        sum += getValue(i,k) * other.getValue(k,j);
                    }
                    result.setValue(i,j,sum);
                }
            }
            return result;
        }

Matrix  Matrix::operator*(double scalar) const{
            Matrix result(rows, cols);
            for(int i=0; i<rows; ++i){
                for(int j=0; j<cols; ++j){
                    result.setValue(i,j,getValue(i,j) * scalar);
                }
            }
            return result;
        }

Matrix  Matrix::transpose() const{
            Matrix result(cols, rows);
            for(int i=0; i<rows; ++i){
                for(int j=0; j<cols; ++j){
                    result.setValue(j,i,getValue(i,j));
                }
            }
            return result;
        }

Matrix Matrix::ElementwiseMultiply(const Matrix& other) const{
            if (rows != other.rows || cols != other.cols) {
                throw std::invalid_argument("Matrices must have the same dimensions for element-wise multiplication");
            }
            Matrix result(rows, cols);
            for (int i = 0; i < rows; ++i) {
                for (int j = 0; j < cols; ++j) {
                    result.setValue(i, j, this->getValue(i, j) * other.getValue(i, j));
                }
            }
            return result;
        }

