    int i, j;
    int open, maxLock, maxCount, choice;

    printf("===== FAST-LOCKER CHAOS GAME =====\n");
    printf("Enter number of lockers: ");
    scanf("%d",&l);
    printf("Enter number of students: ");
    scanf("%d",&s);

    // initialize lockers and counts
    for(i=1;i<=l;i++){
        lock[i]=0;
        count[i]=0;
    }

    // each student toggles lockers
    for(i=1;i<=s;i++){
        for(j=i;j<=l;j=j+i){
            if(lock[j]==0){
                lock[j]=1;
            }
            else{
                lock[j]=0;
            }
            count[j]++;
        }
    }

    // menu using switch
    for(;;){
        printf("\n=============================\n");
        printf("1. Show number of open lockers\n");
        printf("2. Show most toggled locker\n");
        printf("3. Exit\n");
        printf("Enter your choice: ");
        scanf("%d",&choice);

        switch(choice){
            case 1:
                open=0;
                for(i=1;i<=l;i++){
                    if(lock[i]==1){
                        open++;
                    }
                }
                printf("Number of open lockers: %d\n",open);
                break;

            case 2:
                maxLock=1;
                maxCount=count[1];
                for(i=2;i<=l;i++){
