const int ROUNDS = 64;
const int KEY_EXPANSION_SIZE = 2048;
const int SBOX_SIZE = 256;
const int PBOX_SIZE = 512;

vector<unsigned char> generate_sbox(const string& key) {
    vector<unsigned char> sbox(SBOX_SIZE);
    for (int i = 0; i < SBOX_SIZE; i++) sbox[i] = i;

    unsigned char key_hash = 0;
    for (char c : key) key_hash ^= c;

    for (int i = 0; i < SBOX_SIZE * 8; i++) {
        int idx1 = (i * key_hash + key[i % key.size()]) % SBOX_SIZE;
        int idx2 = (idx1 * 7 + key_hash + i) % SBOX_SIZE;
        swap(sbox[idx1], sbox[idx2]);
    }

    return sbox;
}

vector<int> generate_pbox(const string& key) {
    vector<int> pbox(PBOX_SIZE);
    for (int i = 0; i < PBOX_SIZE; i++) pbox[i] = i;

    unsigned long seed = 0;
    for (char c : key) seed = (seed << 5) ^ c;

    for (int i = PBOX_SIZE - 1; i > 0; i--) {
        int j = (seed * i + key[i % key.size()]) % (i + 1);
        swap(pbox[i], pbox[j]);
    }

    return pbox;
}

vector<unsigned char> expand_key(const string& key, int size) {
    vector<unsigned char> expanded(size);
    vector<unsigned char> temp_key(size);

    for (int i = 0; i < size; i++) {
        temp_key[i] = key[i % key.size()];
    }

    for (int round = 0; round < 13; round++) {
        for (int i = 0; i < size; i++) {
            int prev = (i > 0) ? temp_key[i-1] : temp_key[size-1];
            int next = (i < size-1) ? temp_key[i+1] : temp_key[0];

            expanded[i] = (temp_key[i] * 3 + prev * 5 + next * 7 + 
                          key[(i + round) % key.size()] * 11) % 256;

            expanded[i] = (expanded[i] << 3) | (expanded[i] >> 5);
            expanded[i] ^= (i * round + key[i % key.size()]) % 256;
        }
        temp_key = expanded;
    }

    return expanded;
}

unsigned char feistel_function(unsigned char data, unsigned char key_byte, int round) {
    unsigned char result = data;

    result = (result + key_byte * 3) % 256;
    result = (result << 4) | (result >> 4);
    result ^= (key_byte * 7 + round * 13) % 256;
    result = (result * 5 + 17) % 256;
    result = (result << 1) | (result >> 7);
    result ^= (key_byte * 11 + round * 19) % 256;
    result = (result * 9 + 23) % 256;
    result = (result << 3) | (result >> 5);
    result ^= (key_byte * 13 + round * 29) % 256;

    return result;
}

vector<unsigned char> process_block(const vector<unsigned char>& block, 
                                  const vector<unsigned char>& expanded_key,
                                  const vector<unsigned char>& sbox,
                                  const vector<int>& pbox,
                                  bool encrypt) {
