    int key_index = 0;

    for (int round = 0; round < ROUNDS; round++) {
        vector<unsigned char> temp_result = result;

        for (int i = 0; i < result.size(); i++) {
            if (encrypt) {
                unsigned char key_byte = expanded_key[(key_index + round * i) % expanded_key.size()];
                result[i] = feistel_function(result[i], key_byte, round);

                if (i > 0) {
                    result[i] ^= result[i-1];
                    result[i] = (result[i] + result[0]) % 256;
                }

                result[i] = sbox[result[i]];
            }
        }

        if (result.size() >= 2) {
            for (int i = 0; i < result.size() - 1; i += 2) {
                unsigned char left = result[i];
                unsigned char right = result[i+1];

                if (encrypt) {
                    right ^= feistel_function(left, expanded_key[(round + i) % expanded_key.size()], round);
                    left ^= feistel_function(right, expanded_key[(round + i + 1) % expanded_key.size()], round);
                } else {
                    left ^= feistel_function(right, expanded_key[(ROUNDS - round - 1 + i + 1) % expanded_key.size()], ROUNDS - round - 1);
                    right ^= feistel_function(left, expanded_key[(ROUNDS - round - 1 + i) % expanded_key.size()], ROUNDS - round - 1);
                }

                result[i] = left;
                result[i+1] = right;
            }
        }

        vector<unsigned char> pbox_result(result.size());
        for (int i = 0; i < result.size() && i < PBOX_SIZE; i++) {
            int target_pos = encrypt ? pbox[i] : i;
