struct Vehicle {
    char number[20];
    char type[20];   
    float charge;
};


struct Vehicle vehicles[100];
int count = 0;
float totalAmount = 0;


void addVehicle() {
    struct Vehicle v;
    printf("\nEnter vehicle number: ");
    scanf("%s", v.number);

    printf("Enter vehicle type (Car/Bike/Bus): ");
    scanf("%s", v.type);

    if (strcmp(v.type, "Car") == 0 || strcmp(v.type, "car") == 0)
        v.charge = 50;
    else if (strcmp(v.type, "Bike") == 0 || strcmp(v.type, "bike") == 0)
        v.charge = 20;
    else if (strcmp(v.type, "Bus") == 0 || strcmp(v.type, "bus") == 0)
        v.charge = 100;
    else
        v.charge = 30; 

    vehicles[count] = v;
    count++;
    totalAmount += v.charge;

    printf("\n Vehicle parked successfully! Charge: ₹%.2f\n", v.charge);
}


void removeVehicle() {
    char number[20];
    int found = 0;

    printf("\nEnter vehicle number to remove: ");
    scanf("%s", number);

    for (int i = 0; i < count; i++) {
        if (strcmp(vehicles[i].number, number) == 0) {
            printf("\n Vehicle %s (%s) removed successfully!\n", vehicles[i].number, vehicles[i].type);
            totalAmount -= vehicles[i].charge;

            for (int j = i; j < count - 1; j++)
                vehicles[j] = vehicles[j + 1];

            count--;
            found = 1;
            break;
        }
    }

    if (!found)
        printf("\n Vehicle not found!\n");
}

// Function to display all parked vehicles
void displayVehicles() {
    if (count == 0) {
        printf("\nNo vehicles parked right now.\n");
        return;
    }

    printf("\n---List of Parked Vehicles ---\n");
    printf("%-15s %-10s %-10s\n", "Vehicle No", "Type", "Charge");
    printf("--------------------------------------\n");

    for (int i = 0; i < count; i++) {
        printf("%-15s %-10s ₹%.2f\n", vehicles[i].number, vehicles[i].type, vehicles[i].charge);
    }

    printf("--------------------------------------\n");
    printf("Total Vehicles: %d | Total Collection: ₹%.2f\n", count, totalAmount);
}


void menu() {
    printf("\n=====  Parking Management System =====\n");
    printf("1. Park a Vehicle\n");
    printf("2. Remove a Vehicle\n");
    printf("3. Display All Parked Vehicles\n");
    printf("4. Show Total Amount Collected\n");
    printf("5. Exit\n");
    printf("Enter your choice: ");
}


int main() {
    int choice;

    while (1) {
        menu();
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                addVehicle();
                break;
            case 2:
                removeVehicle();
                break;
            case 3:
                displayVehicles();
                break;
            case 4:
                printf("\n Total Amount Collected: ₹%.2f\n", totalAmount);
                break;
            case 5:
                printf("\nThank you for using Parking Management System!\n");
                exit(0);
            default:
                printf("\nInvalid choice! Please try again.\n");
        }
    }

    return 0;
}

