#include "Enemy.h"
#include "Player.h"
#include "World.h"
#include <cmath>

Enemy::Enemy()
    : m_position(0.0f, 0.0f)
    , m_velocity(0.0f, 0.0f)
    , m_speed(150.0f) // Base enemy speed
    , m_facingRight(true)
    , m_animationTime(0.0f)
    , m_animationSpeed(1.5f)
    , m_health(1) // Default 1 heart, can be overridden
    , m_attackCooldown(1.0f) // 1 second base cooldown
    , m_attackCooldownTimer(0.0f)
{
}

void Enemy::Update(float deltaTime, Player* player, World* world) {
    // Update attack cooldown
    if (m_attackCooldownTimer > 0.0f) {
        m_attackCooldownTimer -= deltaTime;
    }

    // Update AI and movement
    UpdateAI(deltaTime, player);

    // Apply movement
    m_position.x += m_velocity.x * deltaTime;
    m_position.y += m_velocity.y * deltaTime;

    // Apply basic terrain collision (similar to player)
    if (world) {
        float groundY = world->GetGroundHeight(m_position.x);
        float waveY = world->GetWaveHeight(m_position.x);
        float terrainY = min(groundY, waveY);

        // Simple ground collision
        if (m_position.y >= terrainY - 20.0f) { // 20 is approximate enemy height
            m_position.y = terrainY - 20.0f;
            m_velocity.y = 0.0f;
        }
    }

    // Apply velocity damping
    m_velocity.x *= 0.8f;
    m_velocity.y *= 0.8f;

    // Update animation
    if (abs(m_velocity.x) > 10.0f) {
        m_animationTime += deltaTime * m_animationSpeed;
    } else {
        m_animationTime = 0.0f;
    }

    // Update facing direction based on movement
    if (m_velocity.x > 10.0f) {
        m_facingRight = true;
    } else if (m_velocity.x < -10.0f) {
        m_facingRight = false;
    }
}

void Enemy::UpdateAI(float deltaTime, Player* player) {
    // Base AI: move towards player
    if (player) {
        Vector2 playerPos = player->GetPosition();
        Vector2 direction = playerPos - m_position;
        float distance = sqrt(direction.x * direction.x + direction.y * direction.y);

        // Normalize direction
        if (distance > 0.0f) {
            direction.x /= distance;
            direction.y /= distance;
        }

        // Move towards player
        MoveTowards(playerPos, deltaTime);

        // Note: Attack logic is handled by derived classes in their UpdateAI overrides
    }
}

void Enemy::MoveTowards(const Vector2& target, float deltaTime) {
    Vector2 direction = target - m_position;
    float distance = sqrt(direction.x * direction.x + direction.y * direction.y);

    if (distance > 0.0f) {
        // Normalize direction
        direction.x /= distance;
        direction.y /= distance;

        // Apply movement
        m_velocity.x += direction.x * m_speed;
        m_velocity.y += direction.y * m_speed * 0.5f; // Slower vertical movement

        // Limit velocity
        float maxSpeed = m_speed;
        if (m_velocity.x > maxSpeed) m_velocity.x = maxSpeed;
        if (m_velocity.x < -maxSpeed) m_velocity.x = -maxSpeed;
        if (m_velocity.y > maxSpeed * 0.5f) m_velocity.y = maxSpeed * 0.5f;
        if (m_velocity.y < -maxSpeed * 0.5f) m_velocity.y = -maxSpeed * 0.5f;
    }
}

/**
* @file task1.cpp
 * @brief Implementacja Zadania 1: Znajdowanie otoczki wypukłej.
 *
 * Zawiera algorytm Monotone Chain oraz funkcję wypisującą wynik.
 */
#include <vector>
#include "../points/Point.h"
#include <algorithm>
#include "../utilis/geometry/geometry_functions.h"
using namespace std;
/**
 * @brief Implementacja algorytmu Monotone Chain (Andrew's).
 *
* ZZnajduje najmniejszy (najmniej liczny) podzbiór takich punktów, które
*otaczają wszystkie inne punkty.
 * Złożoność obliczeniowa: O(n log n) z powodu sortowania.
 *
 * @note Ta funkcja celowo pracuje na kopii wektora wejściowego,
 * aby nie modyfikować oryginalnych danych.
 *
 * @param all_points Wektor wszystkich wczytanych punktów.
 * @return Wektor punktów tworzących otoczkę wypukłą.
 */
vector<Point> monotone_chain_algorithm(const vector<Point>& all_points)
{
    // przypadki brzegowe
    if (all_points.size() <= 3)
    {
        return all_points;
    }

    // tworzenie kopii roboczej i sortowanie
    vector<Point> sorted_points = all_points;
    sort(sorted_points.begin(), sorted_points.end());

    vector<Point> L; //dolna otoczka
    vector<Point> U; //górna otoczka

    // budowanie dolnej otoczki (L)
    for (auto sorted_point : sorted_points)
    {
        // dopóki ostatni segment skręca w prawo (lub jest prosty), usuwaj punkty
        while (L.size() >= 2 && cross_product(L[L.size() - 2], L.back(), sorted_point) <= 0)
        {
            L.pop_back();
        }

        L.push_back(sorted_point);
    }
    // budowanie górnej otoczki (U)
    for (int i = sorted_points.size() - 1; i >= 0; --i)
    {
        while (U.size() >= 2 && cross_product(U[U.size() - 2], U.back(), sorted_points[i]) <= 0)
        {
            U.pop_back();
        }

        U.push_back(sorted_points[i]);
    }
    L.pop_back();// usunięcie skrajnego prawego duplikatu
    U.pop_back();// usunięcie skrajnego lewego duplikatu
    L.insert(L.end(), U.begin(), U.end()); // łączenie, finalna otoczka
    return L;
}

/**
 * @brief Funkcja wypisująca wynik Zadania 1.
 *
 * Iteruje po wektorze otoczki i wypisuje każdy punkt na konsolę.
 *
 * @param convex_hull Stała referencja do wektora z punktami otoczki,
 * obliczonymi wcześniej w main.
 */
void task1(const vector<Point>& convex_hull)
{
    for (Point p : convex_hull)
    {
        p.print();
    }
}

#include "app.h"
