  ASSERT_RESULT_OK(apex_manifest);
  EXPECT_EQ("com.android.example.apex", std::string(apex_manifest->name()));
  EXPECT_EQ(1u, apex_manifest->version());
  EXPECT_FALSE(apex_manifest->nocode());
