MerkelMain::MerkelMain() {}

void MerkelMain::init()
{

    currentTime = orderBook.getEarliestTime();

    wallet.updateBalance("BTC", 1.0);
    wallet.updateBalance("ETH", 10.0);

    int userOption;

    do
    {
        displayMenu();
        userOption = getUserOption();
        processUserOption(userOption);
        std::cout << "you have selected option " << userOption << std::endl;
    } while (userOption >= 1 && userOption <= 7);
}

void MerkelMain::displayMenu()
{
    std::cout << "================================" << std::endl;
    std::cout << "      Welcome to My Program     " << std::endl;
    std::cout << "================================" << std::endl;
    std::cout << "type 1 - 6 to select an option" << std::endl;
    std::cout << "1. Help" << std::endl;
    std::cout << "2. View status" << std::endl;
    std::cout << "3. Make a offer" << std::endl;
    std::cout << "4. make a bid" << std::endl;
    std::cout << "5. Show wallet" << std::endl;
    std::cout << "6. Next time frame" << std::endl;
    std::cout << "Current Time: " << currentTime << std::endl;
    std::cout << "================================" << std::endl;
}

void MerkelMain::processUserOption(int option)
{
    switch (option)
    {
    case 1:
        std::cout << "Help" << std::endl;
        break;
    case 2:
        std::cout << "View status" << std::endl;
        displayStats();
        break;
    case 3:
        std::cout << "Make a Ask" << std::endl;
        enterAsk();
        break;
    case 4:
        std::cout << "Make a Bid" << std::endl;
        enterBid();
        break;
    case 5:
        std::cout << "show wallet" << std::endl;
        std::cout << wallet.toString();
        break;
    case 6:
        std::cout << "Going to next time frame" << std::endl;
        gotoNextTimeFrame();
        break;
    default:
        std::cout << "Invalid option selected." << std::endl;
        break;
    }
}

int MerkelMain::getUserOption()
{
    int option = 0;
    std::string line;
    std::cout << "Enter your option: ";
    std::getline(std::cin, line);
    try
    {
        option = std::stoi(line);
    }
    catch (const std::exception &e)
    {
        option = 0; // Invalid option
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return option;
}

void MerkelMain::gotoNextTimeFrame()
{
    std::cout << "Current time: " << currentTime << std::endl;
    std::cout << "Moving to next time frame..." << std::endl;

    std::vector<OrderBookEntry> matchedOrders = orderBook.matchOrders("ETH/BTC", currentTime);

    for (const auto &order : matchedOrders)
    {
        std::cout << "Matched Order: " << order.toString() << std::endl;
    }

    currentTime = orderBook.getNextTime(currentTime);
}

void MerkelMain::displayStats()
{
    double totalBids = 0.0;
    double totalAsks = 0.0;

    std::cout << "All known products:" << std::endl;
    for (const std::string &product : orderBook.getKnownProducts())
    {

        std::vector<OrderBookEntry> bidOrders = orderBook.getOrders(OrderType::BID, product, currentTime);
        totalBids += bidOrders.size();
        if (!bidOrders.empty())
        {
            double highBid = OrderBook::getHighPrice(bidOrders);
            double lowBid = OrderBook::getLowPrice(bidOrders);
            double meanBid = orderBook.getMeanPrice(bidOrders);

            std::cout << "  BIDS for " << product << " - High: " << highBid << ", Low: " << lowBid << ", Mean: " << meanBid << std::endl;
        }

        std::vector<OrderBookEntry> askOrders = orderBook.getOrders(OrderType::ASK, product, currentTime);
        totalAsks += askOrders.size();
        if (!askOrders.empty())
        {
            double highAsk = OrderBook::getHighPrice(askOrders);
            double lowAsk = OrderBook::getLowPrice(askOrders);
            double meanAsk = orderBook.getMeanPrice(askOrders);

            std::cout << "  ASKS for " << product << " - High: " << highAsk << ", Low: " << lowAsk << ", Mean: " << meanAsk << std::endl;
        }

        std::cout << product << "\n";
    }

    std::cout << "Total Bids: " << totalBids << std::endl;
    std::cout << "Total Asks: " << totalAsks << std::endl;
    std::cout << "Total Orders: " << (totalBids + totalAsks) << std::endl;

    double changeInPrice = orderBook.getChangeInPrice(currentTime);
    std::cout << "Change in Price: " << changeInPrice << std::endl;

    if (changeInPrice > 0)
    {
        std::cout << "Price is going up!" << std::endl;
    }
    else if (changeInPrice < 0)
    {
        std::cout << "Price is going down!" << std::endl;
    }
    else
    {
        std::cout << "No change in price." << std::endl;
    }
}





