template<class T>
class New_Dec{
private:
    std::stack<T> front;
    std::stack<T> back;
public:
    bool empty(){
        return front.empty() && back.empty();
    }
    void push_front(T data){
        front.push(data);
    }
    void push_back(T data){
        back.push(data);
    }
    T pop_front(T data){
        T to_return;
        if (front.empty() == false) {
            to_return = front.top();
            front.pop();
            return to_return;
        }else {
            std::stack<T> new_front;
            for (int i = 1; i < back.size() - 1; i++) {
                new_front.push(back.top());
                back.pop();
            }
            to_return = back.top();
            back = new_front;
            return to_return;
        }
    }
    T pop_back(T data){
        T to_return;
        if (back.empty() == false) {
            to_return = back.top();
            back.pop();
            return to_return;
        }else{
            std::stack<T> new_front;
            for (int i=1; i < front.size()- 1; i++){
                new_front.push(front.top());
                front.pop();
            }
            to_return = front.top();
            front = new_front;
            return to_return;
        }
    }
};
