#include <stdio.h>

#define ROWS 3
#define COLS 3

// Bit positions
#define POWER_ON 0
#define OVERLOAD 1
#define MAINTENANCE 2

// --- Function Declarations ---
void updateSectorStatus(int grid[ROWS][COLS], int row, int col, int flag, int value);
void querySectorStatus(int grid[ROWS][COLS], int row, int col);
void runSystemDiagnostic(int grid[ROWS][COLS]);

// --- MAIN FUNCTION ---
int main() {
    int grid[ROWS][COLS] = {0}; // initialize all to 0 (all bits off)
    int choice, row, col, flag, value;

    do {
        printf("\n===== IESCO Power Grid Monitoring System =====\n");
        printf("1. Update Sector Status\n");
        printf("2. Query Sector Status\n");
        printf("3. Run System Diagnostic\n");
        printf("4. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter sector coordinates (row col): ");
                scanf("%d %d", &row, &col);
                if (row < 0 || row >= ROWS || col < 0 || col >= COLS) {
                    printf("Invalid coordinates!\n");
                    break;
                }

                printf("Select Flag to Update:\n");
                printf("0 - Power Status\n1 - Overload Warning\n2 - Maintenance Required\n");
                printf("Enter flag number: ");
                scanf("%d", &flag);

                printf("Enter 1 to SET or 0 to CLEAR the flag: ");
                scanf("%d", &value);

                updateSectorStatus(grid, row, col, flag, value);
                break;

            case 2:
                printf("Enter sector coordinates (row col): ");
                scanf("%d %d", &row, &col);
                if (row < 0 || row >= ROWS || col < 0 || col >= COLS) {
                    printf("Invalid coordinates!\n");
                    break;
                }
                querySectorStatus(grid, row, col);
                break;

            case 3:
                runSystemDiagnostic(grid);
                break;

            case 4:
                printf("Exiting system. Goodbye!\n");
                break;

            default:
                printf("Invalid choice! Please try again.\n");
        }

    } while (choice != 4);

    return 0;
}

// --- Function to Update Sector Status ---
void updateSectorStatus(int grid[ROWS][COLS], int row, int col, int flag, int value) {
    if (value == 1)
        grid[row][col] |= (1 << flag);   // SET bit using OR
    else
        grid[row][col] &= ~(1 << flag);  // CLEAR bit using AND NOT

    printf("Sector [%d][%d] updated successfully.\n", row, col);
}

// --- Function to Query Sector Status ---
void querySectorStatus(int grid[ROWS][COLS], int row, int col) {
    int status = grid[row][col];

    printf("\n--- Sector [%d][%d] Status Report ---\n", row, col);
    printf("Power: %s\n", (status & (1 << POWER_ON)) ? "ON" : "OFF");
    printf("Overload: %s\n", (status & (1 << OVERLOAD)) ? "Yes (Overloaded)" : "No");
    printf("Maintenance Required: %s\n", (status & (1 << MAINTENANCE)) ? "Yes" : "No");
    printf("Binary Code: %03d\n", status);
}

// --- Function to Run System Diagnostic ---
void runSystemDiagnostic(int grid[ROWS][COLS]) {
    int overloadedCount = 0;
    int maintenanceCount = 0;

    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            int sector = grid[i][j];
            if (sector & (1 << OVERLOAD))
                overloadedCount++;
            if (sector & (1 << MAINTENANCE))
                maintenanceCount++;
        }
    }

    printf("\n===== SYSTEM DIAGNOSTIC REPORT =====\n");
    printf("Total Sectors: %d\n", ROWS * COLS);
    printf("Overloaded Sectors: %d\n", overloadedCount);
    printf("Sectors Requiring Maintenance: %d\n", maintenanceCount);
    printf("====================================\n");
}

