void checkPersonDetection() {
  if (WiFi.status() == WL_CONNECTED) {
    HTTPClient http;
    http.begin(serverUrl);
    int httpCode = http.GET();

    if (httpCode == 200) {
      String payload = http.getString();
      Serial.print("Server Response: ");
      Serial.println(payload);

      JsonDocument doc;
      DeserializationError error = deserializeJson(doc, payload);

      if (!error) {
        if (doc["content"]["is_portrait"].is<bool>()) {
          bool newPersonStatus = doc["content"]["is_portrait"];
          Serial.print("Person detected: ");
          Serial.println(newPersonStatus ? "YES" : "NO");

          if (newPersonStatus != personDetected) {
            personDetected = newPersonStatus;
            systemActive = personDetected;
            displayNeedsUpdate = true; // Данные изменились - нужно обновить дисплей

            if (systemActive) {
              Serial.println("=== SYSTEM ACTIVATED ===");
            } else {
              Serial.println("=== SYSTEM STANDBY ===");
            }
          }
        } else {
          Serial.println("JSON missing 'is_portrait' field");
        }
      } else {
        Serial.print("JSON parsing failed: ");
        Serial.println(error.c_str());
      }
    } else {
      Serial.printf("HTTP GET failed, error: %s\n", http.errorToString(httpCode).c_str());
    }
    http.end();
  } else {
    Serial.println("WiFi not connected");
  }
}

