class Solution {
public:
    int trap(vector<int>& height) {
        int lmax ,rmax , total ;
        lmax = rmax = total = 0;
        int l = 0;
        int n = height.size();
        int r = n - 1;

        while(l < r){
            if(height[l] <= height[r]){
                if(lmax > height[l]){
                    total += lmax - height[l];
                }
                else{
                    lmax = height[l];
                }
                l++;
            }

            else{
                if(rmax > height[r]){
                    total += rmax - height[r];
                }

                else{
                    rmax = height[r];
                }
                r--;
            }
        }
        return total;
    }
};

