    std::cout << "[ENEMY '" << UI::COLOR_BRIGHT_RED << getName() << UI::COLOR_RESET << "'] ";
    std::cout << "Pos:(" << getX() << ", " << getY() << ") ";
    std::cout << "HP: " << UI::getHealthBar(getHealth(), 100, 10, true) << " ";
    std::cout << "Dmg:" << UI::COLOR_RED << attackDamage << UI::COLOR_RESET << " ";

