//  Task 2) Generate Divisors — create a vector 
std::vector<long long> generateDivisors(long long n) {
    std::vector<long long> divisors;      

    // Loop through all integers i = 1..n
    for (long long i = 1; i <= n; ++i) {
        // If the remainder of n / i is zero, i divides n 
        if (n % i == 0) {
            divisors.push_back(i);        
        }
    }

    return divisors;                       
}

