    clearHelper(root_);
}

template <typename Key, typename Data>
void
Map<Key, Data>::clearHelper(Node* root) 
{
    if (NULL == root) { return; }
    clearHelper(root->left_);
    clearHelper(root->right_);
    delete root;
    root = NULL;
}

