                int t = pas[i];
                pas[i] = pas[j];
                pas[j] = t;
            }
        }
    }

    int j = 0, last = -1, cnt = 0, t = 0;

    for (int i = 0; i < nb; i++) {
        cnt = 0;
        while (j < np && pas[j] <= buses[i] && cnt < cap) {
            last = pas[j];
            j++;
            cnt++;
        }
        if (i == nb - 1) {
            if (cnt < cap) t = buses[i];
            else t = last - 1;
        }
    }

    bool same = true;
    while (same) {
        same = false;
        for (int i = 0; i < np; i++) {
            if (pas[i] == t) {
                t--;
                same = true;
                break;
            }
        }
    }

    cout << "The latest time you can arrive is: " << t;
    return 0;
}

