    using std::get;  // needed for argument-dependent lookup (ADL) for call to std::get or get

    template<typename Function, typename TupleLike, std::size_t... Is>
    constexpr decltype(auto)
    apply_impl(Function && function, TupleLike && tuple_like, [[maybe_unused]] std::index_sequence<Is...> seq) noexcept(
        noexcept(std::invoke(std::forward<Function>(function), get<Is>(std::forward<TupleLike>(tuple_like))...))
    ) {
        // NOLINTNEXTLINE(bugprone-use-after-move,hicpp-invalid-access-moved): implemented as presented on cppreference (see: https://en.cppreference.com/w/cpp/utility/apply.html)
        return std::invoke(std::forward<Function>(function), get<Is>(std::forward<TupleLike>(tuple_like))...);
    }

    // std::apply only works for tuple-like classes (see: https://en.cppreference.com/w/cpp/utility/apply.html)
    // as of C++26, only standard library classes can be tuple-like and not custom classes (see: https://en.cppreference.com/w/cpp/utility/tuple/tuple-like.html)
    // therefore, this apply function is a re-implementation of std::apply, but also allows custom tuple-like classes
    template<typename Function, typename TupleLike>
    constexpr decltype(auto) apply(Function && function, TupleLike && tuple_like) noexcept(noexcept(apply_impl(
        std::forward<Function>(function),
        std::forward<TupleLike>(tuple_like),
        std::make_index_sequence<std::tuple_size_v<std::remove_reference_t<TupleLike>>>{}
    ))) {
        return apply_impl(
            std::forward<Function>(function),
            std::forward<TupleLike>(tuple_like),
            std::make_index_sequence<std::tuple_size_v<std::remove_reference_t<TupleLike>>>{}
        );
    }
}

