    if (!success) {
        std::cerr << "ERROR: Failed to write TGA file to " << output_path << std::endl;
        return EXIT_FAILURE;
    }

    std::cerr << "INFO: Successfully converted image to " << output_path << std::endl;
    return EXIT_SUCCESS;
}

