#include <iostream>
#include <future>
#include <thread>
#include <chrono>
#include <syncstream>
#include <string>

using namespace std;
using namespace std::chrono;

void compute(const string& name, int duration) {
    this_thread::sleep_for(seconds(duration));
    osyncstream(cout) << name << endl;
}

void slow(const string& name) {
    compute(name, 7);
}

void quick(const string& name) {
    compute(name, 1);
}

void work() {
    auto start_time = steady_clock::now();

    auto fut_A = async(launch::async, quick, "A");
    auto fut_C2 = async(launch::async, slow, "C2");

    auto fut_B2 = async(launch::async, quick, "B2");
    auto fut_B3 = async(launch::async, quick, "B3");

    fut_A.wait();

    auto fut_B1 = async(launch::async, slow, "B1");

    fut_B1.wait();
    fut_B2.wait();
    fut_B3.wait();

    auto fut_C1 = async(launch::async, quick, "C1");

    fut_C1.wait();
    fut_C2.wait();

    auto fut_D = async(launch::async, quick, "D");

    fut_D.wait();

    auto end_time = steady_clock::now();
    auto duration = duration_cast<seconds>(end_time - start_time).count();

    osyncstream(cout) << "Execution time: " << duration << " seconds" << endl;
    osyncstream(cout) << "Work is done!" << endl;
}

int main() {
    cout << "Starting computations for Variant #8..." << endl;
    cout << "========================================" << endl;

    work();

    return 0;
}

