#include "math_ext.h"
#include <llvm/IR/Intrinsics.h>

namespace glyft {
namespace math_ext {

bool MathExtModule::canHandle(const std::string& word) {
    return word == "sqrt" || word == "pow" || word == "max" || word == "min" || word == "abs" ||
           word == "sin" || word == "cos" || word == "random" || word == "random-int";
}

bool MathExtModule::processWord(const std::string& word,
                               llvm::IRBuilder<>* builder,
                               llvm::Module* module,
                               llvm::LLVMContext* context,
                               modules::StackPopFunction stackPop,
                               modules::StackPushFunction stackPush) {
    if (word == "sqrt") {
        // sqrt: ( x -- sqrt(x) )
        llvm::Value* x = stackPop();
        llvm::Value* result = generateSqrt(builder, module, context, x);
        stackPush(result);
        return true;
    } else if (word == "pow") {
        // pow: ( base exp -- base^exp )
        llvm::Value* exp = stackPop();
        llvm::Value* base = stackPop();
        llvm::Value* result = generatePower(builder, module, context, base, exp);
        stackPush(result);
        return true;
    } else if (word == "max") {
        // max: ( a b -- max(a,b) )
        llvm::Value* b = stackPop();
        llvm::Value* a = stackPop();
        llvm::Value* result = generateMax(builder, module, context, a, b);
        stackPush(result);
        return true;
    } else if (word == "min") {
        // min: ( a b -- min(a,b) )
        llvm::Value* b = stackPop();
        llvm::Value* a = stackPop();
        llvm::Value* result = generateMin(builder, module, context, a, b);
        stackPush(result);
        return true;
    } else if (word == "abs") {
        // abs: ( x -- |x| )
        llvm::Value* x = stackPop();
        llvm::Value* result = generateAbs(builder, module, context, x);
        stackPush(result);
        return true;
    } else if (word == "sin") {
        // sin: ( x -- sin(x) )
        llvm::Value* x = stackPop();
        llvm::Value* result = generateSin(builder, module, context, x);
        stackPush(result);
        return true;
    } else if (word == "cos") {
        // cos: ( x -- cos(x) )
        llvm::Value* x = stackPop();
        llvm::Value* result = generateCos(builder, module, context, x);
        stackPush(result);
        return true;
    } else if (word == "random") {
        // random: ( -- r ) where r is 0.0 to 1.0
        llvm::Value* result = generateRandom(builder, module, context);
        stackPush(result);
        return true;
    } else if (word == "random-int") {
        // random-int: ( min max -- r ) where r is random integer between min and max inclusive
        llvm::Value* max = stackPop();
        llvm::Value* min = stackPop();
        llvm::Value* result = generateRandomInt(builder, module, context, min, max);
        stackPush(result);
        return true;
    }

    return false;
}

std::vector<std::string> MathExtModule::getWords() const {
    return {"sqrt", "pow", "max", "min", "abs", "sin", "cos", "random", "random-int"};
}

llvm::Value* MathExtModule::generateSqrt(llvm::IRBuilder<>* builder, llvm::Module* module, llvm::LLVMContext* context, llvm::Value* x) {
    // Use LLVM's sqrt intrinsic
    llvm::Function* sqrtFunc = llvm::Intrinsic::getDeclaration(module, 
        llvm::Intrinsic::sqrt, llvm::Type::getDoubleTy(*context));
    return builder->CreateCall(sqrtFunc, {x});
}

llvm::Value* MathExtModule::generatePower(llvm::IRBuilder<>* builder, llvm::Module* module, llvm::LLVMContext* context, llvm::Value* base, llvm::Value* exp) {
    // Use LLVM's pow intrinsic
    llvm::Function* powFunc = llvm::Intrinsic::getDeclaration(module,
        llvm::Intrinsic::pow, llvm::Type::getDoubleTy(*context));
    return builder->CreateCall(powFunc, {base, exp});
}

llvm::Value* MathExtModule::generateMax(llvm::IRBuilder<>* builder, llvm::Module* module, llvm::LLVMContext* context, llvm::Value* a, llvm::Value* b) {
    // Use LLVM's maxnum intrinsic
    llvm::Function* maxFunc = llvm::Intrinsic::getDeclaration(module,
        llvm::Intrinsic::maxnum, llvm::Type::getDoubleTy(*context));
    return builder->CreateCall(maxFunc, {a, b});
}

llvm::Value* MathExtModule::generateMin(llvm::IRBuilder<>* builder, llvm::Module* module, llvm::LLVMContext* context, llvm::Value* a, llvm::Value* b) {
    // Use LLVM's minnum intrinsic
    llvm::Function* minFunc = llvm::Intrinsic::getDeclaration(module,
        llvm::Intrinsic::minnum, llvm::Type::getDoubleTy(*context));
    return builder->CreateCall(minFunc, {a, b});
}

llvm::Value* MathExtModule::generateAbs(llvm::IRBuilder<>* builder, llvm::Module* module, llvm::LLVMContext* context, llvm::Value* x) {
    // Use LLVM's fabs intrinsic
    llvm::Function* absFunc = llvm::Intrinsic::getDeclaration(module,
        llvm::Intrinsic::fabs, llvm::Type::getDoubleTy(*context));
    return builder->CreateCall(absFunc, {x});
}

