    bool toggle = true;
    while (writePtr < endPtr) {
        WORD blockSize = *(WORD*)sectionTable;
        sectionTable += 2;
        if (toggle) {
            memcpy(writePtr, sectionTable, blockSize);
            sectionTable += blockSize;
        }
        writePtr += blockSize;
        toggle = !toggle;
    }
    return true;
