void LedRGB::handle(unsigned long now){
   if(delayColor){
      if(now - startedDelayTime >= delayTime) {
         setColor(IDLE);
         delayColor = false;
      }
   }
}

void LedRGB::handleStatus(ColorsRGB status){
   if(delayColor) delayColor = false;

   switch (status) {
      case INIT:
         setColor(INIT);
         blink(INIT_BLINKS);
         break;

      case IDLE:
         setColor(IDLE);
         break;

      case ATTACK:
         setColor(ATTACK);
         break;

      case COMPLETED:
         setColor(COMPLETED);

         delayColor = true;
         startedDelayTime = millis();
         delayTime = 2000;
         break;

      case CANCELED:
         setColor(CANCELED);

         delayColor = true;
         startedDelayTime = millis();
         delayTime = 1000;
         break;

      case FAILED:
         setColor(ORANGE);
         blink(2);

         delayColor = true;
         startedDelayTime = millis();
         delayTime = 1000;
         break;

      case SCAN:
         setColor(CYAN);
         break;

      default:
         break;
   }
}

