#include <iostream>
#include "Animal.h"
#include "Word.h"
#include "GameState.h"
#include "GuessedLetters.h"
using namespace std;

int main() {
    cout << "Choose your animal (1 = Cow, 2 = Insect): ";
    int choice;
    cin >> choice;

    Animal* animal;
    if (choice == 2)
        animal = new Insect();
    else
        animal = new Cow();

    cout << "You chose a " << animal->getName() << "!\n";

    Word word("ELEPHANT"); // or prompt user for extra credit
    GameState game(animal->getBodyParts());
    GuessedLetters guessed;

    while (!game.gameOver() && !word.solved()) {
        cout << "\n" << game.getState() << endl;
        cout << "Guessed letters: " << guessed.getLetters() << endl;
        cout << "Guess this word: " << word.getWord() << endl;

        cout << "\nGuess a letter: ";
        char letter;
        cin >> letter;

        if (word.findLetter(letter)) {
            word.addLetter(letter);
        } else {
            game.addState();
            guessed.addLetter(letter);
        }
    }

    cout << "\n" << game.getState() << endl;
    if (word.solved())
        cout << "You guessed it! The word was " << "ELEPHANT" << "!\n";
    else
        cout << "Game over! The " << animal->getName() << " is fully hung!\n";

    delete animal;
    return 0;
}

