    EXPECT_EQ(recovered.num_channels(), 2);

    for (size_t i = 0; i < 100; ++i)
    {
        EXPECT_NEAR(recovered(i, 0), original(i, 0), 0.01f);
        EXPECT_NEAR(recovered(i, 1), original(i, 1), 0.01f);
    }
}

