ChatDialog::ChatDialog(QWidget *parent)
    : QDialog(parent)
    , ui(new Ui::ChatDialog)
{
    ui->setupUi(this);

    ui->btnSend->setEnabled(false);
    ui->btnSendFile->setEnabled(false);

