    connect(m_sock, &QTcpSocket::connected, this, &ChatDialog::connectSuccess);
    connect(m_sock, &QTcpSocket::readyRead, this, &ChatDialog::recvMsg);
    connect(m_sock, QOverload<QAbstractSocket::SocketError>::of(&QAbstractSocket::error), this, &ChatDialog::errorHandle);

    ui->edtReconrd->appendPlainText("[系统] 正在连接服务器，请稍侯...\n");
    m_sock->connectToHost("39.103.62.75", 8879);

}

ChatDialog::~ChatDialog()
{
    delete ui;
}

void ChatDialog::connectSuccess()
{
    ui->edtReconrd->appendPlainText("[系统] 连接服务器成功！\n\n");
    ui->btnSend->setEnabled(true);
    ui->btnSendFile->setEnabled(true);
}

void ChatDialog::errorHandle(QAbstractSocket::SocketError socketError)
{
    ui->edtReconrd->appendPlainText("[系统] 连接服务器失败！\n\n");
    ui->btnSend->setEnabled(false);
    ui->btnSendFile->setEnabled(false);
    m_sock->connectToHost("39.103.62.75", 8879);
}

void ChatDialog::recvMsg()
{
    MessageHeader msg;
    m_sock->read((char*)&msg, sizeof(msg));

    if(msg.msg_type == MSG_TYPE_TEXT)
    {
        QByteArray data = m_sock->readAll();
        ui->edtReconrd->appendPlainText(QString::fromUtf8(data) + "\n\n");
    }
    else if(msg.msg_type == MSG_TYPE_FILE)
    {
        QString filePath = QFileDialog::getOpenFileName(this, "选择保存的位置", msg.filename);
        QFile file(filePath);
        if (!file.open(QIODevice::WriteOnly|QIODevice::Truncate)) {
            QMessageBox::warning(this, "错误", "无法打开文件");
            return;
        }
        char buff[4 * 1024];
        qint64 ret;

        while ((ret = m_sock->read(buff, sizeof(buff))) > 0)
        {
            file.write(buff, ret);
        }
    }
}


void ChatDialog::on_btnSend_clicked()
{
    QString msg = ui->edtMsg->toPlainText();

    header.msg_type = MSG_TYPE_TEXT;
    header.data_len = msg.toUtf8().size();
    memset(header.filename, 0, sizeof(header.filename));

    m_sock->write((const char*)&header, sizeof(header));
    m_sock->write(msg.toUtf8());
}


void ChatDialog::on_btnSendFile_clicked()
{
    QString filePath = QFileDialog::getOpenFileName(this, "选择要传输的文件");

    QFile file(filePath);
    if (!file.open(QIODevice::ReadOnly)) {
        QMessageBox::warning(this, "错误", "无法打开文件");
        return;
    }

    QFileInfo f(filePath);
    header.msg_type = MSG_TYPE_FILE;
    header.data_len = f.size();

    // 将QString转换为char数组
    QByteArray fb = f.fileName().toUtf8();
    memset(header.filename, 0, sizeof(header.filename));
    strncpy(header.filename, fb.constData(), sizeof(header.filename) - 1);

    // 发送消息头
    m_sock->write((const char*)&header, sizeof(header));

    m_sock->write(file.readAll());

    file.close();
}

#include <string.h>
#include <stdlib.h>
#include <avr/io.h>
#include <avr/interrupt.h>

#define BUFFER_SIZE 50
static char txDataBuffer[BUFFER_SIZE] = "";
volatile static size_t txBufferTail = 0;
volatile static size_t txBufferHead = 0;

static char rxDataBuffer[BUFFER_SIZE] = "";
volatile static size_t rxBufferTail = 0;
volatile static size_t rxBufferHead = 0;

namespace Uart
{
    void init(unsigned int baudRate)
    {
        cli();
        UBRR0 = F_CPU / 16 / baudRate - 1;
        UCSR0B = (1 << RXCIE0) | (1 << RXEN0) | (1 << TXEN0);
        UCSR0C = (1 << UCSZ00) | (1 << UCSZ01);
        sei();
    }
    
    void transmit(char character)
    {
        txDataBuffer[txBufferHead++] = character;
        if(txBufferHead == BUFFER_SIZE)
            txBufferHead = 0;
        UCSR0B |= (1 << UDRIE0);
    }
    
    void transmit(const char* string)
    {
        while(*string)
        {
            txDataBuffer[txBufferHead++] = *string++;
            if(txBufferHead == BUFFER_SIZE)
                txBufferHead = 0;
        }
        UCSR0B |= (1 << UDRIE0);
    }
    
    char recieve()
    {
        if(rxBufferTail == rxBufferHead)
            return '\0';
        char data = rxDataBuffer[rxBufferTail++];
        if(rxBufferTail >= BUFFER_SIZE)
            rxBufferTail = 0;
        return data;
    }
}

ISR(USART_UDRE_vect)
{
    if(txBufferTail != txBufferHead)
    {
        UDR0 = txDataBuffer[txBufferTail++];
        if(txBufferTail >= BUFFER_SIZE)
            txBufferTail = 0;
    }
    else
        UCSR0B &= ~(1 << UDRIE0);
}

ISR(USART_RX_vect)
{
    rxDataBuffer[rxBufferHead++] = UDR0;
    if(rxBufferHead >= BUFFER_SIZE)
        rxBufferHead = 0;
}

