// Point class to represent coordinates
class Point {
public:
    int x, y;
    Point(int a = 0, int b = 0) : x(a), y(b) {}
    bool operator==(const Point& o) const { return x == o.x && y == o.y; }
};

// Food class
class Food {
private:
    Point position;
public:
    void spawn(int w, int h, const deque<Point>& snake) {
        bool valid = false;
        while (!valid) {
            position.x = rand() % (w - 2) + 1;
            position.y = rand() % (h - 2) + 1;
            valid = true;
            for (auto &p : snake) {
                if (p == position) {
                    valid = false;
                    break;
                }
            }
        }
    }

    Point getPosition() const { return position; }
};

// Snake class
class Snake {
private:
    deque<Point> body;
    deque<Point> prevBody;
    char direction;
public:
    Snake() : direction('R') {
        body.push_back(Point(15, 10));
        body.push_back(Point(14, 10));
        body.push_back(Point(13, 10));
    }

    void setDirection(char d) { direction = d; }
    char getDirection() const { return direction; }

    Point getHead() const { return body.front(); }
    const deque<Point>& getBody() const { return body; }
    const deque<Point>& getPrevBody() const { return prevBody; }

    void move() {
        prevBody = body;
        Point next = body.front();
        switch (direction) {
            case 'U': next.y--; break;
            case 'D': next.y++; break;
            case 'L': next.x--; break;
            case 'R': next.x++; break;
        }
        body.push_front(next);
    }

    void grow() {
        // Don't pop back, snake grows
    }

    void shrink() {
        body.pop_back();
    }

    bool checkSelfCollision() const {
        Point head = body.front();
        for (size_t i = 1; i < body.size(); i++) {
            if (body[i] == head) return true;
        }
        return false;
    }

    void reset() {
        body.clear();
        prevBody.clear();
        direction = 'R';
        body.push_back(Point(15, 10));
        body.push_back(Point(14, 10));
        body.push_back(Point(13, 10));
    }
};

// GameBoard class
class GameBoard {
private:
