Tank::Tank(int speed, int rotationSpeed, int health, bool isAI, QObject *parent):
    QObject(parent), speed(speed), rotationSpeed(rotationSpeed),health(health),m_isAI(isAI)
{
    QPixmap pix = updatePixmap().scaled(Height, Width); // 使用updatePixmap;
    setPixmap(pix);
    setTransformOriginPoint(pix.width()/2, pix.height()/2); // 设置旋转中心点
    originalSpeed = speed;
}

int Tank::getHealth()
{
    return health;
}
qreal Tank::getGunLength()
{
    // 炮管长度为坦克高度的一半（可根据实际图片调整）
    return pixmap().height() / 2.0;
}
void Tank::takeDamage(int damage)
{
    if(destroyedState)return;
    if(hasShield()){
        reduceShield();
        return;
    }

    health -= damage;
}

bool Tank::isDestroyed()
{
    if (health <= 0) {
        health = 0;
        // 触发坦克被摧毁事件
        destroyedState = true;
        qDebug() << "Tank destroyed! Emitting signal...";
        emit destroyed(pos()); // 发出被摧毁信号
    }
    return destroyedState;
}

void Tank::setHealth(int health)
{
    this->health = health;
    if (health <= 0) {
        destroyedState = true;
    } else {
        destroyedState = false;
    }
}

void Tank::rotateLeft()
{
    setRotation(rotation() - rotationSpeed);
}

void Tank::rotateRight()
{
    setRotation(rotation() + rotationSpeed);
}

void Tank::moveForward()
{
    // 根据当前角度计算移动方向
    qreal angle = rotation() * M_PI / 180.0; // 转换为弧度
    qreal dx = speed * qSin(angle);
    qreal dy = -speed * qCos(angle);

    setPos(x() + dx, y() + dy);
}

void Tank::moveBackward()
{
    // 根据当前角度计算移动方向（反向）
    qreal angle = rotation() * M_PI / 180.0; // 转换为弧度
    qreal dx = -speed * qSin(angle);
    qreal dy = speed * qCos(angle);

    setPos(x() + dx, y() + dy);
}

QPointF Tank::getGunEndpoint()
{
    // 计算炮管末端位置（基于坦克中心点和旋转角度）
    qreal angle = rotation() * M_PI / 180.0;
    qreal gunLength = pixmap().height() / 2; // 炮管长度设为坦克高度的一半

    // 计算炮管末端相对于坦克中心的偏移
    qreal dx = gunLength * sin(angle);
    qreal dy = -gunLength * cos(angle); // y轴向下为正

    // 返回炮管末端的绝对位置
    return pos() + QPointF(pixmap().width()/2 + dx, pixmap().height()/2 + dy);
}

void Tank::handleCollision()
{
    // 简单碰撞处理：回退到之前的位置
    moveBackward();
}

void Tank::setCurrentSkin(const QString& skinName)
{
    this->currentSkin = skinName;
    QPixmap pix = updatePixmap().scaled(Height, Width);
    setPixmap(pix);
    setTransformOriginPoint(pix.width()/2, pix.height()/2); // 设置旋转中心点
    originalSpeed = speed;
}

QString Tank::getCurrentSkin() const
{
    return currentSkin;
}

QPixmap Tank::updatePixmap()
{
    QPixmap pixmap;
    if (currentSkin == "沙漠迷彩皮肤") {
        pixmap = QPixmap(":/images/desert");
    } else if (currentSkin == "丛林迷彩皮肤") {
        pixmap = QPixmap(":/images/jungle");
    } else if (currentSkin == "雪地迷彩皮肤") {
        pixmap = QPixmap(":/images/snow");
    } else {
        // 默认皮肤
        if (speed >= 8) {
            pixmap = QPixmap(":/images/light");
        } else if (speed >= 6) {
            pixmap = QPixmap(":/images/balanced");
        } else {
            pixmap = QPixmap(":/images/heavy");
        }
    }
    return pixmap;
}

void Tank::activatePowerUp(ItemType type, int durationSeconds)
{
    // 如果道具已激活，先取消之前的效果
    if (isPowerUpActive(type)) {
        deactivatePowerUp(type);
    }

    switch (type) {
    case POWERUP_DOUBLE_SCORE:
        activeItems[type] = true;
        break;
    case POWERUP_SPEED_BOOST:
        originalSpeed = speed;
        speed *= 1.5;
        activeItems[type] = true;
        break;
    case POWERUP_SHIELD:
        activeItems[type] = 3; // 护盾次数
        break;
    default:
        break;
    }

    emit powerUpActivated(type);

    // 设置持续时间
    if (durationSeconds > 0) {
        QTimer* timer = new QTimer(this);
        timer->setSingleShot(true);
        connect(timer, &QTimer::timeout, this, [this, type]() {
            onPowerUpExpired(type);
        });
        timer->start(durationSeconds * 1000);
        powerUpTimers[type] = timer;
    }
}

void Tank::deactivatePowerUp(ItemType type)
{
    if (!activeItems.contains(type)) return;

    switch (type) {
    case POWERUP_DOUBLE_SCORE:
        activeItems.remove(type);
        break;
    case POWERUP_SPEED_BOOST:
        speed = originalSpeed;
        activeItems.remove(type);
        break;
    case POWERUP_SHIELD:
        activeItems.remove(type);
        break;
    default:
        break;
    }

    // 停止计时器
    if (powerUpTimers.contains(type)) {
        powerUpTimers[type]->stop();
        delete powerUpTimers[type];
        powerUpTimers.remove(type);
    }

    emit powerUpDeactivated(type);
}

bool Tank::isPowerUpActive(ItemType type) const
{
    return activeItems.contains(type);
}

