{
    int x; 
    int y; 
    SnakeTelo* next; 
};

class Snake
{
public:
    SnakeTelo* head;
    SnakeTelo* tail;

    Snake()
    {
        head = NULL;
        tail = NULL;
    }

    void StartSpisok(int x, int y)
    {
        SnakeTelo* newTelo = new SnakeTelo;
        newTelo->x = x;
        newTelo->y = y;
        newTelo->next = NULL;

        if (head == NULL)
        {
            head = newTelo;
            tail = newTelo;
        }
        else
        {
            newTelo->next = head;
            head = newTelo;
        }
    }
    void RemoveLast()
    {
        if (head == NULL) return;
        if (head == tail)
        {
            delete head;
            head = NULL;
            tail = NULL;
            return;
        }
        SnakeTelo* current = head;
        while (current->next != tail)
        {
            current = current->next;
        }
        delete tail;
        tail = current;
        tail->next = NULL;
    }
    void Move(int moveX, int moveY, bool eatFood = false)
    {
        int newX = head->x + moveX;
        int newY = head->y + moveY;
        StartSpisok(newX, newY);
        if (!eatFood)
        {
            RemoveLast();
        }
    }
    SnakeTelo* GetHead()
    {
        return head;
    }
    
};

