// Utility functions
std::string to_base58(const std::vector<unsigned char>& data) {
    mpz_t num;
    mpz_init(num);
    mpz_import(num, data.size(), 1, 1, 0, 0, data.data());
    
    std::string result;
    while (mpz_cmp_ui(num, 0) > 0) {
        int remainder = mpz_tdiv_ui(num, 58);
        result.push_back(BASE58_ALPHABET[remainder]);
        mpz_tdiv_q_ui(num, num, 58);
    }
    mpz_clear(num);
    
    std::reverse(result.begin(), result.end());
    for (size_t i = 0; i < data.size() && data[i] == 0; ++i) {
        result.insert(result.begin(), BASE58_ALPHABET[0]);
    }
    return result.empty() ? "1" : result;
}

std::string to_hex(const std::vector<unsigned char>& data) {
    std::string hex;
    char buf[3];
    for (unsigned char c : data) {
        sprintf(buf, "%02x", c);
        hex += buf;
    }
    return hex;
}

std::vector<unsigned char> double_sha256(const std::vector<unsigned char>& data) {
    unsigned char first[SHA256_DIGEST_LENGTH];
    SHA256(data.data(), data.size(), first);
    unsigned char second[SHA256_DIGEST_LENGTH];
    SHA256(first, SHA256_DIGEST_LENGTH, second);
    return std::vector<unsigned char>(second, second + SHA256_DIGEST_LENGTH);
}

// Bitcoin-specific functions
std::string private_key_to_wif(const std::vector<unsigned char>& private_key) {
    std::vector<unsigned char> extended_key = {0x80};
    extended_key.insert(extended_key.end(), private_key.begin(), private_key.end());
    
    auto hashed_key = double_sha256(extended_key);
    auto checksum = std::vector<unsigned char>(hashed_key.begin(), hashed_key.begin() + 4);
    
    extended_key.insert(extended_key.end(), checksum.begin(), checksum.end());
    return to_base58(extended_key);
}

std::vector<unsigned char> private_key_to_public_key(const std::vector<unsigned char>& private_key, bool compressed) {
    secp256k1_context* ctx = secp256k1_context_create(SECP256K1_CONTEXT_SIGN);
    secp256k1_pubkey pubkey;
    if (!secp256k1_ec_pubkey_create(ctx, &pubkey, private_key.data())) {
        secp256k1_context_destroy(ctx);
        throw std::runtime_error("Invalid private key");
    }

    std::vector<unsigned char> result;
    if (compressed) {
        unsigned char serialized[33];
        size_t len = 33;
        secp256k1_ec_pubkey_serialize(ctx, serialized, &len, &pubkey, SECP256K1_EC_COMPRESSED);
        result.assign(serialized, serialized + len);
    } else {
        unsigned char serialized[65];
        size_t len = 65;
        secp256k1_ec_pubkey_serialize(ctx, serialized, &len, &pubkey, SECP256K1_EC_UNCOMPRESSED);
        result.assign(serialized, serialized + len);
    }

    secp256k1_context_destroy(ctx);
    return result;
}

