 * @brief Simple struct representing a place (node where tokens reside).
 */
struct Place {
    string id;
    string name;
    int tokens = 0; // Initial marking
};

/**
 * @brief Simple struct representing a transition (node that can fire).
 */
struct Transition {
    string id;
    string name;
};

/**
 * @brief The main structure holding the entire Petri Net model.
 */
struct PetriNet {
    unordered_map<string, Place> places;
    unordered_map<string, Transition> transitions;
    vector<Arc> arcs;
};

// --- Utility function prototypes ---

/**
 * @brief Builds the incidence maps (pre- and post-sets) for transitions.
 * @param net The PetriNet to analyze.
 * @return A pair of maps: {preset, postset}.
 * - preset[TID] = list of input places for transition TID
 * - postset[TID] = list of output places for transition TID
 */
pair<unordered_map<string, vector<string>>,
     unordered_map<string, vector<string>>>
build_incidence_maps(const PetriNet &net)
{
    unordered_map<string, vector<string>> preset, postset;
    for (const auto &arc : net.arcs) {
        // Arc: Place -> Transition (consumes token: input to T)
        if (net.places.count(arc.source) && net.transitions.count(arc.target))
            preset[arc.target].push_back(arc.source);
        // Arc: Transition -> Place (produces token: output from T)
        else if (net.transitions.count(arc.source) && net.places.count(arc.target))
            postset[arc.source].push_back(arc.target);
    }
    return {preset, postset};
}

/**
 * @brief Extracts the initial marking M0 from the net structure.
 * @param net The PetriNet model.
 * @return An unordered_map representing the initial marking.
 */
unordered_map<string, int> initial_marking(const PetriNet &net)
{
    unordered_map<string, int> M;
    for (const auto &p : net.places)
        M[p.first] = p.second.tokens;
    return M;
}

/**
 * @brief Checks if a transition is enabled in the current marking (assuming arc weight 1).
 * @param tid The ID of the transition to check.
 * @param marking The current token distribution.
 * @param preset The map of transition presets (input places).
 * @return True if the transition is enabled, false otherwise.
 */
bool is_enabled(const string &tid,
                const unordered_map<string, int> &marking,
                const unordered_map<string, vector<string>> &preset)
{
    // A transition with no input places is always enabled (source transition)
    if (!preset.count(tid)) return true;

    // Check if every input place has at least one token
    for (const auto &p : preset.at(tid)) {
        // NOTE: This assumes all arcs have a weight of 1, as defined in the structs.
        if (marking.at(p) < 1) 
            return false;
    }
    return true;
}

/**
 * @brief Fires an enabled transition and computes the resulting new marking.
 * @param tid The ID of the transition to fire.
 * @param marking The current token distribution.
 * @param preset The map of transition presets (input places).
 * @param postset The map of transition postsets (output places).
 * @return The new token distribution (marking) after firing.
 */
unordered_map<string, int> fire_transition(
    const string &tid,
    const unordered_map<string, int> &marking,
    const unordered_map<string, vector<string>> &preset,
    const unordered_map<string, vector<string>> &postset)
{
    auto new_marking = marking;

    // Consume tokens from input places
    if (preset.count(tid))
        for (const auto &p : preset.at(tid))
            new_marking[p] -= 1; // Assuming weight 1

    // Produce tokens to output places
    if (postset.count(tid))
        for (const auto &p : postset.at(tid))
            new_marking[p] += 1; // Assuming weight 1

    return new_marking;
}

/**
 * @brief Converts a marking (token distribution) to a unique string key for set/map storage.
 * @param marking The token distribution map.
 * @param place_order The fixed order of place IDs for consistent key generation.
 * @return A delimited string key (e.g., "1,0,2,").
 */
string marking_to_key(const unordered_map<string, int> &marking,
                        const vector<string> &place_order)
{
    string key;
    for (const auto &p : place_order) {
        key += std::to_string(marking.at(p)) + ",";
    }
    return key;
}

