                std::transform(targetProcess.begin(), targetProcess.end(), targetProcess.begin(), ::tolower);
                
                if (currentProcess == targetProcess) {
                    pid = pe.th32ProcessID;
                    break;
                }
            } while (Process32Next(hSnapshot, &pe));
        }

        CloseHandle(hSnapshot);
        return pid;
    }

