#include "Optimizer.h"
#include "Brainfuck.h"

#include <cassert>

namespace llvm_bf {
std::vector<BFOpBundle>
Optimizer::optimize(const std::vector<BFOpBundle> &Insts) {
  // 1. Remove redundant ptr move
  std::vector<BFOpBundle> NewInsts;

  // net pointer movement: > is +1, < is -1
  int PtrDelta = 0;

  auto flush = [&] {
    if (PtrDelta > 0)
      NewInsts.emplace_back(BFOp::PTRINC, static_cast<size_t>(PtrDelta));
    else if (PtrDelta < 0)
      NewInsts.emplace_back(BFOp::PTRDEC, static_cast<size_t>(-PtrDelta));
    PtrDelta = 0;
  };

  for (auto I : Insts) {
    switch (I.Op) {
    case BFOp::PTRINC:
      PtrDelta += static_cast<int>(I.Num);
      break;
    case BFOp::PTRDEC:
      PtrDelta -= static_cast<int>(I.Num);
      break;

    // DbgDumpCell needs flush
    case BFOp::DbgAssert:
    case BFOp::DbgPrint:
    case BFOp::DbgComment:
    case BFOp::DbgTerminate:
      NewInsts.push_back(I);
      break;

    default:
      flush();
      NewInsts.push_back(I);
      break;
    }
  }

  // TODO: More optimizations

  return NewInsts;
}
