    // ATtiny85: 8MHz internal oscillator, remove /8 prescaler = 8MHz
    CLKPR = (1 << CLKPCE); // Enable clock prescaler change
    CLKPR = 0;             // Set prescaler to 1 (no division) = 8MHz


