using namespace llvm_bf;

class BF32BitInterpreter {
  using CellType = uint8_t;
  std::vector<CellType> Tape;
  size_t Pos = 0;

public:
  BF32BitInterpreter() { Tape.resize(1); }

  [[nodiscard]] bool isExitGood() const { return Tape[0] == 0; }

  [[nodiscard]] auto getExitCode() const { return Tape[0]; }

  void run(const std::vector<BFOpBundle> &Ops) {
    std::unordered_map<size_t, size_t> MatchMap;
    std::vector<size_t> Stack;
    for (size_t i = 0; i < Ops.size(); ++i) {
      if (Ops[i].Op == BFOp::BEQZ)
        Stack.push_back(i);
      else if (Ops[i].Op == BFOp::BNEZ) {
        assert(!Stack.empty() && "Unmatched ]");
        size_t open = Stack.back();
        Stack.pop_back();
        MatchMap[open] = i;
        MatchMap[i] = open;
      }
    }
    assert(Stack.empty() && "Unmatched [");

    size_t PC = 0;
    while (true) {
      switch (Ops[PC].Op) {
      case BFOp::PTRINC:
        Pos += Ops[PC].Num;
        if (Pos >= Tape.size())
          Tape.resize(Pos + 1);
        break;
      case BFOp::PTRDEC:
        assert(Pos >= Ops[PC].Num && "Pos out of range.");
        Pos -= Ops[PC].Num;
        break;
      case BFOp::INC:
        Tape[Pos] += Ops[PC].Num;
        break;
      case BFOp::DEC:
        Tape[Pos] -= Ops[PC].Num;
        break;
      case BFOp::OUTPUT: {
        assert(Ops[PC].Num == 1 && "Unsupported bundle.");
        auto CellVal = Tape[Pos];
        auto CharCellVal = static_cast<char>(CellVal);

        if (CellVal > 255)
          printf("\nOutput in [%lu]=%d is out of range.\n", Pos, CellVal);
        else if (!isascii(CharCellVal))
          printf("\nOutput in [%lu]=%d is not in ASCII set.\n", Pos,
                 CharCellVal);
        else if (!isprint(CharCellVal) && CharCellVal != '\n' &&
                 CharCellVal != '\r') {
          printf("\nOutput in [%lu]=%d is not printable.\n", Pos, CharCellVal);
        }

        putchar(CharCellVal);
        fflush(stdout);
      } break;
      case BFOp::INPUT:
        assert(Ops[PC].Num == 1 && "Unsupported bundle.");
        Tape[Pos] = getchar();
        break;
      case BFOp::BEQZ:
        assert(Ops[PC].Num == 1 && "Unsupported bundle.");
        if (Tape[Pos] == 0)
          PC = MatchMap.at(PC);
        break;
      case BFOp::BNEZ:
        assert(Ops[PC].Num == 1 && "Unsupported bundle.");
        if (Tape[Pos] != 0)
          PC = MatchMap.at(PC);
        break;

      case BFOp::DbgDumpCell:
        assert(Ops[PC].Num == 1 && "Unsupported bundle.");
        printf("\nDebug Dumping Cell, [%lu]=%d\n", Pos, Tape[Pos]);
        fflush(stdout);
        break;

      case BFOp::DbgTerminate:
        assert(Ops[PC].Num == 1 && "Unsupported bundle.");
        printf("\n<DbgTerminate>\n");
        fflush(stdout);
        return;

      case BFOp::DbgAssert: {
        const auto &A = Ops[PC].Assert;

        auto CheckVal = [](int64_t LHS, int64_t RHS, BFAssert::AssertType Ty) {
          switch (Ty) {
          case BFAssert::AssertType::EQ:
            return LHS == RHS;
          case BFAssert::AssertType::NE:
            return LHS != RHS;
          case BFAssert::AssertType::LT:
            return LHS < RHS;
          case BFAssert::AssertType::GT:
            return LHS > RHS;
          case BFAssert::AssertType::LE:
            return LHS <= RHS;
          case BFAssert::AssertType::GE:
            return LHS >= RHS;
          }
          assert(false);
          return false;
        };

        auto FailMsg = "\nBrainfuck Assertion '" + A.toString(false) +
                       "' failed: '" + A.Msg + "'. Cause: ";
        if (A.Pos == BFAssert::DATA_POINTER) {
          if (!CheckVal(static_cast<int64_t>(Pos), A.Val, A.Type)) {
            printf("\n%sData Pointer=%lu", FailMsg.c_str(), Pos);
            dumpTape();
