{
    if(isEditing){ return; }

    scrollVal += scrollDelta;

    if(loopScroll){
        scrollVal = scrollVal % itemCount; //Loop scrolling implementation using modulo
    }
    else{
        if(scrollVal >= itemCount){
            scrollVal = itemCount - 1;
        }
        else if (scrollVal < 0){
            scrollVal = 0;
        }
    }

