struct Symbol
{
    string name;
    string type;
    string size;
    string dimension;
    string lineDeclared;
    string address;
    list<string> usageLines; // tracks all lines where used (including declaration)

    Symbol(string n, string t, string s, string d, string line, string addr)
        : name(n), type(t), size(s), dimension(d), lineDeclared(line), address(addr)
    {
        usageLines.push_back(line); // first usage = declaration
    }

    void addUsage(const string &line)
    {
        usageLines.push_back(line);
    }

    void print() const
    {
        cout << "Name: " << name
             << ", Type: " << type
             << ", Size: " << size
             << ", Dimension: " << dimension
             << ", Declared at: " << lineDeclared
             << ", Address: " << address
             << ", Usage Lines: ";
        for (auto it = usageLines.begin(); it != usageLines.end(); ++it)
        {
            if (it != usageLines.begin())
                cout << ", ";
            cout << *it;
        }
        cout << endl;
    }
};

class SymbolTable
{
private:
    static const int TABLE_SIZE = 101; // prime number for better distribution
    vector<list<Symbol>> table;

    // Hash function: sum of ASCII values mod TABLE_SIZE
    int hashFunction(const string &name) const
    {
        int hash = 0;
        for (char c : name)
        {
            hash += static_cast<int>(c);
        }
        return hash % TABLE_SIZE;
    }

public:
    SymbolTable() : table(TABLE_SIZE) {}

    // 6. Get hash key
    int getHashKey(const string &name) const
    {
        return hashFunction(name);
    }

    // 1. Insert
    bool insert(const string &name, const string &type, const string &size,
                const string &dimension, const string &line, const string &address)
    {
        int index = hashFunction(name);
        for (auto &sym : table[index])
        {
            if (sym.name == name)
            {
                cout << "Error: Symbol '" << name << "' already exists.\n";
                return false;
            }
        }
        table[index].emplace_back(name, type, size, dimension, line, address);
        cout << "Inserted: " << name << " (Hash: " << index << ")\n";
        return true;
    }

    // 2. Search
    Symbol *search(const string &name)
    {
        int index = hashFunction(name);
        for (auto &sym : table[index])
        {
            if (sym.name == name)
            {
                return &sym;
            }
        }
        return nullptr;
    }

    // 5. Update (only if exists)
    bool update(const string &name, const string &type, const string &size,
                const string &dimension, const string &line, const string &address)
    {
        int index = hashFunction(name);
        for (auto &sym : table[index])
        {
            if (sym.name == name)
            {
                sym.type = type;
                sym.size = size;
                sym.dimension = dimension;
                sym.lineDeclared = line;
                sym.address = address;
                // Optionally reset usage or keep it — we keep existing usage
                cout << "Updated: " << name << endl;
                return true;
            }
        }
        cout << "Error: Symbol '" << name << "' not found for update.\n";
        return false;
    }

    // 3. Delete
    bool remove(const string &name)
    {
        int index = hashFunction(name);
        auto &bucket = table[index];
        for (auto it = bucket.begin(); it != bucket.end(); ++it)
        {
            if (it->name == name)
            {
                bucket.erase(it);
                cout << "Deleted: " << name << endl;
                return true;
            }
        }
        cout << "Error: Symbol '" << name << "' not found.\n";
        return false;
    }

    // 4. Display entire symbol table
    void display() const
    {
        cout << "\n=== SYMBOL TABLE ===\n";
        bool empty = true;
        for (int i = 0; i < TABLE_SIZE; i++)
        {
            if (!table[i].empty())
            {
                cout << "Bucket " << i << ":\n";
                for (const auto &sym : table[i])
                {
                    cout << "  ";
                    sym.print();
                    empty = false;
                }
            }
        }
        if (empty)
        {
            cout << "Empty.\n";
        }
        cout << "=====================\n";
    }

