Type stringToType(const std::string &name) {
    const auto lowered = ctoon::toLower(name);
    if (lowered == "json") {
        return ctoon::Type::JSON;
    }
    if (lowered == "toon") {
        return ctoon::Type::TOON;
    }
    return ctoon::Type::UNKNOWN;
}

