        return EXIT_FAILURE;
    }

    string path = argv[1];
    bool showStats = false;

    for(int i = 2; i < argc; i++) {
        if(string(argv[i]) == "--stats") {
            showStats = true;
            break;
        }
    }

    try {
        auto image = ImageLoader::load(path);
        cout << "TPNG: https://github.com/AaryanKhClasses/tpng" << endl;
        if(showStats) cout << "Loaded Image: " << path.substr(path.find_last_of("/\\") + 1) <<
            "\nWidth: " << image.width <<
            "\nHeight: " << image.height <<
            "\nChannels: " << image.channels << endl;


        auto termSize = Terminal::getSize();
        double aspect = 0.5;
        int scale = 1;

        int maxWidth = termSize.width - 2;

        int estimatedWidth = image.width / scale;
        if (estimatedWidth > maxWidth) {
            scale = (image.width + maxWidth - 1) / maxWidth;
            if(showStats) cout << "Image rescaled to fit terminal width (scale: " << scale << ")" << endl;
        }

        Renderer::renderColorASCII(image.data, image.width, image.height, aspect, scale);
    } catch(const exception& err) {
        cerr << "Error: " << err.what() << endl;
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

