class Contact {
public:
    string name;
    string phone;
    string email;

    void getData() {
        cout << "Enter Name: ";
        getline(cin, name);
        cout << "Enter Phone Number: ";
        getline(cin, phone);
        cout << "Enter Email: ";
        getline(cin, email);
    }

    void showData() const {
        cout << left << setw(20) << name 
             << setw(15) << phone 
             << setw(25) << email << endl;
    }
};

void addContact() {
    ofstream fout("addressbook.txt", ios::app);
    Contact c;
    cin.ignore();
    c.getData();
    fout << c.name << "|" << c.phone << "|" << c.email << "\n";
    fout.close();
    cout << "\nContact added successfully!\n";
}

void showAllContacts() {
    ifstream fin("addressbook.txt");
    if (!fin) {
        cout << "No contacts found.\n";
        return;
    }

    cout << "\n--- Contact List ---\n";
    cout << left << setw(20) << "Name" 
         << setw(15) << "Phone" 
         << setw(25) << "Email" << endl;
    cout << string(60, '-') << endl;

    string line;
    while (getline(fin, line)) {
        size_t p1 = line.find('|');
        size_t p2 = line.find('|', p1 + 1);

        Contact c;
        c.name = line.substr(0, p1);
        c.phone = line.substr(p1 + 1, p2 - p1 - 1);
        c.email = line.substr(p2 + 1);

        c.showData();
    }
    fin.close();
}

void searchContact() {
    ifstream fin("addressbook.txt");
    if (!fin) {
        cout << "No contacts found.\n";
        return;
    }

    string searchName;
    cout << "Enter name to search: ";
    cin.ignore();
    getline(cin, searchName);

    string line;
    bool found = false;

    while (getline(fin, line)) {
        size_t p1 = line.find('|');
        size_t p2 = line.find('|', p1 + 1);

        Contact c;
        c.name = line.substr(0, p1);
        c.phone = line.substr(p1 + 1, p2 - p1 - 1);
        c.email = line.substr(p2 + 1);

        if (c.name == searchName) {
            cout << "\nContact Found:\n";
            cout << left << setw(20) << "Name" 
                 << setw(15) << "Phone" 
                 << setw(25) << "Email" << endl;
            cout << string(60, '-') << endl;
            c.showData();
            found = true;
            break;
        }
    }

    if (!found) cout << "\nContact not found.\n";
    fin.close();
}

void deleteContact() {
    ifstream fin("addressbook.txt");
    ofstream fout("temp.txt");

    if (!fin) {
        cout << "No contacts to delete.\n";
        return;
    }

    string deleteName;
    cout << "Enter name to delete: ";
    cin.ignore();
    getline(cin, deleteName);

    string line;
    bool deleted = false;

    while (getline(fin, line)) {
        size_t p1 = line.find('|');
        string name = line.substr(0, p1);

        if (name != deleteName) {
            fout << line << "\n";
        } else {
            deleted = true;
        }
    }

    fin.close();
    fout.close();

    remove("addressbook.txt");
    rename("temp.txt", "addressbook.txt");

    if (deleted)
        cout << "\nContact deleted successfully.\n";
    else
        cout << "\nContact not found.\n";
}

