        cin >> choice;

        switch (choice) {
        case 1: addContact(); break;
        case 2: showAllContacts(); break;
        case 3: searchContact(); break;
        case 4: deleteContact(); break;
        case 5: cout << "Exiting program...\n"; break;
        default: cout << "Invalid choice. Try again.\n";
        }
    } while (choice != 5);

    return 0;
}

