template<std::size_t S>
class Element {
  public:
    Element(const double d = .0f) {

        data = new std::array<double, S>;
        std::fill(data->begin(), data->end(), d);
    }

    Element(const Element &element) {

        data = new std::array<double, S>;
        *data = *element.data;
    }

    Element & operator = (const Element &element) {

        if(data) {
            delete data;
            data = new std::array<double, S>;
        }
        *data = *(element.data);
        return *this;
    }

    Element & operator = (Element &&element) {

        if(data) {
            delete data;
        }
        data = element.data;
        element.data = nullptr;
        return *this;
    }

    Element(Element &&element) {

        data = element.data;
        element.data = nullptr;
    }

    ~Element() {

        if(data) { delete data; data = nullptr; }
    }

    std::array<double, S> *data;
};

template<std::size_t S>
inline bool operator == (const Element<S> &left, const Element<S> &right) {

    return *left.data == *right.data;
}

template<std::size_t S>
inline bool operator != (const Element<S> &left, const Element<S> &right) {

    return *left.data != *right.data;
}

