BluetoothSerial BT;

const int botaoPin = 0; 
const int ledPin = 2;   

enum EstadoLed { DESLIGADO, ACESO, PISCANDO };
EstadoLed estadoLed = DESLIGADO;

bool botaoAnterior = HIGH;
unsigned long tempoPressionado = 0;
unsigned long ultimoMillis = 0;
bool ledLigado = false;

void setup() {
  Serial.begin(115200);
  pinMode(botaoPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);

  if (!BT.begin("espSlavePietra0")) {
    Serial.println("Erro ao iniciar Bluetooth Slave");
    while (1);
  }
  Serial.println("Bluetooth Slave iniciado e aguardando conexão...");
}

void loop() {
  bool botaoAtual = digitalRead(botaoPin);


  if (botaoAnterior == HIGH && botaoAtual == LOW) tempoPressionado = millis();


  if (botaoAnterior == LOW && botaoAtual == HIGH) {
    unsigned long duracao = millis() - tempoPressionado;


    if (duracao < 2000) {
      BT.println("toggle");
      Serial.println("Comando enviado: toggle");
    } 

    else {
      BT.println("pisca");
      Serial.println("Comando enviado: pisca");
    }
  }
  botaoAnterior = botaoAtual;


  if (BT.available()) {
    String comando = BT.readStringUntil('\n');
    comando.trim();
    Serial.printf("Comando recebido: %s\n", comando.c_str());

    if (comando.equalsIgnoreCase("toggle")) {
      if (estadoLed == DESLIGADO) estadoLed = ACESO;
      else if (estadoLed == ACESO || estadoLed == PISCANDO) estadoLed = DESLIGADO;
    } 
    else if (comando.equalsIgnoreCase("pisca")) {
      estadoLed = PISCANDO;
      ledLigado = false;
      ultimoMillis = millis();
    }
  }


  if (estadoLed == DESLIGADO) {
    digitalWrite(ledPin, LOW);
  } 
  else if (estadoLed == ACESO) {
    digitalWrite(ledPin, HIGH);
  } 
  else if (estadoLed == PISCANDO) {
    unsigned long agora = millis();
    if (agora - ultimoMillis >= 500) {
      ledLigado = !ledLigado;
      digitalWrite(ledPin, ledLigado ? HIGH : LOW);
      ultimoMillis = agora;
    }
  }
}

#include <sstream>
#include <iomanip>
#include <cctype>
#include <stdexcept>

#include "yamln.h"  // Assuming the header file is named yamln.h; adjust if necessary

namespace yamln {

static std::string format_key(const std::string& key) {
    if (key.empty()) {
        std::ostringstream oss;
        oss << std::quoted(key);
        return oss.str();
    }

    char first = key[0];
    if (!std::isalpha(static_cast<unsigned char>(first)) && first != '_') {
        std::ostringstream oss;
        oss << std::quoted(key);
        return oss.str();
    }

    bool needs_quote = false;
    for (char c : key) {
        if (!std::isalnum(static_cast<unsigned char>(c)) && c != '_' && c != '-') {
            needs_quote = true;
            break;
        }
    }

    if (needs_quote) {
        std::ostringstream oss;
        oss << std::quoted(key);
        return oss.str();
    }

    return key;
}

static bool is_scalar(const Node& node) {
    return node.is_null() || node.is_bool() || node.is_number() || node.is_string() || node.is_alias();
}

static void serialize_scalar(const Node& node, std::ostream& os) {
    if (node.is_alias()) {
        const Node& ref_node = node.as_alias();
        if (!ref_node.anchor) {
            throw std::runtime_error("Alias references a node without an anchor");
        }
        os << "*" << *ref_node.anchor;
        return;
    }

    if (node.is_null()) {
        os << "null";
    } else if (node.is_bool()) {
        os << (node.as_bool() ? "true" : "false");
    } else if (std::holds_alternative<int>(node.data)) {
        os << std::get<int>(node.data);
    } else if (std::holds_alternative<double>(node.data)) {
        os << std::get<double>(node.data);
    } else if (node.is_string()) {
        os << std::quoted(node.as_string());
    } else {
        throw std::runtime_error("Not a scalar node");
    }
}

static void serialize_container(const Node& node, std::ostream& os, int indent) {
    if (node.is_sequence()) {
        const Sequence& seq = node.as_sequence();
        if (seq.empty()) {
            os << "[]";
            return;
        }

        bool first = true;
        for (const Node& item : seq) {
            if (!first) {
                os << "\n";
            }
            first = false;

            os << std::string(indent, ' ') << "-";
            std::string anch = item.anchor ? " &" + *item.anchor : "";
            os << anch;

            if (is_scalar(item)) {
                os << " ";
                serialize_scalar(item, os);
            } else {
                os << "\n";
                serialize_container(item, os, indent + 2);
            }
        }
    } else if (node.is_mapping()) {
        const Mapping& map = node.as_mapping();
        if (map.empty()) {
            os << "{}";
            return;
        }

        bool first = true;
        for (const auto& kv : map) {
            if (!first) {
                os << "\n";
            }
            first = false;

            os << std::string(indent, ' ') << format_key(kv.first) << ":";
            const Node& val = kv.second;
            std::string anch = val.anchor ? " &" + *val.anchor : "";
            os << anch;

            if (is_scalar(val)) {
                os << " ";
                serialize_scalar(val, os);
            } else {
                os << "\n";
                serialize_container(val, os, indent + 2);
            }
        }
    } else {
        throw std::runtime_error("Not a container node");
    }
}

__attribute__((visibility("default"))) std::string serialize(const Node& n) {
    std::ostringstream os;

    bool is_scalar_type = is_scalar(n);

    std::string anch = n.anchor ? "&" + *n.anchor : "";
    if (!anch.empty()) {
        os << anch;
        if (is_scalar_type) {
            os << " ";
        } else {
            os << "\n";
        }
    }

    if (is_scalar_type) {
        serialize_scalar(n, os);
    } else {
        serialize_container(n, os, 0);
    }

    return os.str();
}

