vector<string>SplitString(string S, string Del)
{
	vector <string>vCl;
	string word;
	short pos = 0;

	while ((pos = S.find(Del)) != std::string::npos)
	{
		word = S.substr(0, pos);
		if (word != "")
		{
			vCl.push_back(word);
		}

		S.erase(0, pos + Del.length());
	}
	if (S != "")
	{
		vCl.push_back(S);
	}
	return vCl;
}

string ConvertRecordToLine(stDataClient DataClient, string Sper = "#//#")
