// UAC 提权重启自己（不等子进程）
bool RelaunchSelfElevatedAndExit() {
    wchar_t exePath[MAX_PATH] = { 0 };
    if (!GetModuleFileNameW(nullptr, exePath, MAX_PATH)) return false;

    SHELLEXECUTEINFOW sei{};
    sei.cbSize = sizeof(sei);
    sei.fMask = SEE_MASK_NOCLOSEPROCESS;
    sei.lpVerb = L"runas";     // 触发 UAC
    sei.lpFile = exePath;
    sei.nShow = SW_SHOWNORMAL;

    DebugLog(L"RelaunchSelfElevated: %s", exePath);
    if (!ShellExecuteExW(&sei)) {
        DWORD ec = GetLastError();
        DebugLog(L"ShellExecuteEx failed: %lu %s", ec, LastErrMsg(ec).c_str());
        DebugPopup(L"UAC 提权被拒绝或启动失败。\n错误=" + std::to_wstring(ec) + L"\n" + LastErrMsg(ec), L"错误");
        return false;
    }
    ExitProcess(0);
    return true;
}

