	{
		char *pp;
		HAllocTmp(proc_handle, &pp, 1024);

		memcpy(pp, p, 1024);
		HPutElem(proc_handle, 1, &pp, 1, STRING_PAR);
		return H_MSG_TRUE;
	}
	else if (BufferSize.par.l == 0)
	{
		return engOutputBuffer(ep, NULL, 0) + H_MSG_TRUE;
	}
	else
	{
		return engOutputBuffer(ep, p, BufferSize.par.l) + H_MSG_TRUE;
	}
}

