// CLASS BARANG
class barang {
    public:
        string nama;
        int jumlah;
        double harga;

        barang(string n, int j, double h) {
            nama = n;
            jumlah = j;
            harga = h;
        }

        double total() const {
            return jumlah * harga;
        }
};

//class kasir
class kasir {
    private:
        vector<barang> daftar_barang;
        double totalBelanja = 0;

    public:
    //tambahkan fungsi
    void tambahBarang() {
        string nama;
        int jumlah;
        double harga;
        char lagi;

        do {
            //input barang, harga, dan jumlah
            cout << "\nMasukan Nama Barang: ";
            cin >> ws;
            getline(cin, nama);
            cout << "Masukan Harga Barang: ";
            cin >> harga;
            cout << "Masukan Jumlah Barang: ";
            cin >> jumlah;

            //daftarkan ke daftar barang
            barang b(nama, jumlah, harga);
            daftar_barang.push_back(b);

            //kode konfirm
            cout << "Tambah barang lagi? (y/n)";
            cin >> lagi;

            //agar dapat menggunakan huruf kapital/nonkapital
            lagi = toupper(lagi);
            cout << endl;
        } while (lagi == 'Y');
    }

    void hitungTotal() {
        totalBelanja = 0;
        for (auto &b : daftar_barang) {
            totalBelanja += b.total();
        }
    }

    void cetakStruk() {
        ofstream file("struk.txt"); //file untuk di isi oleh struk
        double bayar, kembalian;

        hitungTotal();

        cout << fixed << setprecision(2);
        cout << "\n====================\n";
        cout << "   STRUK PEMBAYARAN    \n";
