// ------------------------- Resource Loading Helpers -------------------------

/**
 * @brief Creates an IStream from a Win32 resource.
 */
IStream* createStreamFromResource(HMODULE hModule, WORD resourceId) {
	HRSRC hResInfo = FindResource(hModule, MAKEINTRESOURCE(resourceId), L"SVG");
	if (!hResInfo) return nullptr;
	DWORD resSize = SizeofResource(hModule, hResInfo);
	if (resSize == 0) return nullptr;
	HGLOBAL hResData = LoadResource(hModule, hResInfo);
	if (!hResData) return nullptr;
	LPVOID pRes = LockResource(hResData);
	if (!pRes) return nullptr;

	// Create a new HGLOBAL and copy the resource data into it.
	HGLOBAL hMem = GlobalAlloc(GMEM_MOVEABLE, resSize);
	if (!hMem) return nullptr;
	LPVOID pMem = GlobalLock(hMem);
	if (!pMem) {
		GlobalFree(hMem);
		return nullptr;
	}
	memcpy(pMem, pRes, resSize);
	GlobalUnlock(hMem);

	IStream* pStream = nullptr;
	// TRUE means the stream will call GlobalFree on hMem when it is released.
	HRESULT hr = CreateStreamOnHGlobal(hMem, TRUE, &pStream);
	if (FAILED(hr)) {
		GlobalFree(hMem);
		return nullptr;
	}
	return pStream;
}

/**
 * @brief Maps a card's suit and rank to its corresponding resource ID.
