WORD getCardResourceId(Suit s, int r) {
	if (r < 1 || r > 13) return 0; // Invalid rank

	// Assumes resource.h defines these IDs as provided by the user
	static const WORD spades_ids[] = { IDR_SVG101, IDR_SVG102, IDR_SVG103, IDR_SVG104, IDR_SVG105, IDR_SVG106, IDR_SVG107, IDR_SVG108, IDR_SVG109, IDR_SVG110, IDR_SVG111, IDR_SVG112, IDR_SVG113 };
	static const WORD hearts_ids[] = { IDR_SVG201, IDR_SVG202, IDR_SVG203, IDR_SVG204, IDR_SVG205, IDR_SVG206, IDR_SVG207, IDR_SVG208, IDR_SVG209, IDR_SVG210, IDR_SVG211, IDR_SVG212, IDR_SVG213 };
	static const WORD clubs_ids[] = { IDR_SVG301, IDR_SVG302, IDR_SVG303, IDR_SVG304, IDR_SVG305, IDR_SVG306, IDR_SVG307, IDR_SVG308, IDR_SVG309, IDR_SVG310, IDR_SVG311, IDR_SVG312, IDR_SVG313 };
	static const WORD diamonds_ids[] = { IDR_SVG401, IDR_SVG402, IDR_SVG403, IDR_SVG404, IDR_SVG405, IDR_SVG406, IDR_SVG407, IDR_SVG408, IDR_SVG409, IDR_SVG410, IDR_SVG411, IDR_SVG412, IDR_SVG413 };

	switch (s) {
	case Suit::Spades: return spades_ids[r - 1];
	case Suit::Hearts: return hearts_ids[r - 1];
	case Suit::Clubs: return clubs_ids[r - 1];
	case Suit::Diamonds: return diamonds_ids[r - 1];
	}
	return 0; // Unreachable
}


