uniform vec2 resolution;
uniform vec4 window_bounds;
uniform sampler2D water_state_texture;
uniform sampler2D original_scene_texture;
uniform float damping_factor;
uniform float boundary_threshold;
uniform float boundary_force_strength;
uniform float color_morph_factor;
uniform float is_hiding;
varying highp vec2 uvpos;
void main() {
    float dx = 1.0 / resolution.x;
    float dy = 1.0 / resolution.y;
    vec4 current = texture2D(water_state_texture, uvpos);
    vec3 color = current.rgb;
    float u = current.a;
    float u_n = texture2D(water_state_texture, vec2(uvpos.x, uvpos.y + dy)).a;
    float u_s = texture2D(water_state_texture, vec2(uvpos.x, uvpos.y - dy)).a;
    float u_e = texture2D(water_state_texture, vec2(uvpos.x + dx, uvpos.y)).a;
    float u_w = texture2D(water_state_texture, vec2(uvpos.x - dx, uvpos.y)).a;
    float laplacian = u_w + u_e + u_s + u_n - 4.0 * u;
    float nu = u + laplacian * 0.5;
    vec2 screen_pos = uvpos * resolution;
    vec2 dist_to_min = screen_pos - window_bounds.xy;
    vec2 dist_to_max = (window_bounds.xy + window_bounds.zw) - screen_pos;
    vec2 force = (1.0 - smoothstep(0.0, boundary_threshold, dist_to_min)) +
                 (1.0 - smoothstep(0.0, boundary_threshold, dist_to_max));
    nu -= (force.x + force.y) * boundary_force_strength;
    vec2 in_window = step(window_bounds.xy, screen_pos) * step(screen_pos, window_bounds.xy + window_bounds.zw);
    float boundary_damp = mix(0.5, 1.0, in_window.x * in_window.y);
    nu *= damping_factor * boundary_damp;
    vec3 original_color = texture2D(original_scene_texture, uvpos).rgb;

    // Override colors to exactly match original texture
    if (is_hiding > 0.5) {
