class Point {
    private:
        double x, y;
        int cluster_id;
    public:
        Point(double x, double y) : x(x), y(y), cluster_id(-1) {};

        double getX() const { return x; }
        double getY() const { return y; }
        int getCluster_id() const { return cluster_id; }

        void setCluster_id(int id) { cluster_id = id; }

        double distance(const Point &other) const {
            double dist = std::sqrt((x - other.x) * (x - other.x) + 
                                   (y - other.y) * (y - other.y));
            return dist;
        }
};

class Cluster {
    private:
        int cluster_id;
        Point centroid;
        Point old_centroid;
        std::vector<Point*> points;
    public:
        Cluster(int id, Point centroid) : cluster_id(id), centroid(centroid), old_centroid(centroid) {}

        int getId() const { return cluster_id; }
        Point getCentroid() const { return centroid; }
        Point getOld_centroid() const { return old_centroid; }
        int getQuantity() { return points.size(); }
        const std::vector<Point*>& getPoints() const { return points; }

        void addPoint(Point *point) {
            if (point != nullptr) {
                points.push_back(point);
                point->setCluster_id(this->cluster_id);
            }
        }

        void clearPoints() {
            points.clear();
        }

        void updateCentroid() {
            old_centroid = centroid;
            if (points.empty()) { return; }
            double sum_x = 0, sum_y = 0;
            for (Point *point : points) {
                sum_x += point->getX();
                sum_y += point->getY();
            }
            centroid = Point(sum_x / points.size(), sum_y / points.size());
        }
};

