namespace klux {

ArenaAllocator::ArenaAllocator(size_t chunkSize)
    : defaultChunkSize_(chunkSize) {
}

ArenaAllocator::~ArenaAllocator() {
    for (auto& chunk : chunks_) {
        if (chunk.memory) {
            platform::freeVirtualMemory(chunk.memory, chunk.size);
        }
    }
}

void* ArenaAllocator::allocate(size_t size, size_t alignment) {
    if (size == 0) return nullptr;

    if (chunks_.empty() || chunks_.back().offset + size + alignment > chunks_.back().size) {
        size_t chunkSize = std::max(defaultChunkSize_, size + alignment);
        if (!allocateNewChunk(chunkSize)) {
            return nullptr;
        }
    }

    Chunk& chunk = chunks_.back();
    uintptr_t current = reinterpret_cast<uintptr_t>(chunk.memory) + chunk.offset;
    uintptr_t aligned = platform::alignForward(current, alignment);
    size_t padding = aligned - current;

    if (chunk.offset + padding + size > chunk.size) {
        size_t chunkSize = std::max(defaultChunkSize_, size + alignment);
        if (!allocateNewChunk(chunkSize)) {
            return nullptr;
        }
        return allocate(size, alignment);
    }

    chunk.offset += padding + size;
    stats_.onAllocate(size);

    return reinterpret_cast<void*>(aligned);
}

void ArenaAllocator::deallocate(void* ptr) {
    (void)ptr;
}

void ArenaAllocator::reset() {
    for (auto& chunk : chunks_) {
        chunk.offset = 0;
    }
    stats_.onReset();
}

bool ArenaAllocator::allocateNewChunk(size_t minSize) {
    void* memory = platform::allocateVirtualMemory(minSize);
    if (!memory) return false;

    chunks_.push_back({memory, minSize, 0});
    return true;
}

size_t ArenaAllocator::getTotalCapacity() const {
    size_t total = 0;
    for (const auto& chunk : chunks_) {
        total += chunk.size;
    }
    return total;
}

