void MainWindow::initializeGame(int start_x, int start_y)
{
    srand(time(0));
    int bombCount = BOMBS;
    int rand_x, rand_y;

    while (bombCount > 0)
    {
        rand_x = rand() % WIDTH;   // random numbers from 0 to and including 29
        rand_y = rand() % HEIGHT;   // random numbers from 0 to and including 15

        // initialize bombs away from the first revealed tile and the 3x3 surrounding it
        if (((rand_x > start_x + 1 || rand_x < start_x - 1) ||
             (rand_y > start_y + 1 || rand_y < start_y - 1)) &&
            !(buttonList[rand_x][rand_y]->isBomb()))
        {
            buttonList[rand_x][rand_y]->setBomb(true);
            bombCount--;
        }
    }

    // Initialize numbers
    int count = 0;
    for (int x = 0; x < WIDTH; x++)
    {
        for (int y = 0; y < HEIGHT; y++)
        {
            if (!buttonList[x][y]->isBomb())
            {
                if (x != 0 && buttonList[x-1][y]->isBomb()) // left
                {
                    count++;
                }
                if (x != WIDTH-1 && buttonList[x+1][y]->isBomb()) // right
                {
                    count++;
                }
                if (y != 0 && buttonList[x][y-1]->isBomb()) // top
                {
                    count++;
                }
                if (y != HEIGHT-1 && buttonList[x][y+1]->isBomb()) // bottom
                {
                    count++;
                }
                if (x != 0 && y != 0 && buttonList[x-1][y-1]->isBomb()) // top left
                {
                    count++;
                }
                if (x != WIDTH-1 && y != 0 && buttonList[x+1][y-1]->isBomb()) // top right
                {
                    count++;
                }
                if (x != 0 && y != HEIGHT-1 && buttonList[x-1][y+1]->isBomb())  // bottom left
                {
                    count++;
                }
                if (x != WIDTH - 1 && y != HEIGHT-1 && buttonList[x+1][y+1]->isBomb())  // bottom right
                {
                    count++;
                }
                buttonList[x][y]->setNumber(count);
                count = 0;
            }
        }
    }
    // End of Function
}

