bool IsSuspectPipe(const std::wstring& pipe) {
    std::wstring lower = pipe;
    for (auto& c : lower) c = towlower(c);

    // PsExec pipes
    if (lower.find(L"psexec") != std::wstring::npos) return true;
    if (lower.find(L"paexec") != std::wstring::npos) return true;

    // Other lateral movement tools
    if (lower.find(L"remcom") != std::wstring::npos) return true;
    if (lower.find(L"csexec") != std::wstring::npos) return true;
    if (lower.find(L"winexe") != std::wstring::npos) return true;

    // Cobalt Strike / Metasploit
    if (lower.find(L"msagent") != std::wstring::npos) return true;
    if (lower.find(L"msse-") != std::wstring::npos) return true;
    if (lower.find(L"status_") != std::wstring::npos) return true;

    return false;
}

std::wstring ExtractShareName(const std::wstring& path) {
    if (path.empty()) return L"";

    // Format: \\computername\sharename\path
    size_t pos = path.find(L'\\', 2);
    if (pos == std::wstring::npos) return L"";

    size_t pos2 = path.find(L'\\', pos + 1);
    if (pos2 == std::wstring::npos) return path.substr(pos + 1);

    return path.substr(pos + 1, pos2 - pos - 1);
}

