// метод отправки по eth udp
bool Sender::EthUDPSend(const char* message, byte* ip, const int udpPort)
{
  EthUDPClient.begin(udpPort);
  EthUDPClient.beginPacket(ip, udpPort);
  EthUDPClient.write(message);
  bool packetSent = EthUDPClient.endPacket();

  if (!packetSent) 
  {
    Serial.println("Ошибка: не удалось отправить UDP пакет");
    EthUDPClient.stop();
    return false;
  }

  EthUDPClient.stop();
  return true;
}

// метод отправки по eth tcp
bool Sender::EthTCPSend(const char* message, byte* ip, const int tcpPort)
{
  if (!EthTCPClient.connect(ip, tcpPort)) 
  {
    Serial.println("Ошибка подключения к TCP серверу");
    EthTCPClient.stop();
    return false;
  }

  // Устанавливаем таймаут для операций
  EthTCPClient.setTimeout(5000);

  // Отправляем данные
  Serial.println("Данные для отправки: " + String(message));
  size_t bytesWritten = EthTCPClient.print(message);

  // Ждем отправки всех данных
  EthTCPClient.flush();

  // Проверяем успешность отправки
  bool success = (bytesWritten == strlen(message));

  // Закрываем соединение
  EthTCPClient.stop();
  return success;
}

// метод отправки по TCP через WiFi
bool Sender::WiFiTCPSend(String message, byte* ip, const int tcpPort)
{
  if (!WiFiTCPClient.connect(ip, tcpPort)) 
  {
    Serial.println("Ошибка подключения к TCP серверу");
    WiFiTCPClient.stop();
    return false;
  }

  // Устанавливаем таймаут для операций
  WiFiTCPClient.setTimeout(5000);

  // Отправляем данные
  Serial.println("Данные для отправки: " + message);
  size_t bytesWritten = WiFiTCPClient.print(message);

  // Ждем отправки всех данных
  WiFiTCPClient.flush();

  // Проверяем успешность отправки
  bool success = (bytesWritten == message.length());

  // Закрываем соединение
  WiFiTCPClient.stop();
  return success;
}

// метод отправки по wifi udp
bool Sender::WiFiUDPSend(String message, byte* ip, const int udpPort)
{
  WiFiUDPClient.begin(udpPort);

  // Генерируем уникальный ID для пакета
  static uint16_t packetId = 0;
  packetId++;
  String messageWithId = String(packetId) + ":" + message;

  // Отправка данных
  WiFiUDPClient.beginPacket(ip, udpPort);
  size_t bytesWritten = WiFiUDPClient.print(messageWithId);
  bool packetSent = WiFiUDPClient.endPacket();

  if (!packetSent) 
  {
    Serial.println("Ошибка: не удалось отправить UDP пакет");
    WiFiUDPClient.stop();
    return false;
  }

  Serial.println("UDP пакет отправлен в буфер. Ожидание подтверждения...");
  Serial.println("ID пакета: " + String(packetId) + ", данные: " + message);

  WiFiUDPClient.stop();
  return true;
}

// метод подключения к wifi как клиент
void Sender::ConnectWifi(char* ssid, char* password, bool dhcp, byte* ip)
{
  // Попытка подключения к Wi-Fi
  if (strlen(ssid) > 0 && strlen(password) > 0) 
  {
    if (!dhcp)
    {
      if (ip != nullptr)
        WiFi.config(ip);
      else
      {
        Serial.println("Невозможно подключиться к wifi. Пустой ip");
        return;
      }
    }

    WiFi.begin(ssid, password);
    int attempts = 0;
    while (WiFi.status() != WL_CONNECTED && attempts < 10) 
    {
      delay(500);
      attempts++;
    }
  }
}

// метод подлючения к eth
void Sender::ConnectEth(bool dhcp, byte* ip)
{
  Serial.println("Trying connect eth");
  Ethernet.init(CS);

  if (dhcp)
  {
    if (Ethernet.begin(mac) == 0) 
      Serial.println("DHCP error! Check the connection.");
    else 
      Serial.println("Ethernet connected successfully!");
  }
  else
  {
    if (ip != nullptr)
      Ethernet.begin(mac, ip);
    else
    {
      Serial.println("Невозможно подключиться к eth. Пустой ip");
      return;
    }
  }

  Serial.println(Ethernet.localIP());
}

// метод проверки подключения по eth
bool Sender::IsEthConnected()
{
  return Ethernet.hardwareStatus() != EthernetNoHardware && Ethernet.linkStatus() == LinkON;
}

