FString FMachineID::Generate()
{
    UE_LOG(LogPrometheus, Log, TEXT("Generating Machine ID from hardware..."));

    FString CPUID = GetCPUID();
    FString MAC = GetMACAddress();
    FString Disk = GetDiskSerial();
    FString Motherboard = GetMotherboardID();

    FString Combined = CPUID + MAC + Disk + Motherboard;

    FString FinalID = HashComponents(Combined);

    UE_LOG(LogPrometheus, Log, TEXT("Machine ID Generated: %s"), *FinalID);

    return FinalID;
}

FString FMachineID::GetCPUID()
{
#if PLATFORM_WINDOWS
    int CPUInfo = { 0 };
    __cpuid(CPUInfo, 1);

    return FString::Printf(TEXT("%08X%08X"),
        CPUInfo, CPUInfo);
#elif PLATFORM_MAC || PLATFORM_LINUX
    return TEXT("CPU_ID_PLACEHOLDER");
#else
    return TEXT("UNKNOWN_CPU");
#endif
}

FString FMachineID::GetMACAddress()
{
#if PLATFORM_WINDOWS
    // Use GetAdaptersInfo API to get MAC address
    // Return first non-virtual adapter
    return TEXT("MAC_ADDRESS_PLACEHOLDER");
#elif PLATFORM_MAC
    // Use IOKit to get MAC address
    return TEXT("MAC_ADDRESS_PLACEHOLDER");
#elif PLATFORM_LINUX
    // Read from /sys/class/net/eth0/address
    return TEXT("MAC_ADDRESS_PLACEHOLDER");
#else
    return TEXT("UNKNOWN_MAC");
#endif
}

FString FMachineID::GetDiskSerial()
{
#if PLATFORM_WINDOWS
    // Use WMI or DeviceIoControl to get disk serial
    return TEXT("DISK_SERIAL_PLACEHOLDER");
#elif PLATFORM_MAC
    // Use diskutil or IOKit
    return TEXT("DISK_SERIAL_PLACEHOLDER");
#elif PLATFORM_LINUX
    // Read from /dev/disk/by-id/
    return TEXT("DISK_SERIAL_PLACEHOLDER");
#else
    return TEXT("UNKNOWN_DISK");
#endif
}

FString FMachineID::GetMotherboardID()
{
#if PLATFORM_WINDOWS
    // Use WMI Win32_BaseBoard class
    return TEXT("MOTHERBOARD_ID_PLACEHOLDER");
#elif PLATFORM_MAC
    // Use system_profiler
    return TEXT("MOTHERBOARD_ID_PLACEHOLDER");
#elif PLATFORM_LINUX
    // Read from /sys/class/dmi/id/board_serial
    return TEXT("MOTHERBOARD_ID_PLACEHOLDER");
#else
    return TEXT("UNKNOWN_MOBO");
#endif
}

FString FMachineID::HashComponents(const FString& Components)
{
    return FPrometheusEncryption::SHA256(Components);
}

bool FMachineID::Verify(const FString& ExpectedID)
{
    FString CurrentID = Generate();
    return CurrentID.Equals(ExpectedID);
}

