//dlina str
int myStrlen(const char* str) {
    int length = 0;
    while (str[length] != '\0') {
        length++;
    }
    return length;
}

//copy str
void myStrcpy(char* dest, const char* src) {
    int i = 0;
    while (src[i] != '\0') {
        dest[i] = src[i];
        i++;
    }
    dest[i] = '\0';
}

//porivnana
int myStrcmp(const char* str1, const char* str2) {
    int i = 0;
    while (str1[i] != '\0' && str2[i] != '\0') {
        if (str1[i] != str2[i]) {
            return str1[i] - str2[i];
        }
        i++;
    }
    return str1[i] - str2[i];
}

//+stolbik
void addColumn(int**& matrix, int rows, int& cols, int position) {
    //novaa matrica
    int** newMatrix = new int* [rows];
    for (int i = 0; i < rows; i++) {
        newMatrix[i] = new int[cols + 1];
    }

    //informacia dla matrica
    for (int i = 0; i < rows; i++) {
        for (int j = 0, k = 0; j < cols + 1; j++) {
            if (j == position) {
                newMatrix[i][j] = 0; //novi stolvik
            }
            else {
                newMatrix[i][j] = matrix[i][k];
                k++;
            }
        }
    }

    //dezentegracia matrici
    for (int i = 0; i < rows; i++) {
        delete[] matrix[i];
    }
    delete[] matrix;

    //nova matrica
    matrix = newMatrix;
    cols++;
}

// dezantegracia stolbika
void removeColumn(int**& matrix, int rows, int& cols, int position) {
    if (cols <= 1) {
        cout << "you cant delet column" << endl;
        return;
    }

    //novoa matrica
    int** newMatrix = new int* [rows];
    for (int i = 0; i < rows; i++) {
        newMatrix[i] = new int[cols - 1];
    }

    //informacia dla matrici
    for (int i = 0; i < rows; i++) {
        for (int j = 0, k = 0; j < cols; j++) {
            if (j != position) {
                newMatrix[i][k] = matrix[i][j];
                k++;
            }
        }
    }

    //dezentegracia matrici
    for (int i = 0; i < rows; i++) {
        delete[] matrix[i];
    }
    delete[] matrix;

    //nova matrica
    matrix = newMatrix;
    cols--;
}


// cikl peremeshenia
void shiftRows(int** matrix, int rows, int cols, int shifts, char direction) {
    shifts = shifts % rows;

    if (direction == 'u' || direction == 'U') {
        // podnemaem verh
        for (int s = 0; s < shifts; s++) {
            int* temp = matrix[0];
            for (int i = 0; i < rows - 1; i++) {
                matrix[i] = matrix[i + 1];
            }
            matrix[rows - 1] = temp;
        }
    }
    else {
        //opyskaem
        for (int s = 0; s < shifts; s++) {
            int* temp = matrix[rows - 1];
            for (int i = rows - 1; i > 0; i--) {
                matrix[i] = matrix[i - 1];
            }
            matrix[0] = temp;
        }
    }
}

// peremeshenie stolbicav
void shiftColumns(int** matrix, int rows, int cols, int shifts, char direction) {
    shifts = shifts % cols;

    if (direction == 'l' || direction == 'L') {
        //pravo
        for (int s = 0; s < shifts; s++) {
            for (int i = 0; i < rows; i++) {
                int temp = matrix[i][0];
                for (int j = 0; j < cols - 1; j++) {
                    matrix[i][j] = matrix[i][j + 1];
                }
                matrix[i][cols - 1] = temp;
            }
        }
    }
    else {
        //levo
        for (int s = 0; s < shifts; s++) {
            for (int i = 0; i < rows; i++) {
                int temp = matrix[i][cols - 1];
                for (int j = cols - 1; j > 0; j--) {
                    matrix[i][j] = matrix[i][j - 1];
                }
                matrix[i][0] = temp;
            }
        }
    }
}


//Транспонування
void transposeMatrix(int**& matrix, int& rows, int& cols) {
    //novoa Транспонування
    int** transposed = new int* [cols];
    for (int i = 0; i < cols; i++) {
        transposed[i] = new int[rows];
    }

    //informacia Транспонування
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            transposed[j][i] = matrix[i][j];
        }
    }

    //delet matrica
    for (int i = 0; i < rows; i++) {
        delete[] matrix[i];
    }
    delete[] matrix;

    //prisvaevaem matricy
    matrix = transposed;
    int temp = rows;
    rows = cols;
    cols = temp;
}



