#include <iostream>
#include <fstream>
#include <utility>

#include <boost/numeric/odeint.hpp>

#include <boost/phoenix/core.hpp>
#include <boost/phoenix/operator.hpp>

using namespace std;
using namespace boost::numeric::odeint;
namespace phoenix = boost::phoenix;

const double mu = 1000.0;


typedef boost::numeric::ublas::vector< double > vector_type;
typedef boost::numeric::ublas::matrix< double > matrix_type;

struct vdp_stiff
{
    void operator()( const vector_type &x , vector_type &dxdt , double t )
    {
        dxdt[0] = x[1];
        dxdt[1] = -x[0] - mu * x[1] * (x[0]*x[0]-1.0);
    }
};

struct vdp_stiff_jacobi
{
    void operator()( const vector_type &x , matrix_type &J , const double &t , vector_type &dfdt )
    {
        J(0, 0) = 0.0;
        J(0, 1) = 1.0;
        J(1, 0) = -1.0 - 2.0*mu * x[0] * x[1];
        J(1, 1) = -mu * ( x[0] * x[0] - 1.0);

        dfdt[0] = 0.0;
        dfdt[1] = 0.0;
    }
};


int main( int argc , char **argv )
{
    //[ integrate_stiff_system
    vector_type x( 2 );
    /* initialize random seed: */
    srand ( time(NULL) );

    // initial conditions
    for (int i=0; i<2; i++)
        x[i] = 1.0; //(1.0 * rand()) / RAND_MAX;

    size_t num_of_steps = integrate_const( make_dense_output< rosenbrock4< double > >( 1.0e-6 , 1.0e-6 ) ,
            make_pair( vdp_stiff() , vdp_stiff_jacobi() ) ,
            x , 0.0 , 1000.0 , 1.0
            , cout << phoenix::arg_names::arg2 << " " << phoenix::arg_names::arg1[0] << " " << phoenix::arg_names::arg1[1] << "\n"
            );
    //]
    clog << num_of_steps << endl;



    //[ integrate_stiff_system_alternative

    vector_type x2( 2 );
    // initial conditions
    for (int i=0; i<2; i++)
        x2[i] = 1.0; //(1.0 * rand()) / RAND_MAX;

    size_t num_of_steps2 = integrate_const( make_dense_output< runge_kutta_dopri5< vector_type > >( 1.0e-6 , 1.0e-6 ) ,
            vdp_stiff() , x2 , 0.0 , 1000.0 , 1.0
            , cout << phoenix::arg_names::arg2 << " " << phoenix::arg_names::arg1[0] << " " << phoenix::arg_names::arg1[1] << "\n"
            );
    //]
    clog << num_of_steps2 << endl;


    return 0;
}

#include<iostream>
#include<vector>
#include<string>
using namespace std;
int main(){
    vector<vector<char>> key={{'L','G','D','B','A'},{'Q','M','H','E','C'},{'U','R','N','I','F'},{'X','V','S','O','K'},{'Z','Y','W','T','P'}};
    string message="jinx";
    string str="";
    for(int i=0;i<message.length();i++){
        if(message[i]==' ') continue;
        str+=toupper(message[i]);
        if(str[i]=='J') str[i]='I';
    }
    for(int i=0;i<str.size();i+=2){
        if(i==str.size()-1) break;
        if(str[i]==str[i+1]) str=str.substr(0,i+1)+'X'+str.substr(i+1);
    }
    if(str.length()%2!=0){
        if(str[str.length()-1]=='X') str+='Z';
        else str+='X';
    }
    string cipher="";
    int row1,col1,row2,col2;
    for(int i=0;i<str.length();i+=2){
        for(int r=0;r<5;r++){
            for(int c=0;c<5;c++){
                if(str[i]==key[r][c]){
                    row1=r;
                    col1=c;
                }
                if(str[i+1]==key[r][c]){
                    row2=r;
                    col2=c;
                }
            }
        }
        if(row1==row2){
            cipher+=key[row1][(col1+1)%5];
            cipher+=key[row2][(col2+1)%5];
        }
        else if(col1==col2){
            cipher+=key[(row1+1)%5][col1];
            cipher+=key[(row2+1)%5][col2];
        }
        else{
            cipher+=key[row1][col2];
            cipher+=key[row2][col1];
        }        
    }
    cout<<cipher<<endl;
    return 0;
}

