        std::getline(ss, token, ',');
        n.cc74 = std::stoi(token); if (n.cc74 > 0) n.cc74 -= 1; else n.cc74 = -1;
        std::getline(ss, token, ',');
        n.cc75 = std::stoi(token); if (n.cc75 > 0) n.cc75 -= 1; else n.cc75 = -1;
        std::getline(ss, token, ',');
        n.cc76 = std::stoi(token); if (n.cc76 > 0) n.cc76 -= 1; else n.cc76 = -1;

