class CourseFavorites {
public:
    std::vector<std::string> courses;
    std::string filename;
// public:
    CourseFavorites(const std::string& file) : filename(file) {
        load();
    }
    void add(const std::string& course) {
        if (std::find(courses.begin(), courses.end(), course) == courses.end()) {
            courses.push_back(course);
            save();
        }
    }
    void remove(const std::string& course) {
        auto it = std::remove(courses.begin(), courses.end(), course);
        if (it != courses.end()) {
            courses.erase(it, courses.end());
            save();
        }
    }
    bool contains(const std::string& course) {
        return std::find(courses.begin(), courses.end(), course) != courses.end();
    }
    void list() {
        std::cout << "收藏夹课程列表：" << std::endl;
        for (const auto& c : courses) {
            std::cout << "- " << c << std::endl;
        }
    }
    void save() {
        std::ofstream ofs(filename);
        for (const auto& c : courses) ofs << c << std::endl;
    }
    void load() {
        courses.clear();
        std::ifstream ifs(filename);
        std::string line;
        while (std::getline(ifs, line)) {
            if (!line.empty()) courses.push_back(line);
        }
    }
};

// DeepSeek大模型API调用
size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

std::string call_deepseek_api(const std::string& apikey, const std::string& prompt) {
    CURL* curl;
    CURLcode res;
    std::string readBuffer;
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist* headers = NULL;
        headers = curl_slist_append(headers, ("Authorization: Bearer " + apikey).c_str());
        headers = curl_slist_append(headers, "Content-Type: application/json");
        // 构造符合 deepseek chat API 的请求体，确保JSON格式无误
        std::ostringstream oss;
        oss << "{"
            "\"model\":\"deepseek-chat\",";
        oss << "\"messages\":[{";
        oss << "\"role\":\"user\",";
        oss << "\"content\":\"";
        // 对prompt中的特殊字符进行转义
        for (char ch : prompt) {
            if (ch == '\\') oss << "\\\\";
            else if (ch == '"') oss << "\\\"";
            else if (ch == '\n') oss << "\\n";
            else oss << ch;
        }
        oss << "\"}]}";
        std::string data = oss.str();
        std::cout << "[DeepSeek请求体] " << data << std::endl;
        curl_easy_setopt(curl, CURLOPT_URL, "https://api.deepseek.com/v1/chat/completions");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
        res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);
    }
    return readBuffer;
}



