#include "../include/BlockScope/TransactionDetailsFetcher.h"
#include <iostream>
#include <thread>
#include <chrono>

TransactionDetailsFetcher::TransactionDetailsFetcher(RpcClient& rpc)
    : m_rpc(rpc) {}

TransactionDetails TransactionDetailsFetcher::getTransactionDetails(const std::string& signature) {
    TransactionDetails details;
    details.signature = signature;

    auto response = m_rpc.call("getTransaction", nlohmann::json::array({
        signature,
        nlohmann::json{
            {"encoding", "jsonParsed"},
            {"commitment", "finalized"},
            {"maxSupportedTransactionVersion", 0}
        }
    }));

    if (!response.contains("result")) {
        std::cerr << "⚠️ Tx not found: " << signature << "\n";
        return details;
    }

    const auto& tx = response["result"];
    if (!tx.contains("transaction")) return details;
    const auto& message = tx["transaction"]["message"];
    if (!message.contains("instructions")) return details;

    for (const auto& instr : message["instructions"]) {
        InstructionInfo info;
        info.program = instr.value("program", "");
        if (info.program.empty() && instr.contains("programId")) {
            info.program = instr["programId"].get<std::string>();
        }

        // 🔹 Отсекаем ComputeBudget и прочие системные вызовы
        if (info.program.find("ComputeBudget111") != std::string::npos) continue;

        // 🔹 Распознаём известные программы
        if (info.program.find("11111111111111111111111111111111") != std::string::npos)
            info.program = "system";
        else if (info.program.find("Tokenkeg") != std::string::npos)
            info.program = "spl-token";
        else if (info.program.find("Raydium") != std::string::npos)
            info.program = "raydium";
        else if (info.program.find("JUP") != std::string::npos)
            info.program = "jupiter";

        // 🔍 Проверяем parsed-структуру
        if (instr.contains("parsed") && instr["parsed"].is_object()) {
            info.type = instr["parsed"].value("type", "(parsed)");

            if (instr["parsed"].contains("info") && instr["parsed"]["info"].is_object()) {
                const auto& parsedInfo = instr["parsed"]["info"];

                info.source = parsedInfo.value("source", "");
                info.destination = parsedInfo.value("destination", "");
                info.token = parsedInfo.value("mint", "");

                if (parsedInfo.contains("amount") && parsedInfo["amount"].is_string()) {
                    try {
                        std::string amountStr = parsedInfo["amount"].get<std::string>();
                        double raw = std::stod(amountStr);

                        if (info.program == "system" && info.type == "transfer") {
                            info.amount = raw / 1e9;
                            info.token = "SOL";
                        } else {
                            info.amount = raw / 1e6;
                            if (info.token.empty()) info.token = "SPL";
                        }
                    } catch (...) {
                        // bad formate
                    }
                }
            }
        } else {
            info.type = "(unparsed)";
        }

        details.instructions.push_back(info);
    }

    // Delay for api
    std::this_thread::sleep_for(std::chrono::milliseconds(50));

    return details;
}

