#include "SessionAlsaPcm.h"
#include "ResourceManager.h"
#include <unistd.h>

StreamContextProxy::StreamContextProxy(const struct pal_stream_attributes *sattr __unused,
                    struct pal_device *dattr __unused, const uint32_t no_of_devices __unused,
                    const struct modifier_kv *modifiers __unused, const uint32_t no_of_modifiers __unused,
                    const std::shared_ptr<ResourceManager> rm) :
               StreamCommon(sattr,dattr,no_of_devices,modifiers,no_of_modifiers,rm)
{
    //registering for a callback
    session->registerCallBack((session_callback)HandleCallBack, (uint64_t) this);
    rm->registerStream(this);
}

StreamContextProxy::~StreamContextProxy() {
    rm->deregisterStream(this);
}

int32_t  StreamContextProxy::setParameters(uint32_t param_id, void *payload)
{
    int32_t status = 0;

    if (!payload)
    {
        status = -EINVAL;
        PAL_ERR(LOG_TAG, "wrong params");
        goto error;
    }

    PAL_DBG(LOG_TAG, "start, set parameter %u, session handle - %p", param_id, session);

    mStreamMutex.lock();
    // Stream may not know about tags, so use setParameters instead of setConfig
    if (currentState == STREAM_IDLE) {
        PAL_ERR(LOG_TAG, "Invalid stream state: IDLE for param ID: %d", param_id);
        mStreamMutex.unlock();
        return -EINVAL;
    }
    switch (param_id) {
        case PAL_PARAM_ID_MODULE_CONFIG:
        {
            status = session->setParameters(this, 0, param_id, payload);
            if (status)
                PAL_ERR(LOG_TAG, "Error:setParam for volume boost failed with %d",
                    status);
            break;
        }
        default:
            PAL_ERR(LOG_TAG, "Error:Unsupported param id %u", param_id);
            status = -EINVAL;
            break;
    }

    mStreamMutex.unlock();
    PAL_DBG(LOG_TAG, "exit, session parameter %u set with status %d", param_id, status);
error:
    return status;
}

void StreamContextProxy::ParseASPSEventPayload(uint32_t event_id,
                                   uint32_t event_size, void *data) {
    if (callback_) {
        PAL_INFO(LOG_TAG, "Notify detection event to client");
        callback_((pal_stream_handle_t *)this, event_id, (uint32_t *)data,
                   event_size, cookie_);
    }
}

void StreamContextProxy::HandleCallBack(uint64_t hdl, uint32_t event_id,
                                      void *data, uint32_t event_size) {
    StreamContextProxy *ContextProxy = nullptr;
    PAL_DBG(LOG_TAG, "Enter, event detected on SPF, event id = 0x%x", event_id);
    ContextProxy = (StreamContextProxy *)hdl;
    ContextProxy->ParseASPSEventPayload(event_id, event_size, data);
    PAL_DBG(LOG_TAG, "Exit");
}

#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

const int STUDENT_COUNT = 20;

struct studentType
{
    string studentFName;
    string studentLName;
    int testScore;
    char grade;
};

void getData(studentType students[], int size);
void assignGrade(studentType students[], int size);
int highestScore(studentType students[], int size);
void printHighest(studentType students[], int size, int highScore);
void printAll(studentType students[], int size);

int main()
{
    studentType students[STUDENT_COUNT];

    getData(students, STUDENT_COUNT);
    assignGrade(students, STUDENT_COUNT);

    int highest = highestScore(students, STUDENT_COUNT);

    printAll(students, STUDENT_COUNT);
    cout << "\n\nStudents with highest test score:\n";
    printHighest(students, STUDENT_COUNT, highest);

    return 0;
}

void getData(studentType students[], int size)
{
    for (int i = 0; i < size; i++)
    {
        cout << "Enter first name, last name, and score for student " << i + 1 << ": ";
        cin >> students[i].studentFName >> students[i].studentLName >> students[i].testScore;
    }
}

void assignGrade(studentType students[], int size)
{
    for (int i = 0; i < size; i++)
    {
        int score = students[i].testScore;
        if (score >= 90)
            students[i].grade = 'A';
        else if (score >= 80)
            students[i].grade = 'B';
        else if (score >= 70)
            students[i].grade = 'C';
        else if (score >= 60)
            students[i].grade = 'D';
        else
            students[i].grade = 'F';
    }
}

int highestScore(studentType students[], int size)
{
    int maxScore = students[0].testScore;
    for (int i = 1; i < size; i++)
    {
        if (students[i].testScore > maxScore)
            maxScore = students[i].testScore;
    }
    return maxScore;
}

void printAll(studentType students[], int size)
{
    cout << left << setw(20) << "Name" << setw(10) << "Score" << "Grade\n";
    cout << "-------------------------------------\n";

    for (int i = 0; i < size; i++)
    {
        string fullName = students[i].studentLName + ", " + students[i].studentFName;
        cout << left << setw(20) << fullName
             << setw(10) << students[i].testScore
             << students[i].grade << endl;
    }
}

void printHighest(studentType students[], int size, int highScore)
{
    for (int i = 0; i < size; i++)
    {
        if (students[i].testScore == highScore)
        {
            cout << students[i].studentLName << ", " << students[i].studentFName
                 << " --> " << highScore << endl;
        }
    }
}

#include <cstdio>
#include <random>
#include "Fusion.h"

struct State { double z=0, v=0; };
double accel_profile(double t){
  if (t < 2.2) return 25.0 - 2.0*t;  
  if (t < 12.0) return -9.81 + 0.3;   
  return 0.0;                         
}
int main(){
  const double P0=101325.0, dt=0.005, simT=18.0; 
  std::mt19937 rng(42);
  std::normal_distribution<float> n_acc(0.0f,0.15f), n_baro(0.0f,1.0f);
  State s; double t=0; FusionKF kf; kf.R=1.0f;
  FILE* f=std::fopen("flight.csv","w");
  std::fprintf(f,"t_s,alt_baro_m,alt_fused_m,vel_fused_mps,accZ_mps2,press_Pa,temp_C\n");
  while(t<=simT){
    double a=accel_profile(t); s.v+=a*dt; s.z+=s.v*dt; if(s.z<0 && t>0.2){s.z=0; s.v=0;}
    float P = pressure_from_alt((float)s.z,(float)P0);
    float zbar = hypsometric_alt(P,(float)P0) + n_baro(rng);
    float az   = (float)a + n_acc(rng);
    kfPredict(kf,(float)dt,az);
    kfUpdate(kf,zbar);
    std::fprintf(f,"%.3f,%.4f,%.4f,%.4f,%.4f,%.2f,%.2f\n",t,zbar,kf.z,kf.v,az,P,20.0);
    t+=dt;
  }
  std::fclose(f);
  std::puts("Wrote flight.csv  (PC simulation)");
}

