bool Network::initSocket() {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        std::cerr << "Socket creation failed." << std::endl;
        return false;
    }
    mainSocket = sock;
    return true;
}

bool Network::resolveDomain(const char* domain, const char* port) {
    struct addrinfo hints{};
    memset(&hints, 0, sizeof(hints));

    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    int status = getaddrinfo(domain, port, &hints, &res);
    if (status != 0) {
        std::cerr << "getaddrinfo() failed: " << gai_strerror(status) << std::endl;
        return false;
    }

    std::cout << "Domain resolved successfully.\n";
    return true;
}

bool Network::connectToHost() {
    if (!res) {
        std::cerr << "No resolved address — call resolveDomain() first.\n";
        return false;
    }

    for (auto p = res; p != nullptr; p = p->ai_next) {
        mainSocket = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (mainSocket == -1)
            continue;

        if (connect(mainSocket, p->ai_addr, p->ai_addrlen) == 0) {
            std::cout << "Connected successfully!\n";

            struct timeval timeout{};
            timeout.tv_sec = 3;
            timeout.tv_usec = 0;
            setsockopt(mainSocket, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));


            return true;
        }

        close(mainSocket);
        mainSocket = -1;
    }

    std::cerr << "Could not connect to any address.\n";
    return false;
}

bool Network::sendHttpRequest(const std::string& request) {
    if (mainSocket == -1) {
        std::cerr << "No active socket.\n";
        return false;
    }

    ssize_t bytes_sent = send(mainSocket, request.c_str(), request.size(), 0);
    if (bytes_sent == -1) {
        perror("send");
        return false;
    }

    std::cout << "Sent " << bytes_sent << " bytes.\n";
    return true;
}

std::string Network::recvResponse() {
    if (mainSocket == -1) {
        std::cerr << "No active socket.\n";
        return "";
    }

    std::string response;
    char buffer[4096];
    ssize_t bytesRecv;

    while (true) {
        bytesRecv = recv(mainSocket, buffer, sizeof(buffer) - 1, 0);
        if (bytesRecv <= 0)
            break;  // timeout or closed by server

        buffer[bytesRecv] = '\0';
        response.append(buffer, bytesRecv);

        // Optional: stop if we've received full headers + HTML
        if (response.find("</html>") != std::string::npos)
            break;
    }

    if (bytesRecv == 0)
        std::cout << "Connection closed by server.\n";
    else if (bytesRecv < 0)
        perror("recv");

    std::cout << "Received " << response.size() << " bytes total.\n";
    return response;
}
void Network::closeConnection() {
    if (mainSocket != -1) {
        close(mainSocket);
        mainSocket = -1;
        std::cout << "Connection closed.\n";
    }
