    {
        mainSocket = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (mainSocket == -1)
            continue;

        if (connect(mainSocket, p->ai_addr, p->ai_addrlen) == 0)
        {
            std::cout << "TCP connection established for TLS.\n";
            break;
        }

        close(mainSocket);
        mainSocket = -1;
    }

