#include <iostream>
using namespace std;

struct Task {
    int ID; //任务编号
    int key; //任务优先级
    int load; //任务持续时间
    Task *next;
};

/* 请在这里填写答案 */
Task *getBatch(int m) {
    Task *head = nullptr;
    Task *tail = nullptr;
    int key;
    cin >> key;
    for (int i = 0; i < m; ++i) {
        int id, duration;
        cin >> id >> duration;
        Task *newTask = new Task{id, key, duration, nullptr};
        if (!head) {
            //如果为空，则新创建的头尾指向自己
            head = newTask;
            tail = newTask;
        } else {
            //不为空，尾部指向新创建的
            tail->next = newTask;
            tail = newTask;
        }
    }
    return head;
}

// 将小链表插入大链表
Task *addBatch(Task *head, Task *h) {
    if (!head) return h; // 如果head为空，直接返回h

    if (head->key < h->key) {
        //找到应该插入的位置
        Task *current = head;
        while (current->next) {
            if ((current->key <= h->key) && (current->next != NULL) && (current->next->key > h->key)) {
                Task *add = h;
                Task *next;
                next = current->next;
                current->next = h;
                while (add->next) {
                    add = add->next;
                }
                add->next = next;
                return head;
            }
            current = current->next;
        }
        current->next = h;
        return head; // 返回原来的头
    } else if (head->key > h->key) {
        // 将h插入到head之前
        Task *current = h;
        while (current->next) {
            current = current->next;
        }
        current->next = head;
        return h; // 返回新的头
    }
}

// 输出第m项任务的信息，或者输出OK
void display(Task *head, int m) {
    Task *current = head;
    for (int i = 1; i < m; ++i) {
        if (current != NULL) {
            current = current->next;
        } else {
            break;
        }
    }
    if (current != NULL) {
        cout << current->ID << " " << current->key << " " << current->load << endl;
    } else {
        cout << "OK" << endl;
    }
}

// 学习任务 第一个数字是单项任务的最短持续时间mi，第二个数字是单项任务的最长持续时间ma,最后一个数字是本次工作的最长持续时间load.
Task *study(Task *head, int mi, int ma, int load) {
    Task *current = head;
    int timeSpent = 0;
    Task *prev = nullptr;

    while (current) {
        if (current->load >= mi && current->load <= ma) {
            timeSpent += current->load;
            // cout<<timeSpent<<endl;
            if (timeSpent > load) {
                break;
            }
            // 可以选择删除已完成的任务
            if (prev) {
                prev->next = current->next;
                // cout<<current->ID<<endl;

                delete current;
                current = prev->next; // 更新当前指针
            } else {
                Task *toDelete = current;
                head = current->next; // 更新头指针
                current = head;
                // cout<<toDelete->ID<<endl;
                delete toDelete;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }
    return head;
}


void del(Task *head) {
    //删除链表
    if (head == NULL) return;
    del(head->next);
    delete head;
}

const int K = 3; //幸运数字
int main() {
    int count, mi, ma, load;
    Task *head = NULL, *h;
    cin >> count; //输入行的第一个数字
    while (count != 0) {
        if (count > 0) {
            //新添加count个任务
            h = getBatch(count); //构建链表，并将首指针返回给h
            display(h, K); //显示小链表的第K个任务或输出OK
            head = addBatch(head, h); //将小链表加入大链表，并将首指针返回
        } else {
            cin >> mi >> ma >> load;
            head = study(head, mi, ma, load);
            display(head, K); //显示大链表的第K个任务或输出OK
        }
        cin >> count;
    }
    del(head);
    return 0;
}

