char normalizeRussianChar(char c) {
    if (c >= 'а' && c <= 'я') return c - 'а' + 'А';
    else if (c == 'ё') return 'Е';
    else if (c == 'Ё') return 'Е';
    else if (c == 'й') return 'И';
    else if (c == 'Й') return 'И';
    return c;
}

char normalizeEnglishChar(char c) {
    if (c >= 'a' && c <= 'z') return c - 'a' + 'A';
    return c;
}

bool isRussianLetter(char c) {
    return (c >= 'А' && c <= 'Я') || (c >= 'а' && c <= 'я') || c == 'ё' || c == 'Ё';
}

bool isEnglishLetter(char c) {
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
}

void createVigenereTable(char** table, const string& alphabet) {
