using namespace std;

using State = pair<long long, pair<int, int>>;  // {cost, {u, 最好的引擎index}}

int main(){
    int n, m;
    int tmp = 100;
    cin >> n >> m;

    vector<vector<pair<int, int>>> adj(n+1);  // {v, weight}
    for(int i = 0 ; i < m ; i++){
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    vector<int> s(n+1);
    for(int i = 1 ; i <= n ; i++){
        cin >> s[i];
    }

    vector<vector<long long>> costs(n+1, vector<long long>(n+1, LLONG_MAX));  // 到u星球且引擎為s[1]的最小成本
    priority_queue<State, vector<State>, greater<State>> pq;

    costs[1][1] = 0;
    pq.push({0, {1, 1}});

    while(!pq.empty()){
        long long cost = pq.top().first;
        int u = pq.top().second.first;
        int i = pq.top().second.second;
        pq.pop();

        if(cost > costs[u][i]){
            continue;
        }

        for(auto& edge : adj[u]){
            int v = edge.first;
            int w = edge.second;

            long long travel_cost = (long long)w * s[i];
            long long new_cost = cost + travel_cost;

            int new_engine_index = i;
            if(s[v] < s[i]){
                new_engine_index = v;
            }

            if(new_cost < costs[v][new_engine_index]){
                costs[v][new_engine_index] = new_cost;
                pq.push({new_cost, {v, new_engine_index}});
            }
        }
    }

    long long min_time = LLONG_MAX;
    for(int i = 1 ; i <= n ; i++){
        min_time = min(min_time, costs[n][i]);
    }

    cout << min_time << endl;
}

