void AddNewElToEnd(int &s, int** a, int el)
{
	int* temp = new int[s+1];
	for (size_t i = 0; i < s; i++)
	{
		temp[i] = (*a)[i];
	}
	temp[s] = el;
	delete[] *a;
	*a = temp;
	s++;
}

void AddNewElToStart(int& s, int** a, int el)
{
	int* temp = new int[s+1];
	for (size_t i = 0; i < s; i++)
	{
		temp[i+1] = (*a)[i];
	}
	delete[] * a;
	temp[0] = el;
	*a = temp;
	s++;
}

void AddNewElByIndex(int& s, int** a, int id, int el)
{
	int* temp = new int[s + 1];
	if (id == 0)
	{
		for (size_t i = 0; i < s; i++)
		{
			temp[i + 1] = (*a)[i];
		}
		temp[0] = el;
	}
	else if (id == s-1)
	{
		for (size_t i = 0; i < s; i++)
		{
			temp[i] = (*a)[i];
		}
		temp[s] = el;
	}
	else
	{
		for (size_t i = 0; i < id; i++)
		{
			temp[i] = (*a)[i];
		}
		temp[id] = el;
		for (size_t i = id; i < s; i++)
		{
			temp[i+1] = (*a)[i];
		}
	}
	delete[] * a;
	*a = temp;
	s++;
}

void AddArrayInArray(int& s1, int** a, int& s2, int** b)
{
	int* newArr = new int[s1 + s2];
	for (size_t i = 0; i < s1; i++)
	{
		newArr[i] = (*a)[i];
	}
	for (size_t i = 0; i < s2; i++)
	{
		newArr[i+s1] = (*b)[i];
	}
	delete[] *a;
	*a = newArr;
	s1 += s2;
}

void DeleteLastEl(int& s, int** a)
{
	int* temp = new int[s - 1];
	for (size_t i = 0; i < s-1; i++)
	{
		temp[i] = (*a)[i];
	}
	delete[] * a;
	*a = temp;
	s--;
}

void DeleteFirstEl(int& s, int** a)
{
	int* temp = new int[s - 1];
	for (size_t i = 0; i < s - 1; i++)
	{
		temp[i] = (*a)[i+1];
	}
	delete[] * a;
	*a = temp;
	s--;
}

void DeletePartOfArr(int& s, int** a)
{
	int start, end;
	cout << "Enter start index of deleting part -> ";
	cin >> start;
	cout << "Enter end index of deleting part -> ";
	cin >> end;

	if (start < 0 || end >= s || start > end)
	{
		throw "Error! Invalid range to delete!";
	}
	int newSize = s - (end - start + 1);
	int* temp = new int[newSize];

	for (size_t i = 0; i < start; i++)
	{
		temp[i] = (*a)[i];
	}
	for (size_t i = end+1; i < s; i++)
	{
		temp[start] = (*a)[i];
	}
	delete[] * a;
	*a = temp;
	s = newSize;
}

