TString::TString(char* s) //构造函数
{
	if (s) 
	{
		len = int(strlen(s));
		content = new char[len + 1];
		strcpy(content, s);
	}
	else 
	{
		len = 0;
		content = NULL;
	}
}
TString::TString(const TString& other) //拷贝构造函数
{
	if (other.content) 
	{
		len = other.len;
		content = new char[len + 1];
		strcpy(content, other.content);
	}
	else
	{
		len = 0;
		content = NULL;
	}
}
