using namespace std;

const int NUM_STUDENTS = 20;

struct studentType {
    string studentFName;
    string studentLName;
    int testScore;
    char grade;
};

void readStudentData(studentType students[], int& count) {
    cout << "Enter number of students (max " << NUM_STUDENTS << "): ";
    cin >> count;
    cin.ignore();

    for (int i = 0; i < count; i++) {
        cout << "\nStudent " << (i + 1) << ":\n";
        cout << "First name: ";
        getline(cin, students[i].studentFName);
        cout << "Last name: ";
        getline(cin, students[i].studentLName);
        cout << "Test score (0-100): ";
        cin >> students[i].testScore;
        cin.ignore();
    }
}

void assignGrades(studentType students[], int count) {
    for (int i = 0; i < count; i++) {
        if (students[i].testScore >= 90)
            students[i].grade = 'A';
        else if (students[i].testScore >= 80)
            students[i].grade = 'B';
        else if (students[i].testScore >= 70)
            students[i].grade = 'C';
        else if (students[i].testScore >= 60)
            students[i].grade = 'D';
        else
            students[i].grade = 'F';
    }
}

int findHighestScore(const studentType students[], int count) {
    int highest = students[0].testScore;
    for (int i = 1; i < count; i++) {
        if (students[i].testScore > highest)
            highest = students[i].testScore;
    }
    return highest;
}

void printHighestScoreStudents(const studentType students[], int count, int highest) {
    cout << "\n=== Students with Highest Score ===\n";
    for (int i = 0; i < count; i++) {
        if (students[i].testScore == highest) {
            cout << left << setw(20) << (students[i].studentLName + ", " + students[i].studentFName)
                 << highest << endl;
        }
    }
}

void printAllStudents(const studentType students[], int count) {
    cout << "\n=== All Students ===\n";
    cout << left << setw(20) << "Name" << setw(12) << "Score" << "Grade\n";
    cout << string(35, '-') << endl;

    for (int i = 0; i < count; i++) {
        string fullName = students[i].studentLName + ", " + students[i].studentFName;
        cout << left << setw(20) << fullName 
             << setw(12) << students[i].testScore 
             << students[i].grade << endl;
    }
}

int main() {
    studentType students[NUM_STUDENTS];
    int count;

    readStudentData(students, count);
    assignGrades(students, count);
    printAllStudents(students, count);

    int highest = findHighestScore(students, count);
    printHighestScoreStudents(students, count, highest);

    return 0;
}

