        if (!ifs) { ec = std::make_error_code(std::errc::io_error); return std::nullopt; }
        combined ^= fnv1a_64(chunk.data(), chunk_size) << 2;
        combined ^= static_cast<uint64_t>(static_cast<uint64_t>(size) << 3);
        return combined;
    }
}

