//funçao para verificar quem é o vencedor
int Vencedor(Tabuleiro t)
{
	int i;
	int j;
	int livres;

	// retorna quem venceu: 1 para X, 2 para O, 3 para empate e 0 caso ninguém venceu ainda

	//linhas
	for(i = 0; i < 3; i++)
	{
		if(t.casas[i][0] == t.casas[i][1] && t.casas[i][1] == t.casas[i][2])
		{
			if (t.casas[i][0] == 'X')
			{
				return 1;
			}
			if (t.casas[i][0] == 'O') 
			{
				return 2;
			}
		}
	}

	//colunas
	for (j = 0; j < 3; j++) {
        if (t.casas[0][j] == t.casas[1][j] && t.casas[1][j] == t.casas[2][j])
		{
			if (t.casas[0][j] == 'X')
			{
				return 1;
			}
			if (t.casas[0][j] == 'O')
			{
				return 2;
			}
		}
	}

	//diagonais
    if (t.casas[0][0] == t.casas[1][1] && t.casas[1][1] == t.casas[2][2])
	{
        if (t.casas[0][0] == 'X')
		{
			return 1;
		}
        if (t.casas[0][0] == 'O')
		{
			return 2;
		}
    }

    if (t.casas[0][2] == t.casas[1][1] && t.casas[1][1] == t.casas[2][0])
	{
        if (t.casas[0][2] == 'X')
		{
			return 1;
		}
        if (t.casas[0][2] == 'O')
		{
			return 2;
		}
    }

	//empate
	livres = 0;

	for(i = 0; i < 3; i++)
	{
		for(j = 0; j < 3; j++)
		{
			if(Posicao(t, i, j) == 1)
			{
				livres++;
			}
		}
	}
	if (livres == 0)
	{
		return 3;
	}

	return 0;

}

