    std::size_t operator()(std::vector<int> const& vec) const {
        std::size_t seed = vec.size();
        for (auto v : vec) {
            std::uint32_t x = v;
            x = ((x >> 16) ^ x) * 0x45d9f3b;
            x = ((x >> 16) ^ x) * 0x45d9f3b;
