// --------- UnionFind Tree ---------
class UnionFind {
public:
    UnionFind() : d(0) {}
    UnionFind(int size) : d(size, -1) {}
    void resize(int size) { *this = { size }; }
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if (d[y] < d[x]) std::swap(x, y);
            d[x] += d[y];
            d[y] = x;
        }
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int root(int x) { return d[x] < 0 ? x : d[x] = root(d[x]); }
    int size(int x) { return -d[root(x)]; }

private:
    std::vector<int> d;
};

