LD2410B::LD2410B(HardwareSerial &serial) 
    : _serial(serial), 
      _engineeringMode(false),
      _trackingEnabled(false),
      _maxRecords(1000),
      _rxIndex(0),
      _lastStateChange(0),
      _lastOccupiedState(false) {
}

bool LD2410B::begin(int rxPin, int txPin, unsigned long baudRate) {
    _serial.begin(baudRate, SERIAL_8N1, rxPin, txPin);
    delay(100);

    // Clear any pending data
    while(_serial.available()) {
        _serial.read();
    }

    _rxIndex = 0;
    _lastStateChange = millis();

    return true;
}

bool LD2410B::update() {
    bool newData = false;

    while(_serial.available()) {
        uint8_t byte = _serial.read();

        // Look for data frame header
        if(_rxIndex == 0 && byte == 0xF4) {
            _rxBuffer[_rxIndex++] = byte;
        }
        else if(_rxIndex == 1 && byte == 0xF3) {
            _rxBuffer[_rxIndex++] = byte;
        }
        else if(_rxIndex == 2 && byte == 0xF2) {
            _rxBuffer[_rxIndex++] = byte;
        }
        else if(_rxIndex == 3 && byte == 0xF1) {
            _rxBuffer[_rxIndex++] = byte;
        }
        else if(_rxIndex >= 4) {
            _rxBuffer[_rxIndex++] = byte;

            // Check if we have complete frame
            if(_rxIndex >= 6) {
                uint16_t dataLen = _rxBuffer[4] | (_rxBuffer[5] << 8);
                size_t expectedLen = 4 + 2 + dataLen + 4; // header + len + data + footer

                if(_rxIndex >= expectedLen) {
                    // Verify footer
                    if(_rxBuffer[_rxIndex-4] == 0xF8 &&
                       _rxBuffer[_rxIndex-3] == 0xF7 &&
                       _rxBuffer[_rxIndex-2] == 0xF6 &&
                       _rxBuffer[_rxIndex-1] == 0xF5) {

                        if(parseDataFrame()) {
                            newData = true;
                        }
                    }
                    _rxIndex = 0;
                }

                // Prevent buffer overflow
                if(_rxIndex >= sizeof(_rxBuffer)) {
                    _rxIndex = 0;
                }
            }
        }
        else {
            _rxIndex = 0;
        }
    }

    return newData;
}

bool LD2410B::parseDataFrame() {
    // Data starts at index 6 (after header and length)
    uint16_t dataLen = _rxBuffer[4] | (_rxBuffer[5] << 8);

    if(dataLen < 2) return false;

    uint8_t dataType = _rxBuffer[6];
    uint8_t head = _rxBuffer[7];

    if(head != 0xAA) return false;

    // Find tail (0x55) and checksum (0x00)
    size_t tailIndex = 6 + dataLen - 2;
    if(_rxBuffer[tailIndex] != 0x55 || _rxBuffer[tailIndex+1] != 0x00) {
        return false;
    }

    // Process target data
    processTargetData(&_rxBuffer[8], dataLen - 4, dataType);

    return true;
}

void LD2410B::processTargetData(const uint8_t* data, size_t len, uint8_t dataType) {
    if(len < 12) return;

    // Parse basic target information (always present)
    uint8_t newTargetState = data[0];
    uint16_t movingDist = data[1] | (data[2] << 8);
    uint8_t movingEnergy = data[3];
    uint16_t stationaryDist = data[4] | (data[5] << 8);
    uint8_t stationaryEnergy = data[6];
    uint16_t detectionDist = data[7] | (data[8] << 8);

    _currentData.targetState = newTargetState;
    _currentData.movingDistance = movingDist;
    _currentData.movingEnergy = movingEnergy;
    _currentData.stationaryDistance = stationaryDist;
    _currentData.stationaryEnergy = stationaryEnergy;
    _currentData.detectionDistance = detectionDist;

    // Parse engineering mode data if available
    if(dataType == DATA_ENGINEERING && len >= 31) {
        size_t offset = 9;
        _currentData.maxMovingGate = data[offset++];
        _currentData.maxStationaryGate = data[offset++];

        // Motion gate energies (9 gates)
        for(int i = 0; i < 9; i++) {
            _currentData.movingGateEnergy[i] = data[offset++];
        }

        // Stationary gate energies (9 gates)
        for(int i = 0; i < 9; i++) {
            _currentData.stationaryGateEnergy[i] = data[offset++];
        }

        if(len >= 33) {
            _currentData.lightSensor = data[offset++];
            _currentData.outPinState = data[offset++];
        }
    }

    // Track occupancy changes
    bool currentlyOccupied = (newTargetState != TARGET_NONE);

    if(_trackingEnabled && currentlyOccupied != _lastOccupiedState) {
        addOccupancyRecord(currentlyOccupied, newTargetState, detectionDist);
        _lastStateChange = millis();
        _lastOccupiedState = currentlyOccupied;
    }
}

