 //K-th node on path from A to B

 int lift(int v, int k, LCA &l) {
    for (int i = 0; i < l.LOG; i++)
        if (k & (1 << i))
            v = l.up[v][i];
    return v;
}

int kth_on_path(int a, int b, int k, LCA &l) {
    int c = l.lca(a, b);
    int da = l.depth[a] - l.depth[c];
    if (k <= da) return lift(a, k, l);
    int db = l.depth[b] - l.depth[c];
    int rest = k - da;
    return lift(b, db - rest, l);
}

//Is X on the path from A to B?
//X lies on path A–B iff
//dist(A,X) + dist(X,B) == dist(A,B)

#include <stdio.h>

typedef struct {
    int id;
    int popularity;
    int lastAccess;
    int isPresent;
} Book;

int main() {
    int capacity, Q;
    scanf("%d %d", &capacity, &Q);

    Book shelf[capacity];
    for (int i = 0; i < capacity; i++) {
        shelf[i].isPresent = 0;
    }

    int time = 1;  

    while (Q--) {
        char op[10];
        scanf("%s", op);

        if (op[0] == 'A' && op[1] == 'D') {
            int x, y;
            scanf("%d %d", &x, &y);

            int found = -1;

            for (int i = 0; i < capacity; i++) {
                if (shelf[i].isPresent && shelf[i].id == x) {
                    found = i;
                    break;
                }
            }

            if (found != -1) {
                shelf[found].popularity = y;
                shelf[found].lastAccess = time++;
                continue;
            }

            int empty = -1;
            for (int i = 0; i < capacity; i++) {
                if (!shelf[i].isPresent) {
                    empty = i;
                    break;
                }
            }

            if (empty != -1) {
                shelf[empty].id = x;
                shelf[empty].popularity = y;
                shelf[empty].lastAccess = time++;
                shelf[empty].isPresent = 1;
                continue;
            }

            int LRU = 0;
            for (int i = 1; i < capacity; i++) {
                if (shelf[i].lastAccess < shelf[LRU].lastAccess) {
                    LRU = i;
                }
            }

            shelf[LRU].id = x;
            shelf[LRU].popularity = y;
            shelf[LRU].lastAccess = time++;
            shelf[LRU].isPresent = 1;
        }

        else if (op[0] == 'A' && op[1] == 'C') {
            int x;
            scanf("%d", &x);

            int found = -1;

            for (int i = 0; i < capacity; i++) {
                if (shelf[i].isPresent && shelf[i].id == x) {
                    found = i;
                    break;
                }
            }

            if (found == -1) {
                printf("-1\n");
            } else {
                printf("%d\n", shelf[found].popularity);
                shelf[found].lastAccess = time++; 
            }
        }
    }

    return 0;
}

