using namespace std;

void Create(int** a, const int n, const int Low, const int High);
void Print(int** a, const int n);
int SumPobDiag(int** a, const int n);

int main()
{
    SetConsoleCP(1251);
    SetConsoleOutputCP(1251);

    srand((unsigned)time(NULL));

    int Low = 1;     // мінімальне значення елементів
    int High = 9;    // максимальне значення елементів

    int n;
    cout << "n = ";
    cin >> n;

    int** a = new int* [n];
    for (int i = 0; i < n; i++)
        a[i] = new int[n];

    Create(a, n, Low, High);
    Print(a, n);

    int sum = SumPobDiag(a, n);
    cout << "Сума елементів побічної діагоналі = " << sum << endl;

    for (int i = 0; i < n; i++)
        delete[] a[i];
    delete[] a;

    return 0;
}

void Create(int** a, const int n, const int Low, const int High)
{
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            a[i][j] = Low + rand() % (High - Low + 1);
}

void Print(int** a, const int n)
{
    cout << endl;
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < n; j++)
            cout << setw(4) << a[i][j];
        cout << endl;
    }
    cout << endl;
}

int SumPobDiag(int** a, const int n)
{
    int sum = 0;
    for (int i = 0; i < n; i++)
    {
        int j = n - 1 - i; // індекс елемента побічної діагоналі
        sum += a[i][j];
    }
    return sum;
}

