using namespace std;

vector<vector<int>> generate_matrix(int n, bool multigraph=true, int max_multiedge=10, bool undirected=false) {
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dist_multi(0, max_multiedge);
    uniform_int_distribution<> dist_simple(0, 1);

    vector<vector<int>> M(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int val = multigraph ? dist_multi(gen) : dist_simple(gen);
            M[i][j] = val;
            if (undirected) M[j][i] = val;
        }
    }
    return M;
}

void write_graph_file(const string &filename, int n1, int n2, bool multigraph, int max_multiedge, bool undirected, int k) {
    ofstream f(filename);
    if (!f.is_open()) { 
        cerr << "Cannot write file: " << filename << endl; 
        return; 
    }

    auto g1 = generate_matrix(n1, multigraph, max_multiedge, undirected);
    f << n1 << "\n";
    for (auto &row : g1) {
        for (int i = 0; i < row.size(); i++)
            f << row[i] << (i+1 < row.size() ? ' ' : '\n');
    }

    auto g2 = generate_matrix(n2, multigraph, max_multiedge, undirected);
    f << n2 << "\n";
    for (auto &row : g2) {
        for (int i = 0; i < row.size(); i++)
            f << row[i] << (i+1 < row.size() ? ' ' : '\n');
    }
    f << k << "\n";
}

int main(int argc, char** argv) {
    if (argc < 7) {
        cerr << "Usage:\n" << argv[0] 
             << " n1 n2 k test_count solver_path mode(d/a)\n";
        return 1;
    }

    int n1 = stoi(argv[1]);
    int n2 = stoi(argv[2]);
    int k = stoi(argv[3]);
    int tests = stoi(argv[4]);
    string solverPath = argv[5];
    string mode = argv[6];   

    if (mode != "d" && mode != "a") {
        cerr << "Error: mode must be 'd' or 'a'\n";
        return 1;
    }

    filesystem::path solverFs(solverPath);
    if (!filesystem::exists(solverFs)) {
        cerr << "Error: solver not found at path: " << solverFs << endl;
        return 1;
    }

#ifdef _WIN32
    if (solverFs.extension() != ".exe") solverFs += ".exe";
#endif

    string solverAbs = filesystem::absolute(solverFs).string();

    filesystem::create_directory("inputs");
    filesystem::create_directory("outputs");

    double total_ms = 0.0;

    for (int i = 0; i < tests; i++) {
        string inFile = "inputs/test_" + to_string(i) + ".txt";
        string outFile = "outputs/out_" + to_string(i) + ".txt";

        write_graph_file(inFile, n1, n2, true, 5, false, k);

        auto start = chrono::high_resolution_clock::now();

        string cmd = solverAbs + " " + mode + " " + inFile + " " + outFile;
        cout << "Running command: " << cmd << endl;

        int ret = system(cmd.c_str());

        auto end = chrono::high_resolution_clock::now();
        double ms = chrono::duration<double, milli>(end - start).count();

        if (ret != 0)
            cerr << "Error running solver on: " << inFile << endl;

        cout << "Test " << i << " = " << ms << " ms\n";
        total_ms += ms;
    }

    cout << "\nAVERAGE TIME: " << (total_ms / tests) << " ms\n";
    return 0;
}

#include <stdio.h>

int main() {
    int arr[100];     // array declaration
    int n, i, pos, value, choice;

    // Input initial array size
    printf("Enter the number of elements in the array: ");
    scanf("%d", &n);

    // Input array elements
    printf("Enter %d elements:\n", n);
    for (i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    do {
        printf("\n--- Array Operations Menu ---\n");
        printf("1. Insert Element\n");
        printf("2. Delete Element\n");
        printf("3. Display Array\n");
        printf("4. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                // Insertion
                printf("Enter position to insert (1 to %d): ", n + 1);
                scanf("%d", &pos);
                if (pos < 1 || pos > n + 1) {
                    printf("Invalid position!\n");
                } else {
                    printf("Enter value to insert: ");
                    scanf("%d", &value);
                    for (i = n; i >= pos; i--)
                        arr[i] = arr[i - 1];
                    arr[pos - 1] = value;
                    n++;
                    printf("Element inserted successfully!\n");
                }
                break;

            case 2:
                // Deletion
                printf("Enter position to delete (1 to %d): ", n);
                scanf("%d", &pos);
                if (pos < 1 || pos > n) {
                    printf("Invalid position!\n");
                } else {
                    for (i = pos - 1; i < n - 1; i++)
                        arr[i] = arr[i + 1];
                    n--;
                    printf("Element deleted successfully!\n");
                }
                break;

            case 3:
                // Display
                if (n == 0) {
                    printf("Array is empty.\n");
                } else {
                    printf("Current Array: ");
                    for (i = 0; i < n; i++)
                        printf("%d ", arr[i]);
                    printf("\n");
                }
                break;

            case 4:
                printf("Exiting program...\n");
                break;

            default:
                printf("Invalid choice! Please try again.\n");
        }
    } while (choice != 4);

    return 0;
}

#include "table_formatter.hpp"

#include <iostream>
#include <iomanip>
#include <limits>
#include <sstream>
#include <algorithm>
#include "text_colors.hpp"

namespace TableFormatter {
    // Determines color for time display based on performance relative to min/max
    static const char* getTimeColor(double time, double minTime, double maxTime) {
        if (maxTime <= minTime) return TextColors::RESET;
        double ratio = (time - minTime) / (maxTime - minTime);
        if (ratio < 0.2) return TextColors::GREEN;   // Fastest 20%
        if (ratio > 0.8) return TextColors::RED;     // Slowest 20%
        return TextColors::YELLOW;                     // Middle 60%
    }

    // Prints a formatted table with timing results for all algorithms and sizes
    void printTable(const std::string& typeName,
                    const std::vector<std::vector<double>>& times,
                    const std::vector<std::vector<bool>>& validation,
                    const std::vector<std::string>& algorithmNames,
                    const std::vector<int>& sizes) {
        const int nameWidth = 18;
        const int colWidth = 12;
        const int numSizes = static_cast<int>(sizes.size());
        const int numAlgorithms = static_cast<int>(algorithmNames.size());

        // Print table header
        std::cout << "\n" << TextColors::BRIGHT << TextColors::CYAN
                  << "[ " << typeName << " ARRAYS ]" << TextColors::RESET << "\n";
        std::cout << std::string(80, '-') << "\n";

        std::cout << std::left << std::setw(nameWidth) << "Algorithm";
        for (int i = 0; i < numSizes; ++i) {
            std::cout << std::setw(colWidth) << ("Size " + std::to_string(sizes[i]));
        }
        std::cout << "\n" << std::string(80, '-') << "\n";

        // Print each algorithm's results
        for (int algoIdx = 0; algoIdx < numAlgorithms; ++algoIdx) {
            std::cout << std::left << std::setw(nameWidth) << algorithmNames[algoIdx];

            for (int sizeIdx = 0; sizeIdx < numSizes; ++sizeIdx) {
                // Find min and max times for this size (for color coding)
                double minTime = std::numeric_limits<double>::max();
                double maxTime = 0.0;
                for (int i = 0; i < numAlgorithms; ++i) {
                    if (times[sizeIdx][i] > 0.0) {
                        minTime = std::min(minTime, times[sizeIdx][i]);
                        maxTime = std::max(maxTime, times[sizeIdx][i]);
                    }
                }

                double time = times[sizeIdx][algoIdx];
                bool isValid = validation[sizeIdx][algoIdx];

                // Print time with appropriate color and validation indicator
                if (time > 0.0) {
                    const char* color = getTimeColor(time, minTime, maxTime);
                    std::ostringstream oss;
                    oss << std::fixed << std::setprecision(3) << time << " ms";
                    if (!isValid) {
                        oss << " [!]";  // Mark invalid results
                    }
                    std::cout << color << std::setw(colWidth) << oss.str() << TextColors::RESET;
                } else {
                    std::cout << std::setw(colWidth) << "N/A";
                }
            }
            std::cout << "\n";
        }
        std::cout << "\n";
    }
}

#include <iostream>
