using namespace std;

class Kahraman {
public:
    string ad;
    int can;
    int hasar;

    Kahraman() {
        hasar = 100;
        can = 1000;
    }

    void ozelGuc(Kahraman &rakip) {
        int ozelHasar = hasar * 2;
        rakip.can -= ozelHasar;
        cout << ad << " özel gücünü kullandı!" << rakip.ad 
             << " " << ozelHasar << " hasar aldı!" << endl;
    }
};

int main() {
    Kahraman spiderman;
    spiderman.ad = "spiderman";

    Kahraman batman;
    batman.ad = "batman";

    cout << "Süper kahramanlar kapışıyor!" << endl;
    bool savasbittimi = true;

    while (savasbittimi) {
        char karaktersecimi;
        cout << "\nHangi süperkahraman saldırsın? (s/b) veya özel güç (d/k): ";
        cin >> karaktersecimi;

        if (karaktersecimi == 's') {
            batman.can -= spiderman.hasar;
            cout << "Spiderman saldırdı!️🕷️" << endl;
        }
        else if (karaktersecimi == 'b') {
            spiderman.can -= batman.hasar;
            cout << "Batman saldırdı!🦇" << endl;
        }
        else if (karaktersecimi == 'd') {
            spiderman.ozelGuc(batman);
        }
        else if (karaktersecimi == 'k') {
            batman.ozelGuc(spiderman);
        }
        else {
            cout << "⚠️ Hatalı seçim!" << endl;
        }

        cout << "Spiderman kalan can: " << spiderman.can 
             << " | Batman kalan can: " << batman.can << endl;

        if (spiderman.can <= 0 || batman.can <= 0) {
            savasbittimi = false;
            if (spiderman.can <= 0)
                cout << "\nKazanan: Batman!🦇" << endl;
            else
                cout << "\nKazanan: Spiderman!️🕷️" << endl;
        }
    }

    return 0;

}

#include "../include/handlers/ChatHandler.h"

void ChatHandler::handle(const http::HttpRequest& req, http::HttpResponse* resp)
{

    try
    {

        auto session = server_->getSessionManager()->getSession(req, resp);
        LOG_INFO << "session->getValue(\"isLoggedIn\") = " << session->getValue("isLoggedIn");
        if (session->getValue("isLoggedIn") != "true")
        {

            json errorResp;
            errorResp["status"] = "error";
            errorResp["message"] = "Unauthorized";
            std::string errorBody = errorResp.dump(4);

            server_->packageResp(req.getVersion(), http::HttpResponse::k401Unauthorized,
                "Unauthorized", true, "application/json", errorBody.size(),
                errorBody, resp);
            return;
        }


        int userId = std::stoi(session->getValue("userId"));
        std::string username = session->getValue("username");

        std::string reqFile("../AIApps/ChatServer/resource/AI.html");
        FileUtil fileOperater(reqFile);
        if (!fileOperater.isValid())
        {
            LOG_WARN << reqFile << "not exist.";
            fileOperater.resetDefaultFile();
        }

        std::vector<char> buffer(fileOperater.size());
        fileOperater.readFile(buffer); 
        std::string htmlContent(buffer.data(), buffer.size());


        size_t headEnd = htmlContent.find("</head>");
        if (headEnd != std::string::npos)
        {
            std::string script = "<script>const userId = '" + std::to_string(userId) + "';</script>";
            htmlContent.insert(headEnd, script);
        }

        // server_->packageResp(req.getVersion(), HttpResponse::k200Ok, "OK"
        //             , false, "text/html", htmlContent.size(), htmlContent, resp);
        resp->setStatusLine(req.getVersion(), http::HttpResponse::k200Ok, "OK");
        resp->setCloseConnection(false);
        resp->setContentType("text/html");
        resp->setContentLength(htmlContent.size());
        resp->setBody(htmlContent);
    }
    catch (const std::exception& e)
    {

        json failureResp;
        failureResp["status"] = "error";
        failureResp["message"] = e.what();
        std::string failureBody = failureResp.dump(4);
        resp->setStatusLine(req.getVersion(), http::HttpResponse::k400BadRequest, "Bad Request");
        resp->setCloseConnection(true);
        resp->setContentType("application/json");
        resp->setContentLength(failureBody.size());
        resp->setBody(failureBody);
    }
}

/*
 * Generic Segment Tree for RMQs
 * O(n) construction with O(lg n) queries.
 * T must allow a total ordering <.
 *
 * Author: LELE 
 * Source: https://github.com/jfuentess/edaa/blob/main/rmq/segment_tree.cpp
*/

#ifndef SEGMENT_TREE
#define SEGMENT_TREE

#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <vector>

template<class T>
class segment_tree
{
    private:
        std::vector<T> ST;

        inline T _min(const T &x, const T &y)
        {
            return x < y ? x : y;
        }

    public:
        segment_tree(const std::vector<T> &A)
        {
            if (A.size() == 0) {
                std::cerr << "Invalid input array: must be non-empty." << std::endl;
                std::exit(EXIT_FAILURE);
            }

            uint64_t n, i, j;
            n = A.size();
            ST.resize(n << 1); // Size is 2n

            // Load A as leaves of tree
            for (i = 0; i < n; i++)
                ST[i + n] = A[i];

            // Combine intervals bottom-up
            for (i = n - 1; i > 0; i--) {
                j = i << 1;
                ST[i] = _min(ST[j], ST[j | 1]);
            }
        }

        // Answers min A[i:j] in O(lg n) time
        T RMQ(uint64_t i, uint64_t j)
        {
            uint64_t n = ST.size() >> 1;

            if (i >= j || j > n) {
                std::cerr << "Invalid query " << i << " " << j << std::endl;
                std::exit(EXIT_FAILURE);
            }

            T q = ST[i + n]; // Initialize query result as an element that's always in A[i:j]
            // Go bottom-up combining values in node to answer query
            for (i += n, j += n; i < j; i >>= 1, j >>= 1) {
                if (i & 1)
                    q = _min(q, ST[i++]);
                if (j & 1)
                    q = _min(q, ST[--j]);
            }

            return q;
        }

        // Changes value at index i to x
        void update(uint64_t i, const T x)
        {
            uint64_t n = ST.size() >> 1;

            if (i >= n) {
                std::cerr << "Invalid update " << i << std::endl;
                std::exit(EXIT_FAILURE);
            }

            // Update parent nodes until root
            for (ST[i += n] = x; i > 1; i >>= 1)
                ST[i >> 1] = _min(ST[i], ST[i ^ 1]); // i ^ 1 gives the sibling node to i
        }
};

