#ifdef _WIN32
    // For Windows (Winsock)
    #include <winsock2.h>
    #include <ws2tcpip.h>
    // Link with Ws2_32.lib
    #pragma comment(lib, "Ws2_32.lib")
#else
    // For Linux/macOS (POSIX Sockets)
    #include <sys/socket.h> // For recv, send
    #include <unistd.h>     // For close
#endif

#define BUFFER_SIZE 1024 // 1 kilobyte buffer for reading data

void ConnectionHandler::handle_client(int client_socket) {
    std::cout << "[Thread " << std::this_thread::get_id() 
              << "] Handling new client on socket " << client_socket << std::endl;

    // Create a buffer to store data received from the client
    char buffer[BUFFER_SIZE] = {0}; // Initialize buffer to all zeros

    // server should never crash
    try {
        // Keep handling client requests until they disconnect
        while (true) {
            int bytes_received = 0;

            #ifdef _WIN32
                bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
            #else
                bytes_received = read(client_socket, buffer, BUFFER_SIZE - 1);
            #endif

            if (bytes_received < 0) {
                std::cerr << "[Thread " << std::this_thread::get_id() 
                          << "] Error receiving data on socket " << client_socket << std::endl;
                break;
            }
            else if (bytes_received == 0) {
                std::cout << "[Thread " << std::this_thread::get_id() 
                          << "] Client disconnected from socket " << client_socket << std::endl;
                break;
            }
            else {
                // Null-terminate the received data
                buffer[bytes_received] = '\0';

                std::cout << "[Thread " << std::this_thread::get_id() 
                          << "] Received " << bytes_received << " bytes: " 
                          << std::string(buffer, bytes_received) << std::endl;

                // Echo the message back to the client
                int bytes_sent = 0;
                #ifdef _WIN32
                    bytes_sent = send(client_socket, buffer, bytes_received, 0);
                #else
                    bytes_sent = write(client_socket, buffer, bytes_received);
                #endif

                if (bytes_sent < 0) {
                    std::cerr << "[Thread " << std::this_thread::get_id() 
                              << "] Error sending data on socket " << client_socket << std::endl;
                    break;
                }

                // Clear buffer for next read
                std::fill(buffer, buffer + BUFFER_SIZE, 0);
            }
        }
    } catch (const std::exception& e) {
        std::cerr << "[Thread " << std::this_thread::get_id() 
                  << "] Exception in handle_client: " << e.what() << std::endl;
    } catch (...) {
        std::cerr << "[Thread " << std::this_thread::get_id() 
                  << "] Unknown exception in handle_client" << std::endl;
    }

    // Close the client socket
    #ifdef _WIN32
        closesocket(client_socket);
    #else
        close(client_socket);
    #endif

    std::cout << "[Thread " << std::this_thread::get_id() 
              << "] Closed socket " << client_socket << std::endl;
}

