namespace sjtu {

// ===== helpers =====
void int2048::trim() {
  while (!d_.empty() && d_.back() == 0) d_.pop_back();
  if (d_.empty()) sign_ = 0;
}

int int2048::abs_cmp(const int2048 &a, const int2048 &b) {
  if (a.d_.size() != b.d_.size()) return a.d_.size() < b.d_.size() ? -1 : 1;
  for (int i = (int)a.d_.size() - 1; i >= 0; --i) {
    if (a.d_[i] != b.d_[i]) return a.d_[i] < b.d_[i] ? -1 : 1;
  }
  return 0;
}

void int2048::abs_add_to(std::vector<int> &a, const std::vector<int> &b) {
  size_t n = std::max(a.size(), b.size());
  a.resize(n, 0);
  long long carry = 0;
  for (size_t i = 0; i < n; ++i) {
    long long cur = carry + a[i] + (i < b.size() ? b[i] : 0);
    a[i] = int(cur % BASE);
    carry = cur / BASE;
  }
  if (carry) a.push_back((int)carry);
}

void int2048::abs_sub_from(std::vector<int> &a, const std::vector<int> &b) {
  // assumes |a| >= |b|
  long long carry = 0;
  for (size_t i = 0; i < a.size(); ++i) {
    long long cur = (long long)a[i] - (i < b.size() ? b[i] : 0) - carry;
    if (cur < 0) { cur += BASE; carry = 1; }
    else carry = 0;
    a[i] = int(cur);
  }
  while (!a.empty() && a.back() == 0) a.pop_back();
}

int2048 int2048::mul_naive(const int2048 &a, const int2048 &b) {
  if (a.sign_ == 0 || b.sign_ == 0) return int2048();
  int2048 res;
  res.sign_ = a.sign_ * b.sign_;
  res.d_.assign(a.d_.size() + b.d_.size(), 0);
  for (size_t i = 0; i < a.d_.size(); ++i) {
    long long carry = 0;
    long long ai = a.d_[i];
    for (size_t j = 0; j < b.d_.size() || carry; ++j) {
      long long cur = res.d_[i + j] + ai * 1LL * (j < b.d_.size() ? b.d_[j] : 0) + carry;
      res.d_[i + j] = int(cur % BASE);
      carry = cur / BASE;
    }
  }
  res.trim();
  return res;
}

// FFT multiply using base 1000 packing (3 digits per BASE chunk)
static void fft(std::vector<std::complex<double>> &a, bool invert) {
  size_t n = a.size();
  static std::vector<int> rev;
  static std::vector<std::complex<double>> roots{0, 1};

  if (rev.size() != n) {
    rev.assign(n, 0);
    for (size_t i = 0, j = 0; i < n; ++i) {
      rev[i] = j;
      size_t bit = n >> 1;
      for (; j & bit; bit >>= 1) j ^= bit;
      j ^= bit;
    }
  }
  if (roots.size() < n) {
    size_t k = __builtin_ctz(roots.size());
    roots.resize(n);
    while ((1u << k) < n) {
      double ang = 2 * M_PI / (1u << (k + 1));
      for (size_t i = 1u << (k - 1); i < (1u << k); ++i) {
        roots[2 * i] = roots[i];
        double ang_i = ang * (2 * i + 1 - (1u << k));
        roots[2 * i + 1] = std::complex<double>(cos(ang_i), sin(ang_i));
      }
      ++k;
    }
  }

  for (size_t i = 0; i < n; ++i) if (i < (size_t)rev[i]) std::swap(a[i], a[rev[i]]);
  for (size_t len = 1; len < n; len <<= 1) {
    for (size_t i = 0; i < n; i += 2 * len) {
      for (size_t j = 0; j < len; ++j) {
        std::complex<double> u = a[i + j];
        std::complex<double> v = a[i + j + len] * roots[len + j];
        a[i + j] = u + v;
        a[i + j + len] = u - v;
      }
    }
  }
  if (invert) {
    std::reverse(a.begin() + 1, a.end());
    for (size_t i = 0; i < n; ++i) a[i] /= (double)n;
  }
}

int2048 int2048::mul_fft(const int2048 &a, const int2048 &b) {
  if (a.sign_ == 0 || b.sign_ == 0) return int2048();
  // convert to base 1000 digits
  std::vector<int> x; x.reserve(a.d_.size() * 3);
  for (size_t i = 0; i < a.d_.size(); ++i) {
    int v = a.d_[i];
    x.push_back(v % 1000); v /= 1000;
    x.push_back(v % 1000); v /= 1000;
    x.push_back(v);
  }
  while (!x.empty() && x.back() == 0) x.pop_back();
  std::vector<int> y; y.reserve(b.d_.size() * 3);
  for (size_t i = 0; i < b.d_.size(); ++i) {
    int v = b.d_[i];
    y.push_back(v % 1000); v /= 1000;
    y.push_back(v % 1000); v /= 1000;
    y.push_back(v);
  }
  while (!y.empty() && y.back() == 0) y.pop_back();

  size_t n1 = x.size(), n2 = y.size();
  if (n1 == 0 || n2 == 0) return int2048();
  size_t n = 1; while (n < n1 + n2) n <<= 1;
  std::vector<std::complex<double>> fa(n), fb(n);
  for (size_t i = 0; i < n1; ++i) fa[i] = std::complex<double>(x[i], 0);
  for (size_t i = 0; i < n2; ++i) fb[i] = std::complex<double>(y[i], 0);

  fft(fa, false); fft(fb, false);
  for (size_t i = 0; i < n; ++i) fa[i] *= fb[i];
  fft(fa, true);

  std::vector<long long> c(n);
  for (size_t i = 0; i < n; ++i) c[i] = (long long) llround(fa[i].real());
  long long carry = 0;
  for (size_t i = 0; i < n; ++i) {
    long long cur = c[i] + carry;
    c[i] = cur % 1000;
    carry = cur / 1000;
  }
  while (carry) { c.push_back(carry % 1000); carry /= 1000; }
  while (!c.empty() && c.back() == 0) c.pop_back();

  // pack back to base 1e9 (3 blocks per chunk)
  int2048 res;
  res.sign_ = a.sign_ * b.sign_;
  for (size_t i = 0; i < c.size(); ) {
    long long val = 0;
    long long p = 1;
    for (int k = 0; k < 3 && i < c.size(); ++k, ++i) {
      val += c[i] * p; p *= 1000;
    }
    res.d_.push_back((int)val);
  }
  res.trim();
  return res;
}

