deque<SDL_Point> snakeBody;
enum Dir {
	UP,
	DOWN,
	LEFT,
	RIGHT
};
bool isGameOver;
int playerScore = 0;
Dir curDir = UP;
const int lenSquare = 20;
const int WIN_W = 1600;
const int WIN_H = 900;

struct PointHash {
	size_t operator()(const SDL_Point &p) const noexcept {
		return (static_cast<size_t>(p.x) << 32) ^ static_cast<size_t>(p.y);
	}
};

struct PointEq {
	bool operator()(const SDL_Point& a, const SDL_Point& b) const noexcept {
		return (a.x == b.x) && (a.y == b.y);
	}
};
std::unordered_set<SDL_Point, PointHash, PointEq> occ;


int main(int argc, char* argv[]) {
	SDL_Window* window;
	window = SDL_CreateWindow("Dit me thang nao che game bo", 1600, 900, SDL_WINDOW_RESIZABLE);	
	SDL_Renderer *ren = SDL_CreateRenderer(window, nullptr);

	const int tick_ms = 125;
	Uint64 prev = SDL_GetTicks();
	int acc = 0;

	int COLS = WIN_W / lenSquare, ROWS = WIN_H / lenSquare;

	std::mt19937 rng(std::chrono::steady_clock::now().time_since_epoch().count());

	auto randCell = [&](int maxVal) {
		return std::uniform_int_distribution<int>(0, maxVal - 1)(rng);
	};

	//Food spawner
	auto spawnFood = [&](const std::unordered_set<SDL_Point, PointHash, PointEq>& occupied) {
		while (true) {
			SDL_Point p = { randCell(COLS), randCell(ROWS) };

			if (!occupied.count(p))
				return p;
		}
	};

	//Initial States

	snakeBody.push_back({ COLS / 2, ROWS / 2 });
	snakeBody.push_back({ COLS / 2 - 1, ROWS / 2 });
	snakeBody.push_back({ COLS / 2 - 2, ROWS / 2 });

	for (SDL_Point& p : snakeBody)
		occ.insert(p);

	SDL_Point food = spawnFood(occ);

	bool running = true;
	Dir pending; //wait for event	
	bool hasPending = false; //check if we perform a move

	while (running) {
		SDL_Event e;

		while (SDL_PollEvent(&e)) {
			if (e.type == SDL_EVENT_QUIT) {
				running = false;
			}

			if (e.type == SDL_EVENT_KEY_DOWN) {
				SDL_Scancode sc = e.key.scancode;

				auto turnable = [&](Dir X) -> bool {
					if (curDir == UP && X == DOWN)
						return false;

					if (curDir == DOWN && X == UP)
						return false;

					if (curDir == LEFT && X == RIGHT)
						return false;

					if (curDir == RIGHT && X == LEFT)
						return false;

					return true;
				};

				if (!isGameOver) {
					if (sc == SDL_SCANCODE_W && turnable(UP)) {
						pending = UP;
						hasPending = true;
					}
					else if (sc == SDL_SCANCODE_S && turnable(DOWN)) {
						pending = DOWN;
						hasPending = true;
					}
					else if (sc == SDL_SCANCODE_D && turnable(RIGHT)) {
						pending = RIGHT;
						hasPending = true;
					}
					else if (sc == SDL_SCANCODE_A && turnable(LEFT)) {
						pending = LEFT;
						hasPending = true;
					}
				}

				if (sc == SDL_SCANCODE_ESCAPE) {
					running = false;
				}
			}
		}

		//Timing
		Uint64 now = SDL_GetTicks();

		int dt = static_cast<int>(now - prev);
		prev = now;
		acc += dt;

		while (!isGameOver && acc >= tick_ms) {
			acc -= tick_ms;


			if (hasPending) {
