struct DBuf {
  LGFX* lcd;
  LGFX_Sprite buf[2];
  uint16_t* sprPtr[2];  // Pointers to sprite buffers
  int front = 0, back = 1;
  int w, h;

  void begin(LGFX* d, int width, int height) {
    lcd = d; w = width; h = height;

    lcd->initDMA();

    for (int i=0; i<2; i++) {
      buf[i].setColorDepth(16);
      buf[i].setPsram(true);
      sprPtr[i] = (uint16_t*)buf[i].createSprite(w, h);
      buf[i].fillScreen(TFT_BLACK);
    }
  }

  // draw on the back buffer:
  LGFX_Sprite& canvas() { return buf[back]; }

  // get pointer to back buffer for games
  LGFX* getCanvas() { return (LGFX*)&buf[back]; }

  // show the back buffer and swap
  void present() {
    // Wait for any pending operations
    lcd->waitDisplay();

    // Direct framebuffer swap
    lcd->setAddrWindow(0, 0, w, h);
    lcd->writePixelsDMA(sprPtr[back], w * h);

    // Wait for write
    lcd->waitDisplay();

    // Now safe to swap buffers
    std::swap(front, back);
  }
};

DBuf dbuf;


