    if (x >= centerX - buttonWidth/2 && x <= centerX + buttonWidth/2 &&
        y >= pongY && y <= pongY + buttonHeight) {
        soundSelect();  // Play selection sound
        selectedGame = 0;
        currentState = PLAYING_PONG;
        if (pongGame) delete pongGame;
        // pass back buffer canvas for drawing
        pongGame = new PongGame((LGFX*)&dbuf.canvas());
    }

    // Check Tetris button
    if (x >= centerX - buttonWidth/2 && x <= centerX + buttonWidth/2 &&
        y >= tetrisY && y <= tetrisY + buttonHeight) {
        soundSelect();  // play selection sound
        selectedGame = 1;
        currentState = PLAYING_TETRIS;
        if (tetrisGame) delete tetrisGame;
        // pass back buffer canvas for drawing
        tetrisGame = new TetrisGame((LGFX*)&dbuf.canvas());
    }
}

