    lastPlayed = selection;
    uint8_t fileNumber = base + selection;

    Serial.printf("[AUDIO] Selected %s variation %d (file %04d.mp3), avoiding last: %d\n", 
                  category, selection, fileNumber, (lastPlayed == 255) ? -1 : (int)(lastPlayed));

    return fileNumber;
}

