    // Visual effects
    constexpr float ANIMATION_SPEED = 0.18f;
    constexpr float GLOW_RADIUS = 25.0f;
    constexpr float GLOW_INTENSITY = 0.9f;
    constexpr float CORNER_RADIUS = 14.0f;

    // Tiling
    constexpr int GAP_SIZE = 12;
    constexpr float MASTER_RATIO = 0.58f;

    // Performance
