class Mat4 {
public:
    float m[16];

    Mat4() {
        memset(m, 0, sizeof(m));
        m[0] = m[5] = m[10] = m[15] = 1.0f;
    }

    static Mat4 ortho(float l, float r, float b, float t) {
        Mat4 mat;
        mat.m[0] = 2.0f / (r - l);
        mat.m[5] = 2.0f / (t - b);
        mat.m[10] = -1.0f;
        mat.m[12] = -(r + l) / (r - l);
        mat.m[13] = -(t + b) / (t - b);
        return mat;
    }
};

