        geometry.w += (target.w - geometry.w) * Config::ANIMATION_SPEED;
        geometry.h += (target.h - geometry.h) * Config::ANIMATION_SPEED;

        spawn_anim = std::min(1.0f, spawn_anim + dt * 3.0f);
        focus_anim += ((is_focused ? 1.0f : 0.0f) - focus_anim) * 0.15f;
    }
};

