// Function to find a book by ISBN
int findBookByISBN(int isbns[], int bookCount, int isbn) {
    for (int i = 0; i < bookCount; i++) {
        if (isbns[i] == isbn)
            return i;
    }
    return -1;
}

// Function to add a new book
void addNewBook(int isbns[], char titles[][50], float prices[], int quantities[], int *bookCount) {
    if (*bookCount >= MAX_BOOKS) {
        printf("Inventory full! Cannot add more books.\n");
        return;
    }

    int isbn;
    printf("Enter ISBN: ");
    scanf("%d", &isbn);

    // Check for duplicate ISBN
    if (findBookByISBN(isbns, *bookCount, isbn) != -1) {
        printf("Error: Book with this ISBN already exists!\n");
        return;
    }

    isbns[*bookCount] = isbn;

    printf("Enter Title: ");
    getchar();  // clear newline
    fgets(titles[*bookCount], 50, stdin);
    titles[*bookCount][strcspn(titles[*bookCount], "\n")] = '\0';  // remove newline

    printf("Enter Price: ");
    scanf("%f", &prices[*bookCount]);

    printf("Enter Quantity: ");
    scanf("%d", &quantities[*bookCount]);

    (*bookCount)++;

    printf("Book added successfully!\n");
}

// Function to process a sale
void processSale(int isbns[], int quantities[], int bookCount) {
    int isbn, sold;
    printf("Enter ISBN of book sold: ");
    scanf("%d", &isbn);

    int index = findBookByISBN(isbns, bookCount, isbn);
    if (index == -1) {
        printf("Error: Book not found!\n");
        return;
    }

    printf("Enter number of copies sold: ");
    scanf("%d", &sold);

    if (quantities[index] < sold) {
        printf("Error: Not enough stock available!\n");
    } else {
        quantities[index] -= sold;
        printf("Sale processed successfully. Remaining stock: %d\n", quantities[index]);
    }
}

// Function to generate low-stock report
void generateLowStockReport(int isbns[], char titles[][50], float prices[], int quantities[], int bookCount) {
    printf("\n--- Low Stock Report (Quantity < 5) ---\n");
    int found = 0;

    for (int i = 0; i < bookCount; i++) {
        if (quantities[i] < 5) {
            printf("ISBN: %d | Title: %s | Price: %.2f | Quantity: %d\n",
                   isbns[i], titles[i], prices[i], quantities[i]);
            found = 1;
        }
    }

    if (!found)
        printf("No books are low in stock.\n");
}

