using namespace std;

// Set of C keywords
const unordered_set<string> keywords = {
    "auto", "break", "case", "char", "const", "continue", "default", "do",
    "double", "else", "enum", "extern", "float", "for", "goto", "if",
    "int", "long", "register", "return", "short", "signed", "sizeof", "static",
    "struct", "switch", "typedef", "union", "unsigned", "void", "volatile", "while"};

// Helper: check if character is operator
bool isArithOp(char c)
{
    return c == '+' || c == '-' || c == '*' || c == '/';
}

bool isPunct(char c)
{
    return c == ';' || c == ',' || c == ':';
}

bool isParen(char c)
{
    return c == '(' || c == ')' || c == '{' || c == '}' || c == '[' || c == ']';
}

// Main lexical analyzer function
void lexicalAnalysis(const string &input)
{
    int i = 0;
    int n = input.length();

    // Token storage
    vector<string> keywordList, identifierList, constantList;
    vector<char> arithOpList, punctList, parenList;
    vector<string> logicalOpList;

    unordered_set<string> seenIdentifiers;
    vector<string> duplicateIdentifiers;

    while (i < n)
    {
        // Skip whitespace
        if (isspace(input[i]))
        {
            i++;
            continue;
        }

        // Handle comments
        if (input[i] == '/')
        {
            if (i + 1 < n && input[i + 1] == '/')
            {
                // Single-line comment
                while (i < n && input[i] != '\n')
                    i++;
                continue;
            }
            else if (i + 1 < n && input[i + 1] == '*')
            {
                // Multi-line comment
                i += 2;
                while (i + 1 < n && !(input[i] == '*' && input[i + 1] == '/'))
                {
                    i++;
                }
                if (i + 1 < n)
                    i += 2; // skip */
                continue;
            }
        }

        // Handle identifiers or keywords
        if (isalpha(input[i]) || input[i] == '_')
        {
            string lexeme = "";
            while (i < n && (isalnum(input[i]) || input[i] == '_'))
            {
                lexeme += input[i];
                i++;
            }
            if (keywords.count(lexeme))
            {
                keywordList.push_back(lexeme);
            }
            else
            {
                identifierList.push_back(lexeme);
                if (seenIdentifiers.count(lexeme))
                {
                    if (find(duplicateIdentifiers.begin(), duplicateIdentifiers.end(), lexeme) == duplicateIdentifiers.end())
                        duplicateIdentifiers.push_back(lexeme);
                }
                else
                {
                    seenIdentifiers.insert(lexeme);
                }
            }
            continue;
        }

        // Handle constants (integers only)
        if (isdigit(input[i]))
        {
            string num = "";
            while (i < n && isdigit(input[i]))
            {
                num += input[i];
                i++;
            }
            constantList.push_back(num);
            continue;
        }

        // Handle logical operators (2-char)
        if (i + 1 < n)
        {
            string twoChar = string(1, input[i]) + string(1, input[i + 1]);
            if (twoChar == "==" || twoChar == "!=" || twoChar == "<=" || twoChar == ">=")
            {
                logicalOpList.push_back(twoChar);
                i += 2;
                continue;
            }
        }

