        {
            logicalOpList.push_back(string(1, input[i]));
            i++;
            continue;
        }

        // Handle arithmetic operators
        if (isArithOp(input[i]))
        {
            arithOpList.push_back(input[i]);
            i++;
            continue;
        }

        // Handle assignment (=) — treated as arithmetic operator per your sample
        if (input[i] == '=')
        {
            arithOpList.push_back('=');
            i++;
            continue;
        }

        // Handle punctuation
        if (isPunct(input[i]))
        {
            punctList.push_back(input[i]);
            i++;
            continue;
        }

        // Handle parentheses/brackets
        if (isParen(input[i]))
        {
            parenList.push_back(input[i]);
            i++;
            continue;
        }

        // Skip unknown characters (optional: you can warn)
        i++;
    }

    // Output results
    cout << "Keyword (" << keywordList.size() << "): ";
    for (size_t j = 0; j < keywordList.size(); j++)
    {
        if (j > 0)
            cout << ", ";
        cout << keywordList[j];
    }
