	, LastAppliedTessFactor(16)
	, LastCameraPosition(FVector::ZeroVector)
	, CurrentResolution(32, 32)
	, LastLogTime(0.0)
{
	PrimaryComponentTick.bCanEverTick = true;
	PrimaryComponentTick.bStartWithTickEnabled = true;
	
