//冒泡排序


void bubbleSort(vector<int>& nums)
{
    int n = nums.size();
    for (int i = 0; i < n - 1; i++)
    {
        for (int j = 0; j < n - 1 - i; j++)
        {
            if (nums[j] > nums[j + 1])
            {
                std::swap(nums[j], nums[j + 1]);
            }
        }
    }
}





int main()
{

    std::vector<int> arr = { 64, 34, 25, 12, 22, 11, 90 };
    bubbleSort(arr);

    std::cout << "排序后数组: ";
    for (int num : arr) {
        std::cout << num << " ";
    }
    // 输出：11 12 22 25 34 64 90

}

