// ---------- Criação e inserção ----------
NO* criaNO(int valor) {
    NO* novo = (NO*)malloc(sizeof(NO));
    if (novo == NULL) return NULL;      // Falha de alocação

    novo->valor = valor;
    novo->esq = NULL;
    novo->dir = NULL;
    novo->altura = 0;
    return novo;
}

int alturaNo(NO* no) {
    if (no == NULL) return -1;
    return no->altura;
}

int maior(int a, int b) {
    if (a > b) return a;
    return b;
}

int fatorBalanceamento(NO* no) {
    if (no == NULL) return 0;
    return alturaNo(no->esq) - alturaNo(no->dir);
}

NO* girarDireita(NO* y) {  
   /* Rotação simples à direita  
             y                x  
            / \              / \  
           x   T3   =>      T1  y  
          / \                  / \  
        T1  T2               T2  T3  
   */  

   NO* x = y->esq;
   NO* T2 = x->dir;

   // Executa a rotação
   x->dir = y;
   y->esq = T2;

   // Atualiza as alturas
   y->altura = maior(alturaNo(y->esq), alturaNo(y->dir)) + 1;
   x->altura = maior(alturaNo(x->esq), alturaNo(x->dir)) + 1;

   return x;
}  

NO* girarEsquerda(NO* x) {  
   /* Rotação simples à esquerda  
           x                    y  
          / \                  / \  
         T1  y      =>        x  T3  
            / \              / \  
           T2 T3            T1 T2  
   */  

   NO* y = x->dir;
   NO* T2 = y->esq;

   // Executa a rotação
   y->esq = x;
   x->dir = T2;

   // Atualiza as alturas
   x->altura = maior(alturaNo(x->esq), alturaNo(x->dir)) + 1;
   y->altura = maior(alturaNo(y->esq), alturaNo(y->dir)) + 1;

   return y;
}

NO* insereArvore(NO* no, int valor) {
    /* Inserção binária normal ----------------------------- */
    if (no == NULL) {
        return criaNO(valor);
    }

    if (valor < no->valor) {
        no->esq = insereArvore(no->esq, valor);
    }
    else if (valor > no->valor) {
        no->dir = insereArvore(no->dir, valor);
    }
    else {
        /* Valor já existe – não insere duplicado */
        return no;
    }

    /* Atualiza altura do nó */
    int altEsq = alturaNo(no->esq);
    int altDir = alturaNo(no->dir);
    no->altura = maior(altEsq, altDir) + 1;

