// ---------- Blender-friendly math helpers (row-major, column-vector semantics) ----------
struct Mat4 {
    float m[16];
};

inline Mat4 mat4_identity() {
    Mat4 M{};
    M.m[0] = M.m[5] = M.m[10] = M.m[15] = 1.0f;
    return M;
}

inline Mat4 mat4_mul(const Mat4& A, const Mat4& B) {
    Mat4 C{};
    for (int r = 0; r < 4; ++r) {
        for (int c = 0; c < 4; ++c) {
            float sum = 0.0f;
            for (int k = 0; k < 4; ++k) {
                sum += A.m[r * 4 + k] * B.m[k * 4 + c];
            }
            C.m[r * 4 + c] = sum;
        }
    }
    return C;
}

// +90 deg rotation about X (Y-up -> Z-up). Maps (x, y, z)_Yup -> (x, -z, y)_Zup
inline Mat4 mat4_rx90() {
    Mat4 R = mat4_identity();
    R.m[5] = 0.0f;
    R.m[6] = -1.0f;
    R.m[9] = 1.0f;
    R.m[10] = 0.0f;
    return R;
}

// OpenGL perspective (gluPerspective equivalent), row-major layout
inline Mat4 perspective_opengl_row_major(float fovy_deg, float aspect, float zn, float zf) {
    const float f = 1.0f / std::tan(fovy_deg * 0.5f * physics::PI_F / 180.0f);
    Mat4 P{};
    P.m[0] = f / aspect;
    P.m[5] = f;
    P.m[10] = (zf + zn) / (zn - zf);
    P.m[11] = -1.0f;
    P.m[14] = (2.0f * zf * zn) / (zn - zf);
    return P;
}

// Build camera->world in current Y-up world (columns = right, up, -forward; last column = eye)
inline Mat4 cam2world_yup_from_basis(const float eye[3],
                                     const float right[3],
                                     const float up_cam[3],
                                     const float forward[3]) {
    Mat4 T = mat4_identity();
    // Columns = right, up, -forward, eye; store column-wise in row-major memory
    T.m[0]  = right[0];   T.m[4]  = right[1];   T.m[8]  = right[2];
    T.m[1]  = up_cam[0];  T.m[5]  = up_cam[1];  T.m[9]  = up_cam[2];
    T.m[2]  = -forward[0];T.m[6]  = -forward[1];T.m[10] = -forward[2];

    T.m[3]  = eye[0];
    T.m[7]  = eye[1];
    T.m[11] = eye[2];
    return T;
}

