//              INSERTION AT HEAD
// ================================================



void insertAtHead(Node* &head,Node*&tail, int d){
    Node*temp=new Node(d);
    // if head is NULL
    if(head==NULL){
        head=temp;
        tail=temp;
        tail -> next = head;
        return;
    }

    temp -> next = head;
    head=temp;
    tail->next=head;
}



// ================================================
//              INSERTION AT TAIL
// ================================================

 void insertAtTail(Node*&head, Node*&tail,int d){
    Node*temp=new Node(d);
    if(head==NULL){
        head=temp;
        tail=temp;
        tail->next=head;
        return;
    }
    tail -> next = temp;
    temp -> next = head;
    tail = temp;
 }






// ================================================
//              INSERTION AT POSITION
// ================================================


void insertAtPosition(Node*&head,Node*&tail,int position,int d){
    // if posiiton is 1
    if(position==1){
        insertAtHead(head,tail,d);
        return;
    }

    // Traversing
    Node*temp=head;
    int cnt=1;
    while(cnt<position-1 && temp -> next !=head){
         temp=temp -> next;
         cnt++;
    }

    // Last position
    if(temp==tail){
        insertAtTail(head,tail,d);
        return;
    }

    // middle 
    Node* newNode = new Node(d);
    newNode -> next = temp -> next;
    temp -> next = newNode;

}




