        return;
    }

    // if a single node
    if(head==tail){
        delete head;
        head=NULL;
        tail=NULL;
        return;
    }

    // If more than one nodes
    Node*temp=head;
    head=head -> next;
    tail -> next = head;
    temp -> next = NULL;
    delete temp;
 }



