void deleteAtTail(Node*&head,Node*&tail){
    // empty list
    if(head==NULL){
        cout<<"List is empty "<<endl;
        return;
    }

    // if a single node
    if(head==tail){
        delete head;
        head=NULL;
        tail=NULL;
        return;
    }

    // more nodes
    Node*temp=head;
    while(temp->next!=tail){
        temp=temp->next;
    }

    temp->next=head;
    delete tail;
    tail=temp;

}



