struct TimerON {
  unsigned long t = 0;
  bool a = false;
  bool f = false;

  void set(unsigned long d) {
    if (!a) { t = millis() + d; a = true; f = false; }
  }

  bool done() {
    if (a && !f && millis() >= t) f = true;
    return f;
  }

  void reset() { a = false; f = false; }
};
TimerON TON[50]; 

// ===================== TIMERS TON ======================
struct TimerOFF {
  unsigned long t = 0;
  bool activo = false;

  void set(unsigned long d) {
    t = millis() + d;
    activo = true;
  }

  bool ON() {
    if (activo && millis() > t) {
      activo = false;
    }
    return activo;
  }
};
