// Cross-platform exec function (captures stdout)
std::string exec(const std::string &cmd) {
    std::array<char, 256> buffer;
    std::string result;

#if defined(_WIN32)
    FILE* pipe = _popen(cmd.c_str(), "r");
#else
    FILE* pipe = popen(cmd.c_str(), "r");
#endif

    if (!pipe) throw std::runtime_error("popen() failed!");

    while (fgets(buffer.data(), static_cast<int>(buffer.size()), pipe) != nullptr) {
        result += buffer.data();
    }

#if defined(_WIN32)
    _pclose(pipe);
#else
    pclose(pipe);
#endif

    return result;
}

// Download a single video with yt-dlp
void download_video(const std::string &url, const std::string &outdir) {
    std::stringstream cmd;

#if defined(_WIN32)
    // 🟩 FIX: escape all '%' as '%%' to prevent cmd.exe variable expansion
    // 🟩 Also remove "cmd /C" — directly calling yt-dlp is safer and cleaner
    cmd << "yt-dlp -o \"" << outdir
        << "\\%%(playlist_index)s - %%(title)s.%%(ext)s\" "
        << "-f \"bestvideo[ext=mp4]+bestaudio[ext=m4a]/best\" "
        << "\"" << url << "\"";
#else
    cmd << "yt-dlp -o \"" << outdir
        << "/%(playlist_index)s - %(title)s.%(ext)s\" "
        << "-f \"bestvideo[ext=mp4]+bestaudio[ext=m4a]/best\" "
        << "\"" << url << "\"";
#endif

    std::string final_cmd = cmd.str();

    // 🐞 Debug info
    std::cout << "\n--------------------------------------------------" << std::endl;
    std::cout << "🎬 Starting download task" << std::endl;
    std::cout << "📄 URL      : " << url << std::endl;
    std::cout << "📁 OutputDir: " << outdir << std::endl;
    std::cout << "💻 Command  : " << final_cmd << std::endl;
    std::cout << "--------------------------------------------------" << std::endl;

    // Execute the command and check result
    int ret = std::system(final_cmd.c_str());

    if (ret == 0) {
        std::cout << "✅ Download completed successfully for: " << url << std::endl;
    } else {
        std::cerr << "❌ Download failed for: " << url << std::endl;
        std::cerr << "⚠️ Exit code: " << ret << std::endl;
    }

    std::cout << "--------------------------------------------------\n" << std::endl;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <playlist_url> <output_dir> [concurrency=4]\n";
        return 1;
    }

    std::string playlist_url = argv[1];
    std::string outdir = argv[2];
    int concurrency = (argc >= 4) ? std::stoi(argv[3]) : 4;

    // Check if yt-dlp is available
    if (std::system("yt-dlp --version >nul 2>&1") != 0) {
        std::cerr << "❗ yt-dlp not found! Please install it first (pip install yt-dlp)." << std::endl;
        return 1;
    }

    fs::create_directories(outdir);

    // Step 1: Dump playlist JSON
    std::string dump_cmd = "yt-dlp --flat-playlist --dump-single-json \"" + playlist_url + "\"";
    std::cout << "📋 Fetching playlist metadata..." << std::endl;

    std::string json_output;
    try {
        json_output = exec(dump_cmd);
    } catch (const std::exception &e) {
        std::cerr << "Error executing yt-dlp: " << e.what() << std::endl;
        return 1;
    }

    // Step 2: Parse JSON
    json playlist;
    try {
        playlist = json::parse(json_output);
    } catch (std::exception &e) {
        std::cerr << "❌ Failed to parse playlist JSON: " << e.what() << std::endl;
        return 1;
    }

    std::vector<std::string> urls;
    for (auto &entry : playlist["entries"]) {
        if (entry.contains("url")) {
            urls.push_back(entry["url"]);
        } else if (entry.contains("id")) {
            urls.push_back("https://www.youtube.com/watch?v=" + entry["id"].get<std::string>());
        }
    }

    std::cout << "✅ Found " << urls.size() << " videos." << std::endl;

    // Step 3: Download in parallel
    std::vector<std::future<void>> tasks;
    for (size_t i = 0; i < urls.size(); ++i) {
        if (tasks.size() >= (size_t)concurrency) {
            tasks.front().get();  // Wait for one to finish
            tasks.erase(tasks.begin());
        }
        tasks.push_back(std::async(std::launch::async, download_video, urls[i], outdir));
    }

    for (auto &t : tasks) {
        t.get();
    }

    std::cout << "\n🎉 All downloads completed successfully!" << std::endl;

#if defined(_WIN32)
    system("pause");
#endif

    return 0;
}

