// Template RAII pour handles
template<typename T, typename Deleter>
class AutoHandle {
    T handle;
    Deleter deleter;
public:
    AutoHandle(T h, Deleter d) : handle(h), deleter(d) {}
    ~AutoHandle() { if (handle && handle != INVALID_HANDLE_VALUE) deleter(handle); }
    T get() const { return handle; }
    operator bool() const { return handle != INVALID_SOCKET && handle != INVALID_HANDLE_VALUE; }
    AutoHandle(const AutoHandle&) = delete;
    AutoHandle& operator=(const AutoHandle&) = delete;
};

