Token Parser::getCurrentToken() const {
    if (current >= tokens.size()) {
        return Token(TokenType::END_OF_FILE, "", 0, 0);
    }
    return tokens[current];
}

Token Parser::peekToken(size_t offset) const {
    size_t peekIndex = current + offset;
    if (peekIndex >= tokens.size()) {
        return Token(TokenType::END_OF_FILE, "", 0, 0);
    }
    return tokens[peekIndex];
}

bool Parser::isAtEnd() const {
    return current >= tokens.size() || getCurrentToken().getType() == TokenType::END_OF_FILE;
}

Token Parser::advance() {
    if (!isAtEnd()) {
        current++;
    }
    return tokens[current - 1];
}

bool Parser::check(TokenType type) const {
    if (isAtEnd()) return false;
    return getCurrentToken().getType() == type;
}

bool Parser::match(TokenType type) {
    if (check(type)) {
        advance();
        return true;
    }
    return false;
}

bool Parser::match(const std::vector<TokenType>& types) {
    for (TokenType type : types) {
        if (check(type)) {
            advance();
            return true;
        }
    }
    return false;
}

Token Parser::consume(TokenType type, const std::string& message) {
    if (check(type)) {
        return advance();
    }

    Token current = getCurrentToken();
    throw ParseError(message, current.getLine(), current.getColumn());
}

void Parser::synchronize() {
    advance();

    while (!isAtEnd()) {
        if (tokens[current - 1].getType() == TokenType::SEMICOLON) return;

        switch (getCurrentToken().getType()) {
            case TokenType::IF:
            case TokenType::WHILE:
            case TokenType::FOR:
            case TokenType::RETURN:
            case TokenType::INT:
            case TokenType::FLOAT:
            case TokenType::CHAR:
            case TokenType::VOID:
                return;
            default:
                break;
        }

        advance();
    }
}

std::shared_ptr<Program> Parser::parse() {
    try {
        return parseProgram();
    } catch (const ParseError& e) {
        synchronize();
        throw;
    }
}

std::shared_ptr<Program> Parser::parseProgram() {
    auto program = std::make_shared<Program>();

    while (!isAtEnd()) {
        if (getCurrentToken().getType() == TokenType::NEWLINE) {
            advance();
            continue;
        }

        try {
            auto declaration = parseDeclaration();
            if (declaration) {
                program->addDeclaration(declaration);
            }
        } catch (const ParseError& e) {
            synchronize();
        }
    }

    return program;
}

