// Alle Wochentage in denen Schule ist
enum class Wochentag : uint8_t
{
  Montag,
  Dienstag,
  Mittwoch,
  Donnerstag,
  Freitag,
  Anzahl // Hilfswert für Arraygröße
};

struct Reihe
{
  std::string klasse;
  Wochentag tag;
  uint8_t stunde_start;
  uint8_t stunde_ende;
  uint8_t staerke; // Klassenstärke
};

struct Tabelle
{
  std::vector<Reihe> reihen;
};

struct Ergebnis
{
  uint16_t anzahl;
  Wochentag tag;
  uint16_t uhrzeit;
};

Ergebnis
rechnen (const Tabelle &tabelle)
{
  Ergebnis ergebnis{ 0, Wochentag::Montag, 0 };

  // 24 Stunden * 5 Wochentage
  std::array<std::array<uint16_t, static_cast<size_t> (Wochentag::Anzahl)>, 24>
      werte{};

  for (const auto &reihe : tabelle.reihen)
    {
      int tag = static_cast<int> (reihe.tag);
      if (tag < 0 || tag >= static_cast<int> (Wochentag::Anzahl))
        {
          std::cerr << "Ungültiger Wochentag-Index: " << tag << std::endl;
          exit (1);
        }

      for (int i = static_cast<int> (reihe.stunde_start);
           i < static_cast<int> (reihe.stunde_ende) && i < 24; ++i)
        {
          werte[i][tag] += reihe.staerke;
        }
    }

  for (size_t i = 0; i < werte.size (); ++i)
    {
      for (size_t j = 0; j < werte[i].size (); ++j)
        {
          if (werte[i][j] > ergebnis.anzahl)
            {
              ergebnis.anzahl = werte[i][j];
              ergebnis.tag = static_cast<Wochentag> (j);
              ergebnis.uhrzeit = i;
            }
        }
    }

  return ergebnis;
}

std::string
enumeration_zu_text (Wochentag t)
{
  switch (t)
    {
    case Wochentag::Montag:
      return "Montag";
    case Wochentag::Dienstag:
      return "Dienstag";
    case Wochentag::Mittwoch:
      return "Mittwoch";
    case Wochentag::Donnerstag:
      return "Donnerstag";
    case Wochentag::Freitag:
      return "Freitag";
    default:
      return "Unbekannt";
    }
}

Tabelle
lesen (const std::string name)
{
  std::vector<std::string> daten;
  std::ifstream datei (name);
  if (!datei.is_open ())
    {
      std::cerr << "Fehler beim Öffnen der Datei: " << name << std::endl;
      exit (1);
    }

  std::string zeile;

  std::string dummy;
  std::getline (datei, dummy); // erste Zeile ignorieren

  while (std::getline (datei, zeile))
    {
      daten.push_back (zeile);
    }

  datei.close ();

  Tabelle tabelle;

  for (const auto &zeile : daten)
    {
      Reihe reihe;
      std::string tag; // jetzt String, nicht char!
      uint16_t start, ende, staerke_val;

      std::istringstream iss (zeile);
      iss >> reihe.klasse >> tag >> start >> ende >> staerke_val;
      reihe.stunde_start = start;
      reihe.stunde_ende = ende;
      reihe.staerke = staerke_val;

      if (tag == "Montag")
        reihe.tag = Wochentag::Montag;
      else if (tag == "Dienstag")
        reihe.tag = Wochentag::Dienstag;
      else if (tag == "Mittwoch")
        reihe.tag = Wochentag::Mittwoch;
      else if (tag == "Donnerstag")
        reihe.tag = Wochentag::Donnerstag;
      else if (tag == "Freitag")
        reihe.tag = Wochentag::Freitag;
      else
        {
          std::cerr << "Ungültiger Wochentag: " << tag << std::endl;
          exit (1);
        }

      tabelle.reihen.push_back (reihe);
    }

  return tabelle;
}

