  color_snake_ = lv_color_hex(0x00FF00);   // Green
  color_pickup_ = lv_color_hex(0xFF0000);  // Red
  color_bg_ = lv_color_hex(0x000000);      // Black
  color_border_ = lv_color_hex(0x404040);  // Dark gray
