void StartNextRound(Stopwatch& stopwatch)
{
		// グローバル変数を更新するだけ
		if (roundNumber == 0) {
			baseChar = U"シ";
			correctChar = U"ン";
		}
		else if (roundNumber == 1) {
			baseChar = U"新";
			correctChar = U"親";
		}
		else if (roundNumber == 2) {
			baseChar = U"真";
			correctChar = U"眞";
		}
	if (roundNumber >= 3)
	{
		isGameFinished = true;
		return;
	}
