	const double height = Scene::Height();
	const double charWidth = 40;
	const double charHeight = 40;
	const double padding = 7.0; // 文字同士の余白
	for (int i = 0; i < totalChars; i++)
	{
		Vec2 newPos;
		RectF newRect;
		bool valid = false;
		int tries = 0;

		// 重なりを避けてランダム配置
		while (!valid && tries < 500)
		{
			newPos = Vec2{
				Random(50.0, width - 100.0),
				Random(100.0, height - 100.0)
			};
			newRect = RectF{ newPos, charWidth + padding, charHeight + padding };
			valid = true;

			for (const auto& p : positions)
			{
				RectF existingRect{ p, charWidth + padding, charHeight + padding };
				if (newRect.intersects(existingRect))
				{
					valid = false;
					break;
				}
			}
			tries++;
		}
		positions << newPos;
	}
