};

Deck::Deck(int s) : size(s) {
    vector<int> numbers;

    // Generate pairs of numbers for StandardCards (1 to 8)
    for (int i = 1; i <= (size - 4) / 2; i++) {
        numbers.push_back(i);
        numbers.push_back(i);
    }

    // Add 2 BonusCards (value 7) and 2 PenaltyCards (value 8)
    numbers.push_back(7);
    numbers.push_back(7);
    numbers.push_back(8);
    numbers.push_back(8);

    // Shuffle the numbers
    random_shuffle(numbers.begin(), numbers.end());

    // Allocate memory for the cards
    cards = new Card*[size];
    for (int i = 0; i < size; i++) {
        if (numbers[i] == 7)
            cards[i] = new BonusCard(numbers[i]);
        else if (numbers[i] == 8)
            cards[i] = new PenaltyCard(numbers[i]);
        else
            cards[i] = new StandardCard(numbers[i]);
    }

    shuffle();
}


Deck::~Deck() {
    for (int i = 0; i < size; i++)
        delete cards[i];
    delete[] cards;
}

void Deck::shuffle() {
    for (int i = 0; i < size; i++) {
        int j = rand() % size;
        swap(cards[i], cards[j]);
    }
}


