            cout << "Not enough balance available!\n";
        } else {
            balance -= amount;
            cout << "Amount Withdrawn Successfully.\n";
            cout << "Remaining Balance: Rs." << balance << "\n";
        }
    }

    void checkBalance() {
        if (!accountCreated) {
            cout << "No account found! Please create an account first.\n";
            return;
        }

        cout << "\nCurrent Balance: Rs." << balance << "\n";
