static thread_local MouseProcHook* tlsInstance = nullptr;
static HHOOK sHook = nullptr;

LRESULT CALLBACK MouseProcHook::LowLevelMouseProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == HC_ACTION && tlsInstance) {
        auto* p = reinterpret_cast<MSLLHOOKSTRUCT*>(lParam);
        if (p && (p->flags & (LLMHF_INJECTED | 0x2)) == 0) {
            if (wParam == WM_LBUTTONDOWN) tlsInstance->mouseDown.store(true,  std::memory_order_release);
            else if (wParam == WM_LBUTTONUP) tlsInstance->mouseDown.store(false, std::memory_order_release);
        }
    }
    return CallNextHookEx(sHook, nCode, wParam, lParam);
}

DWORD WINAPI MouseProcHook::ThreadProc(LPVOID param) {
    tlsInstance = static_cast<MouseProcHook*>(param);

    sHook = SetWindowsHookExW(WH_MOUSE_LL, LowLevelMouseProc, nullptr, 0);
    if (!sHook) return 0;

    MSG msg;
    while (GetMessageW(&msg, nullptr, 0, 0) > 0) {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    UnhookWindowsHookEx(sHook);
    sHook = nullptr;
    tlsInstance = nullptr;
    return 0;
}

void MouseProcHook::enable() {
    hThread = CreateThread(nullptr, 0, ThreadProc, this, 0, &threadId);
}

void MouseProcHook::disable() {
    if (!hThread) return;
    PostThreadMessageW(threadId, WM_QUIT, 0, 0);
    WaitForSingleObject(hThread, 3000);
    CloseHandle(hThread);
    hThread = nullptr;
}

#include <iostream>
using namespace std;

struct Element {
    int valeur;
    Element* suivant;
};

class Liste {
private:
    Element* tete; // pointeur sur le premier élément

public:
    Liste() { // constructeur
        tete = nullptr;
    }

    ~Liste() { // destructeur pour éviter fuite mémoire
        while (tete != nullptr) {
            Element* temp = tete;
            tete = tete->suivant;
            delete temp;
        }
    }

    void ajouterDebut(int v) {
        Element* nouveau = new Element;
        nouveau->valeur = v;
        nouveau->suivant = tete;
        tete = nouveau;
    }

    void supprimerDebut() {
        if (tete == nullptr) {
            cout << "La liste est vide, rien à supprimer." << endl;
        } else {
            Element* temp = tete;
            tete = tete->suivant;
            delete temp;
        }
    }

    void afficher() {
        Element* courant = tete;
        cout << "Liste : ";
        while (courant != nullptr) {
            cout << courant->valeur << " -> ";
            courant = courant->suivant;
        }
        cout << "NULL" << endl;
    }
};
int main() {
    Liste maListe;

    maListe.ajouterDebut(10);
    maListe.ajouterDebut(20);
    maListe.ajouterDebut(30);

    maListe.afficher();  // affiche : 30 -> 20 -> 10 -> NULL

    maListe.supprimerDebut();
    maListe.afficher();  // affiche : 20 -> 10 -> NULL

    maListe.supprimerDebut();
    maListe.supprimerDebut();
    maListe.supprimerDebut(); // essaie de supprimer quand c’est vide

    return 0;
}

