{
	CastamFraction result;

	if (right.getNumerator() == 0) {
		cout << "Error: division by zero!" << endl;
		return result; 
	}

	result.setNumerator(
		left.getNumerator() * right.getDenumerator()
	);
	result.setDenumerator(
		left.getDenumerator() * right.getNumerator()
	);
	return result;
}

