#endif

static bool file_exists(const std::string &path) {
    struct stat st;
    return stat(path.c_str(), &st) == 0 && S_ISREG(st.st_mode);
}

static std::string read_file(const std::string &path, bool &ok) {
    ok = false;
    std::ifstream in(path, std::ios::binary);
    if (!in) return {};
    std::ostringstream ss;
    ss << in.rdbuf();
    ok = true;
    return ss.str();
}

#if defined(_WIN32)

bool copy_to_clipboard_windows(const std::string &text) {
    if (!OpenClipboard(NULL)) return false;
    EmptyClipboard();

    // Convert UTF-8 std::string to UTF-16
    int wlen = MultiByteToWideChar(CP_UTF8, 0, text.c_str(), (int)text.size(), NULL, 0);
    if (wlen == 0) { CloseClipboard(); return false; }
    HGLOBAL hGlob = GlobalAlloc(GMEM_MOVEABLE, (wlen + 1) * sizeof(wchar_t));
    if (!hGlob) { CloseClipboard(); return false; }
    wchar_t *wbuf = (wchar_t*)GlobalLock(hGlob);
    MultiByteToWideChar(CP_UTF8, 0, text.c_str(), (int)text.size(), wbuf, wlen);
    wbuf[wlen] = 0;
    GlobalUnlock(hGlob);

    if (SetClipboardData(CF_UNICODETEXT, hGlob) == NULL) {
        GlobalFree(hGlob);
        CloseClipboard();
        return false;
    }

    CloseClipboard();
    return true;
}

#elif defined(__APPLE__)

bool copy_to_clipboard_macos(const std::string &text) {
    // Use pbcopy. Write to its stdin.
    FILE *p = popen("pbcopy", "w");
    if (!p) return false;
    size_t written = fwrite(text.data(), 1, text.size(), p);
    int rc = pclose(p);
    return written == text.size() && rc == 0;
}

#else // Linux / other Unix

bool copy_to_clipboard_xclip(const std::string &text) {
    // Try xclip first
    FILE *p = popen("xclip -selection clipboard -in 2>/dev/null", "w");
    if (!p) return false;
    size_t written = fwrite(text.data(), 1, text.size(), p);
    int rc = pclose(p);
    return written == text.size() && rc == 0;
}

bool copy_to_clipboard_xsel(const std::string &text) {
    FILE *p = popen("xsel --clipboard --input 2>/dev/null", "w");
    if (!p) return false;
    size_t written = fwrite(text.data(), 1, text.size(), p);
    int rc = pclose(p);
    return written == text.size() && rc == 0;
}

#endif

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage:\n  clpbrd <text...>\n  clpbrd <file-path>\n";
        return 2;
    }

    // Build input string from argv[1..]
    std::string combined;
    // If only one arg and it's a path to an existing file, read file content
    if (argc == 2) {
        std::string single = argv[1];
        // Allow @prefix to explicitly indicate file if desired
        if (!single.empty() && single.front() == '@') {
            std::string path = single.substr(1);
            bool ok;
            std::string content = read_file(path, ok);
            if (!ok) { std::cerr << "Error: cannot read file: " << path << "\n"; return 3; }
            combined = content;
        } else if (file_exists(single)) {
            bool ok;
            std::string content = read_file(single, ok);
            if (!ok) { std::cerr << "Error: cannot read file: " << single << "\n"; return 3; }
            combined = content;
        } else {
            combined = single;
        }
    } else {
        // Multiple args: treat as literal text joined by spaces
        std::ostringstream ss;
        for (int i = 1; i < argc; ++i) {
            if (i > 1) ss << ' ';
            ss << argv[i];
        }
        combined = ss.str();
    }

    if (combined.empty()) {
        std::cerr << "Warning: nothing to copy (empty string).\n";
        return 0;
    }

    bool ok = false;
#if defined(_WIN32)
    ok = copy_to_clipboard_windows(combined);
#elif defined(__APPLE__)
    ok = copy_to_clipboard_macos(combined);
#else
    // Try xclip, then xsel
    ok = copy_to_clipboard_xclip(combined);
    if (!ok) ok = copy_to_clipboard_xsel(combined);
    if (!ok) {
        // As a last resort, try wl-copy (Wayland)
        FILE *p = popen("wl-copy 2>/dev/null", "w");
        if (p) {
            size_t written = fwrite(combined.data(), 1, combined.size(), p);
            int rc = pclose(p);
            ok = (written == combined.size() && rc == 0);
        }
    }
#endif

    if (!ok) {
        std::cerr << "Error: failed to copy to clipboard. Ensure clipboard utility is available.\n";
        return 4;
    }

    return 0;
}

