// FFT size must be power of 2 (width and height can differ!)
static_assert((GRID_WIDTH & (GRID_WIDTH - 1)) == 0, "Grid width must be power of 2 for FFT");
static_assert((GRID_HEIGHT & (GRID_HEIGHT - 1)) == 0, "Grid height must be power of 2 for FFT");

LeniaCore::LeniaCore(std::shared_ptr<Kernel> kernel, float mu, float sigma)
    : kernel_(kernel)
    , cells_(nullptr)
    , potential_(nullptr)
    , temp_buffer_(nullptr)
    , cells_fft_(nullptr)
    , kernel_fft_(nullptr)
    , fft_scratch_(nullptr)
    , fft_table_(nullptr)
    , generation_(0)
    , time_(0.0f)
    , mu_(mu)
    , sigma_(sigma)
{
    if (!kernel_) {
        Serial.println("ERROR: Kernel is null!");
        return;
    }

    const size_t fft_complex_size = GRID_SIZE * 2;  // Complex: real + imag

    Serial.printf("Allocating FFT buffers (grid=%dx%d)...\n", GRID_WIDTH, GRID_HEIGHT);
    Serial.printf("Free heap before: %d bytes\n", ESP.getFreeHeap());

    // Allocate core buffers
    cells_ = static_cast<uint8_t*>(malloc(GRID_SIZE));
    potential_ = static_cast<float*>(malloc(GRID_SIZE * sizeof(float)));
    temp_buffer_ = static_cast<float*>(malloc(GRID_SIZE * sizeof(float)));

    // Allocate FFT buffers
    cells_fft_ = static_cast<float*>(malloc(fft_complex_size * sizeof(float)));
    kernel_fft_ = static_cast<float*>(malloc(fft_complex_size * sizeof(float)));
    fft_scratch_ = static_cast<float*>(malloc(fft_complex_size * sizeof(float)));

    if (!cells_ || !potential_ || !temp_buffer_ ||
        !cells_fft_ || !kernel_fft_ || !fft_scratch_) {
        Serial.println("ERROR: Failed to allocate buffers!");
        return;
    }

    Serial.printf("Buffers allocated, Free heap: %d bytes\n", ESP.getFreeHeap());

    // Initialize FFT
    initFFT();

    // Initialize lookup table
    initGrowthLUT();

    // Clear buffers
    memset(cells_, 0, GRID_SIZE);
    memset(potential_, 0, GRID_SIZE * sizeof(float));

    Serial.printf("LeniaCore initialized: %dx%d grid\n", GRID_WIDTH, GRID_HEIGHT);
}

LeniaCore::~LeniaCore() {
    if (cells_) free(cells_);
    if (potential_) free(potential_);
    if (temp_buffer_) free(temp_buffer_);
    if (cells_fft_) free(cells_fft_);
    if (kernel_fft_) free(kernel_fft_);
    if (fft_scratch_) free(fft_scratch_);

    // Deinit FFT tables
    dsps_fft2r_deinit_fc32();
}

void LeniaCore::initialize(const char* rle) {
    reset();

    if (rle) {
        // Decode RLE string to cells
        Serial.println("Decoding RLE pattern...");
        if (decodeRLE(rle, cells_, GRID_WIDTH, GRID_HEIGHT)) {
            Serial.printf("RLE decoded successfully, mass=%.2f\n", getMass());
        } else {
            Serial.println("RLE decode failed, using fallback pattern");
            loadOrbiumPattern();
        }
    } else {
        // Load fallback pattern
        Serial.println("No RLE provided, using fallback pattern");
        loadOrbiumPattern();
    }
}

void LeniaCore::reset() {
    memset(cells_, 0, GRID_SIZE);
    memset(potential_, 0, GRID_SIZE * sizeof(float));
    generation_ = 0;
    time_ = 0.0f;
}

void LeniaCore::step() {
    // 1. Convolve cells with kernel -> potential
    convolve();

    // Debug: Check center and max potential on first few steps
    if (generation_ < 3) {
        uint16_t center_idx = (GRID_HEIGHT / 2) * GRID_WIDTH + (GRID_WIDTH / 2);

        // Find max potential
        float max_pot = 0.0f;
        uint16_t max_idx = 0;
        for (uint16_t i = 0; i < GRID_SIZE; ++i) {
            if (potential_[i] > max_pot) {
                max_pot = potential_[i];
                max_idx = i;
            }
        }

        Serial.printf("  [Gen %u] Center: cell=%u, pot=%.4f, growth=%.4f | Max pot=%.4f at cell=%u\n",
                      generation_, cells_[center_idx], potential_[center_idx],
                      growthFunction(potential_[center_idx]), max_pot, cells_[max_idx]);
    }

    // 2. Update cells using growth function
    updateCells();

    // Update state
    ++generation_;
    time_ += DT;
}

void LeniaCore::update(uint8_t steps) {
    for (uint8_t i = 0; i < steps; ++i) {
        step();
    }
}

